// Legacy ABI discovery gate retained for historical diagnostics. This file
// intentionally uses the project's *minimal* libretro definitions, while the
// official Vulkan interface types are isolated in AzaharOfficialVulkanABI.mm.
// The AZ115 flags below describe ONLY the early, private prototype and remain
// false; they must not be confused with the later LIVE hardware implementation
// (v187+). Discovering headers alone never authorizes rendering or GPU access.
#if defined(__has_include)
#  if __has_include("libretro_vulkan.h") && __has_include(<vulkan/vulkan.h>)
#    define AZ116_VULKAN_DEPENDENCIES_DISCOVERABLE 1
#  else
#    define AZ116_VULKAN_DEPENDENCIES_DISCOVERABLE 0
#  endif
#else
#  define AZ116_VULKAN_DEPENDENCIES_DISCOVERABLE 0
#endif
#define AZ115_OFFICIAL_VULKAN_HEADER 0 // Not safely integrated into this TU.
#define AZ115_FRONTEND_CONTEXT_CALLBACKS 0
#define AZ115_GPU_FRAME_EXCHANGE 0
#define AZ115_OPENEMU_GPU_PRESENTER 0
static_assert(!(AZ115_FRONTEND_CONTEXT_CALLBACKS && AZ115_GPU_FRAME_EXCHANGE && AZ115_OPENEMU_GPU_PRESENTER) || AZ115_OFFICIAL_VULKAN_HEADER,
              "Never enable Vulkan bridge without official libretro Vulkan ABI");
static bool Az115HardwareReady(void) {
    return AZ115_OFFICIAL_VULKAN_HEADER && AZ115_FRONTEND_CONTEXT_CALLBACKS &&
           AZ115_GPU_FRAME_EXCHANGE && AZ115_OPENEMU_GPU_PRESENTER;
}


// The project's minimal libretro.h omits the core-options ABI structures.
// These layouts match the libretro C ABI (v1 and v2).
struct az_retro_core_option_value { const char *value; const char *label; };
struct az_retro_core_option_definition {
    const char *key; const char *desc; const char *info;
    struct az_retro_core_option_value values[128]; const char *default_value;
};
struct az_retro_core_option_v2_definition {
    const char *key; const char *desc; const char *desc_categorized;
    const char *info; const char *info_categorized; const char *category_key;
    struct az_retro_core_option_value values[128]; const char *default_value;
};
struct az_retro_core_options_v2 {
    const void *categories;
    const struct az_retro_core_option_v2_definition *definitions;
};

static const unsigned kNativeWidth = 400;
static const unsigned kNativeHeight = 480;
static const unsigned kMaxFramebufferBytes = 400 * 480 * 4;
// Safety boundary for *source* frames, not the smaller OpenEmu presentation.
// Full-resolution stereo at 6x is 4800x2880 BGRA (~53 MiB) per CPU copy.
// Check arithmetic in 64-bit before allocating; invalid geometry fails closed.
static constexpr unsigned kAz191MaxFrameDimension = 8192u;
static constexpr size_t kAz191MaxFrameBytes = 128u * 1024u * 1024u;
static bool Az191ValidFrame(unsigned w, unsigned h) {
    return w > 0 && h > 0 && w <= kAz191MaxFrameDimension &&
           h <= kAz191MaxFrameDimension &&
           (uint64_t)w * (uint64_t)h * 4u <= kAz191MaxFrameBytes;
}

