// Retain NDS responders for compatibility with the existing OpenEmu core SDK.
@protocol OE3DSSystemResponderClient <OENDSSystemResponderClient>
- (oneway void)didChange3DSAnalogAxis:(NSUInteger)axis value:(float)value forPlayer:(NSUInteger)player;
- (oneway void)didChange3DSExtraButton:(NSUInteger)button pressed:(BOOL)pressed forPlayer:(NSUInteger)player;
@end
// v204: shared, atomically accounted GPU probe lifecycle. A completed handler
// may outlive this core; it MUST NOT capture a core, host bitmap or callback to
// OpenEmu. No locks or GPU waits on the frame execution path.
struct Az204StreamTracker {
    std::atomic<unsigned> inflight{0};
    std::atomic<unsigned> submissions[12];
    std::atomic<unsigned> completions[12];
    std::atomic<unsigned> passes[12];
    std::atomic<unsigned> failures[12];
    std::atomic<unsigned> busy_skips[12];
    std::atomic<unsigned> max_errors[12];
    std::atomic<unsigned> missing_reported[12];
    Az204StreamTracker() {
        for(unsigned i=0;i<12;i++) {
            submissions[i].store(0); completions[i].store(0);
            passes[i].store(0); failures[i].store(0);
            busy_skips[i].store(0); max_errors[i].store(0);
            missing_reported[i].store(0);
        }
    }
};

// v206: one bounded high-resolution output matrix across multiple physical
// texture sizes. Completion callbacks own their state, not an emulator object.
struct Az206MatrixTracker {
    std::atomic<unsigned> inFlight{0};
    std::atomic<unsigned> started{0};
    std::atomic<unsigned> completed{0};
    std::atomic<unsigned> passed{0};
    std::atomic<unsigned> failed{0};
    std::atomic<unsigned> checkedPixels{0};
};

// v205: an isolated, verified Metal-to-bitmap handoff. The asynchronous
// callback owns this heap state and *never* calls into OpenEmu or the core.
// The emulator thread uses try_lock so rendering can never block on this lock.
struct Az205PresentState {
    std::mutex mutex;
    std::vector<uint8_t> readyPixels;
    unsigned readyW=0,readyH=0,readySourceW=0,readySourceH=0;
    unsigned readyMode=0;
    uint64_t readySequence=0;
    uint64_t lastPresented=0;
    std::atomic<uint64_t> frameSequence{0};
    std::atomic<unsigned> inFlight{0};
    std::atomic<unsigned> submitted{0};
    std::atomic<unsigned> modeSubmitted[24]{};
    std::atomic<unsigned> modeFinished[24]{};
    std::atomic<unsigned> modeVerified[24]{};
    std::atomic<unsigned> finished{0};
    std::atomic<unsigned> verified{0};
    std::atomic<unsigned> rejected{0};
    std::atomic<unsigned> skippedBusy{0};
    std::atomic<unsigned> visible{0};
    std::atomic<unsigned> stale{0};
    std::atomic<bool> disabled{false};
    std::atomic<bool> reported{false};
};

@interface AzaharGameCore () <OE3DSSystemResponderClient>
// v206: non-visible, asynchronous full-resolution and intermediate-resolution
// Metal texture matrix. The v205 bitmap fallback is always independent.
- (void)az206ProbeOutputMatrix:(const uint8_t *)pixels
    sourceWidth:(unsigned)width sourceHeight:(unsigned)height
    sourcePitch:(size_t)pitch rgba:(BOOL)rgba;

// v205: submit full-resolution Metal composition and consume only a
// verified, recent completed frame. Neither function changes OpenEmu's renderer.
- (uint64_t)az205SubmitVisibleCandidate:(const uint8_t *)pixels
    sourceWidth:(unsigned)width sourceHeight:(unsigned)height
    sourcePitch:(size_t)pitch rgba:(BOOL)rgba
    destinationWidth:(unsigned)dw destinationHeight:(unsigned)dh
    fullStereo:(BOOL)wide;
- (void)az205MaybePresentVerifiedFrame:(uint8_t *)destination
    width:(unsigned)dw height:(unsigned)dh
    sourceWidth:(unsigned)sw sourceHeight:(unsigned)sh
    sequence:(uint64_t)sequence fullStereo:(BOOL)wide;
// v204: bounded concurrent streaming test; no OpenEmu display changes.
- (void)az204ProbeContinuousMetalComposition:(const uint8_t *)pixels
                      sourceWidth:(unsigned)width sourceHeight:(unsigned)height
                      sourcePitch:(size_t)pitch rgba:(BOOL)rgba;
// v203: isolated async composition probe. NEVER changes the OpenEmu presenter.
- (void)az203ProbeMetalComposition:(const uint8_t *)pixels
                      sourceWidth:(unsigned)width sourceHeight:(unsigned)height
                      sourcePitch:(size_t)pitch rgba:(BOOL)rgba;
// v202: diagnostic-only async Metal transfer; NEVER changes the host presenter.
- (void)az202ProbeFullResolutionPixels:(const uint8_t *)pixels
                          sourceWidth:(unsigned)width sourceHeight:(unsigned)height
                          sourcePitch:(size_t)pitch rgba:(BOOL)rgba;
@end

