// Diagnostic-only logging. Uses /tmp so the helper can usually write without
// modifying the user's OpenEmu configuration. Also writes to stderr.
// v212: Two diagnostic levels without altering any underlying probe execution.
// Default: keep active runtime milestones, failures and release identity.
// AZAHAR_DIAG_VERBOSE=1: emit every historical milestone for developer analysis.
// Filtering occurs BEFORE stderr, flush, and per-line file open/close, so legacy
// preflight chatter does not impose avoidable I/O on normal gameplay.
static std::atomic<unsigned long long> gAz212LinesWritten{0};
static std::atomic<unsigned long long> gAz212LinesFiltered{0};
static bool Az212VerboseDiagnostics(void) {
    static const bool enabled = [] {
        const char *value = getenv("AZAHAR_DIAG_VERBOSE");
        return value && strcmp(value, "1") == 0;
    }();
    return enabled;
}
static bool Az212LogIsRelevant(const char *line) {
    if (!line) return false;
    // Never suppress an error/failure regardless of historical test version.
    if (strstr(line, "ERROR") || strstr(line, "FAIL") ||
        strstr(line, "CHECK") || strstr(line, "DEGRADED") ||
        strstr(line, "WARNING") || strstr(line, "FATAL")) return true;
    if (line[0] == 'V' && line[1] >= '0' && line[1] <= '9') {
        char *end = nullptr;
        const long version = strtol(line + 1, &end, 10);
        // Version labels >=187 identify live Vulkan integration and subsequent
        // stable presentation, timing, settings, save and pixel-audit checkpoints.
        return end != line + 1 && version >= 187;
    }
    return false;
}
static void AzTrace(const char *stage) {
    if (!stage) return;
    if (!Az212VerboseDiagnostics() && !Az212LogIsRelevant(stage)) {
        ++gAz212LinesFiltered;
        return;
    }
    ++gAz212LinesWritten;
    fprintf(stderr, "[AzaharDiag] %s\n", stage);
    fflush(stderr);
    // Castle 91: bound on-disk diagnostics across repeated ROM launches.
    // The latest log remains at its usual path; one prior segment is retained.
    const char *diagPath = "/tmp/azahar-openemu-diagnostic.log";
    struct stat diagStat;
    if (stat(diagPath, &diagStat) == 0 && diagStat.st_size >= 2 * 1024 * 1024) {
        rename(diagPath, "/tmp/azahar-openemu-diagnostic.previous.log");
    }
    FILE *f = fopen(diagPath, "a");
    if (f) {
        fprintf(f, "[AzaharDiag] %s\n", stage);
        fflush(f);
        fclose(f);
    }
}

