// v193: presentation size is independent of Azahar's internal render factor.
// The source is read at full resolution, with an inexpensive four-tap average
// when downsampling; the OpenEmu bitmap dimensions remain fixed. This avoids
// the host treating a 2x/3x row as though it still had the 1x stride.
static void Az193CopyDownsampleBGRA(uint8_t *dst, unsigned destW, unsigned destH,
                                    const uint8_t *src, unsigned srcW, unsigned srcH,
                                    size_t srcPitch, bool rgba) {
    if (!dst || !src || !destW || !destH || !srcW || !srcH) return;
    for (unsigned y=0; y<destH; ++y) {
        const unsigned sy0=(unsigned)(((uint64_t)(2u*y+0u)*srcH)/(2u*destH));
        const unsigned sy1=(unsigned)(((uint64_t)(2u*y+1u)*srcH)/(2u*destH));
        const uint8_t *row0=src+(size_t)std::min(sy0,srcH-1u)*srcPitch;
        const uint8_t *row1=src+(size_t)std::min(sy1,srcH-1u)*srcPitch;
        for (unsigned x=0; x<destW; ++x) {
            const unsigned sx0=(unsigned)(((uint64_t)(2u*x+0u)*srcW)/(2u*destW));
            const unsigned sx1=(unsigned)(((uint64_t)(2u*x+1u)*srcW)/(2u*destW));
            const uint8_t *a=row0+(size_t)std::min(sx0,srcW-1u)*4u;
            const uint8_t *b=row0+(size_t)std::min(sx1,srcW-1u)*4u;
            const uint8_t *c=row1+(size_t)std::min(sx0,srcW-1u)*4u;
            const uint8_t *d=row1+(size_t)std::min(sx1,srcW-1u)*4u;
            uint8_t *out=dst+((size_t)y*destW+x)*4u;
            const unsigned redIndex=rgba?0u:2u, blueIndex=rgba?2u:0u;
            out[0]=(uint8_t)((a[blueIndex]+b[blueIndex]+c[blueIndex]+d[blueIndex]+2u)/4u);
            out[1]=(uint8_t)((a[1]+b[1]+c[1]+d[1]+2u)/4u);
            out[2]=(uint8_t)((a[redIndex]+b[redIndex]+c[redIndex]+d[redIndex]+2u)/4u);
            out[3]=(uint8_t)((a[3]+b[3]+c[3]+d[3]+2u)/4u);
        }
    }
}
// Session geometry and memory ownership: OpenEmu caches the bitmap's base
// pointer and row stride. They MUST stay stable while the game is running.
// Allocate for max 2x at launch and start with a native-sized screenRect.
// SBS Full doubles the logical width; changing between 2D and SBS Full can
// require a game restart to select the corresponding host window geometry.
// screenRect is the *visible* portion of the fixed buffer, not its capacity.
static constexpr unsigned kAz197FullWidth = kNativeWidth * 2u;
static bool Az197FullSelected(AzaharGameCore *core) {
    return core && [core->_az191Stereo isEqualToString:@"side-by-side-full"];
}
static void Az197LockSessionGeometry(AzaharGameCore *core, const char *phase) {
    if (!core || core->_az197PresentationLocked) return;
    const unsigned logicalW=Az197FullSelected(core) ? kAz197FullWidth : kNativeWidth;
    const unsigned logicalH=kNativeHeight;
    // Reserve a Retina-capable 2x bitmap in both 1x and higher modes. The
    // player controls only Azahar's 1x..6x INTERNAL resolution; no separate
    // physical-output menu, including for old persisted 3x preferences.
    unsigned scale=2u;
    // OpenEmu creates its initial native-sized game window from screenRect.
    // Later it can refresh the bitmap texture when screenRect changes, while
    // keeping bufferSize (and thus the host's row pitch) unchanged. This is
    // the tested v208+ core-only Retina presentation method; never mutate the
    // cached buffer pointer, maximum dimensions or pitch after initialization.
    unsigned maxW=logicalW, maxH=logicalH;
    if(scale>1u) {maxW=logicalW*2u; maxH=logicalH*2u;}
    const size_t bytes=(size_t)maxW*maxH*4u;
    bool enough=(bytes<=(size_t)24u*1024u*1024u);
    if(enough && bytes>core->_videoBufferCapacity) {
        uint8_t *next=core->_az191OwnsVideoBuffer
            ? (uint8_t *)realloc(core->_videoBuffer,bytes) : nullptr;
        if(next) {
            memset(next+core->_videoBufferCapacity,0,bytes-core->_videoBufferCapacity);
            core->_videoBuffer=next;
            core->_videoBufferCapacity=bytes;
        } else enough=false;
    }
    // Single owned compact working surface; only needed in padded mode.
    if(enough && scale>1u) {
        const size_t compact=(size_t)logicalW*scale*logicalH*scale*4u;
        core->_az208CompactFrame=(uint8_t *)malloc(compact);
        if(core->_az208CompactFrame) core->_az208CompactCapacity=compact;
        else enough=false;
    }
    if(!enough) {
        // This is a fail-closed choice: native v206 bitmap, never a black
        // or cropped high-res host texture, and never resize live.
        if(core->_az208CompactFrame) free(core->_az208CompactFrame);
        core->_az208CompactFrame=nullptr;
        core->_az208CompactCapacity=0u;
        scale=1u; maxW=logicalW; maxH=logicalH;
        AzTrace("V208 HOST_BUFFER_FALLBACK reason=ALLOC_OR_BUDGET native_display=YES");
    }
    core->_az207ActiveHostScale=scale;
    core->_az197SessionWidth=logicalW*scale;
    core->_az197SessionHeight=logicalH*scale;
    core->_videoSize=OEIntSizeMake(maxW,maxH);
    core->_az208PaddedHost=(scale>1u);
    core->_az208VisibleWidth=logicalW;
    core->_az208VisibleHeight=logicalH;
    core->_az208StartupFrames=0u;
    core->_az208HiResPublished=0u;
    {
        char v208[290];
        snprintf(v208,sizeof(v208),
          "V208 BUFFER_AND_WINDOW_LOCK host_buffer=%ux%u initial_rect=%ux%u target_rect=%ux%u scale=%u padded=%u bytes=%zu status=READY",
          maxW,maxH,logicalW,logicalH,core->_az197SessionWidth,
          core->_az197SessionHeight,scale,(unsigned)core->_az208PaddedHost,bytes);
        AzTrace(v208);
    }
    core->_az197PresentationLocked = YES;
    {
        char v207[260];
        snprintf(v207,sizeof(v207),
            "V207 HOST_BUFFER_LOCK scale=%u native=%ux%u physical=%ux%u bytes=%zu mode=%s status=READY",
            scale,logicalW,logicalH,core->_az197SessionWidth,core->_az197SessionHeight,
            (size_t)core->_az197SessionWidth*core->_az197SessionHeight*4u,
            scale>1u?"EXPERIMENTAL_BITMAP_HIRES":"STABLE_V206_BITMAP");
        AzTrace(v207);
    }
    char msg[260];
    snprintf(msg,sizeof(msg),
        "V197 GEOMETRY_LOCK phase=%s window=%ux%u selected=%s buffer_capacity=%zu",
        phase,core->_az197SessionWidth,core->_az197SessionHeight,
        (core->_az191Stereo ?: @"off").UTF8String,core->_videoBufferCapacity);
    AzTrace(msg);
}
// Host bitmap is pitched at the maximum buffer width, not the visible width.
// A compact render has rowPitch=outW*4, while OpenEmu reads rowPitch=maxW*4.
// Copy each scanline separately; a contiguous memcpy would shear/corrupt the
// picture as soon as the visible screenRect is smaller than bufferSize.
static inline void Az208CopyRowsToHost(AzaharGameCore *core,
                                      const uint8_t *compact,unsigned outW,unsigned outH) {
    if(!core || !compact || !core->_videoBuffer ||
       outW>(unsigned)core->_videoSize.width ||
       outH>(unsigned)core->_videoSize.height) return;
    const size_t srcPitch=(size_t)outW*4u;
    const size_t dstPitch=(size_t)core->_videoSize.width*4u;
    for(unsigned y=0;y<outH;++y)
        memcpy(core->_videoBuffer+(size_t)y*dstPitch,
               compact+(size_t)y*srcPitch,srcPitch);
}
// Publish only the visible rectangle: for internal 1x show native pixels;
// for internal 2x..6x show physical 2x Retina pixels. The first 180 delivered
// frames retain the native rectangle, allowing OpenEmu to size its window.
// This is a session-time texture-view change, never a host memory reallocation.
static inline void Az208AdvanceScreenRect(AzaharGameCore *core) {
    if(!core || !core->_az208PaddedHost) return;
    if(core->_az208StartupFrames<180u) ++core->_az208StartupFrames;
    // Source render factor and host physical-output factor are independent.
    // Rendering at 6x is supersampled DOWN to 2x, not shown at 6x physical.
    // Buffer capacity and pitch remain fixed throughout resolution changes.
    const unsigned outputScale=(core->_az191Resolution>1) ? 2u : 1u;
    const unsigned baseW=core->_az197SessionWidth/core->_az207ActiveHostScale;
    const unsigned baseH=core->_az197SessionHeight/core->_az207ActiveHostScale;
    const unsigned targetW=baseW*outputScale;
    const unsigned targetH=baseH*outputScale;
    if(core->_az208StartupFrames<180u) return;
    if(core->_az208VisibleWidth==targetW && core->_az208VisibleHeight==targetH) return;
    core->_az208VisibleWidth=targetW;
    core->_az208VisibleHeight=targetH;
    core->_az208HiResPublished=(outputScale==2u);
    char msg[260];
    snprintf(msg,sizeof(msg),
      "V208 RECT_PUBLISH buffer=%dx%d rect=%ux%u initial_native=YES after_frames=%u host_realloc=NO expected_window_resize=NO",
      (int)core->_videoSize.width,(int)core->_videoSize.height,
      core->_az208VisibleWidth,core->_az208VisibleHeight,
      core->_az208StartupFrames);
    AzTrace(msg);
    snprintf(msg,sizeof(msg),
      "V210 AUTO_OUTPUT internal=%ld physical_scale=%u rect=%ux%u mode=%s host_realloc=NO status=PASS",
      (long)core->_az191Resolution,outputScale,targetW,targetH,
      (core->_az191Stereo?:@"off").UTF8String);
    AzTrace(msg);
    // v214: Stock OpenEmu derives the Fullscreen Scale -> 1x view size
    // from defaultScreenSize, which itself follows screenRect. Publishing
    // physical 2x pixels is therefore visible to the HOST'S logical scaling
    // calculation. A core-only alteration of aspectSize cannot independently
    // set a native logical size while retaining the physical Retina rect.
    // Do not silently downsample to 1x or mutate OpenEmu global defaults.
    char v214[320];
    snprintf(v214,sizeof(v214),
      "V214 FULLSCREEN_SCALE_CONTRACT logical=%ux%u visible_rect=%ux%u factor=%u internal=%ld host_scale_control=OPENEMU_ONLY retina_preserved=YES status=HOST_LOGICAL_SIZE_REVIEW",
      baseW,baseH,targetW,targetH,outputScale,
      (long)core->_az191Resolution);
    AzTrace(v214);
}
// Verify actual host bytes after each pitched row copy: compare 9 RGBA/BGRA
// pixels spread over three rows and columns. This is a cheap corruption guard,
// NOT a full image comparison or proof of visible display correctness.
// Keep the audit separate from the presentation path to avoid altering pixels.
static inline void Az209AuditHostPitch(AzaharGameCore *core,
                                      const uint8_t *compact,
                                      unsigned width,unsigned height,
                                      uint64_t elapsedUs) {
    if(!core || !core->_az208PaddedHost) return;
    ++core->_az209PitchCopies;
    core->_az209PitchTotalUs+=elapsedUs;
    core->_az209PitchMaxUs=std::max(core->_az209PitchMaxUs,elapsedUs);
    if(core->_az208HiResPublished) ++core->_az209HiResCopies;
    else ++core->_az209NativeStartCopies;
    bool okay=compact && core->_videoBuffer && width && height &&
      width<=(unsigned)core->_videoSize.width &&
      height<=(unsigned)core->_videoSize.height &&
      (size_t)width*height*4u<=core->_az208CompactCapacity &&
      (size_t)core->_videoSize.width*core->_videoSize.height*4u<=core->_videoBufferCapacity;
    if(okay) {
      const size_t widePitch=(size_t)core->_videoSize.width*4u;
      const size_t compactPitch=(size_t)width*4u;
      const unsigned xs[3]={0u,width/2u,width-1u};
      const unsigned ys[3]={0u,height/2u,height-1u};
      for(unsigned yi=0u;yi<3u && okay;++yi) {
        for(unsigned xi=0u;xi<3u && okay;++xi) {
          const uint8_t *src=compact+(size_t)ys[yi]*compactPitch+(size_t)xs[xi]*4u;
          const uint8_t *dst=core->_videoBuffer+(size_t)ys[yi]*widePitch+(size_t)xs[xi]*4u;
          okay=(memcmp(src,dst,4u)==0);
        }
      }
    }
    if(okay) ++core->_az209PitchPass; else ++core->_az209PitchFail;
    if(core->_az209PitchCopies==1u || !okay ||
       (core->_az209PitchCopies%600u)==0u) {
       char audit[320];
       snprintf(audit,sizeof(audit),
         "V209 PITCH_AUDIT output=%ux%u host_stride=%u sampled=9 copies=%llu pass=%llu fail=%llu native_start=%u hires=%u last_copy_us=%llu max_copy_us=%llu status=%s",
         width,height,(unsigned)core->_videoSize.width,
         (unsigned long long)core->_az209PitchCopies,
         (unsigned long long)core->_az209PitchPass,
         (unsigned long long)core->_az209PitchFail,
         core->_az209NativeStartCopies,core->_az209HiResCopies,
         (unsigned long long)elapsedUs,
         (unsigned long long)core->_az209PitchMaxUs,okay?"PASS":"CHECK");
       AzTrace(audit);
    }
}
// v199: Prefer the correctly sized full-eye image produced by a newly rebuilt
// Azahar libretro binary. The v198 center-crop path remains an explicit
// compatibility fallback if an older compact framebuffer arrives. Only this
// stereo mode is affected; all other modes keep v198's presentation behavior.
// v198: Azahar libretro computes the normal stack as 400x480 even for
// Side-by-Side Full. Inside its framebuffer layout it then divides the width
// by two for the eyes. In a portrait-shaped libretro frame this makes both
// eye images occupy the *central half* of the height (approximately y=120..360
// at 400x480), with black bands above and below. v197 stretched the full
// source extent to an 800x480 host bitmap, leaving the game vertically squashed.
// Crop just that intentional layout padding before converting to the fixed
// 800x480 presentation surface. This is geometry repair, NOT a claim that the
// libretro renderer produced native-resolution pixels for both eyes.
// A future upstream layout/binary with an already-wide source is passed through
// without cropping. No change to host window geometry or memory ownership.
static bool Az198HasCompactFullStereoLayout(unsigned width,unsigned height) {
    return width > 0u && height > 0u &&
        (uint64_t)width * 6u <= (uint64_t)height * 5u + 2u;
}
static void Az198CopyFullStereoBGRA(uint8_t *dst,unsigned destW,unsigned destH,
                                   const uint8_t *src,unsigned srcW,unsigned srcH,
                                   size_t srcPitch,bool rgba) {
    if (!dst || !src || !srcW || !srcH || !destW || !destH) return;
    // v199: No filtering or cropping for a genuine full-width libretro frame.
    // Preserve exact BGRA pixel values; convert RGBA only if necessary.
    if (srcW==destW && srcH==destH && srcPitch >= (size_t)srcW*4u) {
        if (!rgba) {
            for (unsigned y=0; y<destH; ++y)
                memcpy(dst+(size_t)y*destW*4u,src+(size_t)y*srcPitch,(size_t)destW*4u);
        } else {
            for (unsigned y=0; y<destH; ++y) {
                const uint8_t *in=src+(size_t)y*srcPitch;
                uint8_t *out=dst+(size_t)y*destW*4u;
                for (unsigned x=0;x<destW;++x) {
                    out[x*4u+0u]=in[x*4u+2u];
                    out[x*4u+1u]=in[x*4u+1u];
                    out[x*4u+2u]=in[x*4u+0u];
                    out[x*4u+3u]=in[x*4u+3u];
                }
            }
        }
        return;
    }
    if (Az198HasCompactFullStereoLayout(srcW,srcH)) {
        // Top and bottom padding take one quarter each. Use the *same source*
        // for both eye halves so their stereo separation is not changed.
        const unsigned firstRow=srcH/4u;
        const unsigned activeHeight=srcH/2u;
        Az193CopyDownsampleBGRA(dst,destW,destH,
            src+(size_t)firstRow*srcPitch,srcW,activeHeight,srcPitch,rgba);
    } else {
        Az193CopyDownsampleBGRA(dst,destW,destH,src,srcW,srcH,srcPitch,rgba);
    }
}
// v197: when the user switches *out of* full stereo while the window remains
// 800px wide, pillarbox the 400px normal view instead of stretching it.
// This preserves correct proportions until the next game load can resize.
static void Az197CopyPresentationBGRA(uint8_t *dst,unsigned destW,unsigned destH,
                                     const uint8_t *src,unsigned srcW,unsigned srcH,
                                     size_t srcPitch,bool rgba,bool stereoFull) {
    if (!dst || !src || !destW || !destH || !srcW || !srcH) return;
    // v207: exact source-to-host-size transport for actual full-res frames.
    // Note: a full-stereo equal-size copy is already handled by v198 below.
    if(!stereoFull && destH>kNativeHeight && srcW==destW && srcH==destH &&
       srcPitch>=(size_t)srcW*4u) {
        for(unsigned y=0;y<destH;++y) {
            const uint8_t *in=src+(size_t)y*srcPitch;
            uint8_t *out=dst+(size_t)y*destW*4u;
            if(!rgba) memcpy(out,in,(size_t)destW*4u);
            else for(unsigned x=0;x<destW;++x) {
                out[4u*x+0u]=in[4u*x+2u];
                out[4u*x+1u]=in[4u*x+1u];
                out[4u*x+2u]=in[4u*x+0u];
                out[4u*x+3u]=in[4u*x+3u];
            }
        }
        return;
    }
    // v207: apply pillarboxing also for 2x/3x FULL-stereo host surfaces.
    // Aspect 800:480 identifies a locked full-stereo-wide session.
    if ((uint64_t)destW*kNativeHeight==(uint64_t)destH*kAz197FullWidth && !stereoFull) {
        const unsigned viewW=destW/2u, offset=(destW-viewW)/2u;
        memset(dst,0,(size_t)destW*destH*4u);
        // Fixed-size temporary rows are unnecessary. Write the centered region
        // directly using the same 4-tap filter as v193.
        for (unsigned y=0;y<destH;++y) {
            const unsigned sy0=std::min((unsigned)(((uint64_t)(2u*y)*srcH)/(2u*destH)),srcH-1u);
            const unsigned sy1=std::min((unsigned)(((uint64_t)(2u*y+1u)*srcH)/(2u*destH)),srcH-1u);
            const uint8_t *row0=src+(size_t)sy0*srcPitch;
            const uint8_t *row1=src+(size_t)sy1*srcPitch;
            for (unsigned x=0;x<viewW;++x) {
                const unsigned sx0=std::min((unsigned)(((uint64_t)(2u*x)*srcW)/(2u*viewW)),srcW-1u);
                const unsigned sx1=std::min((unsigned)(((uint64_t)(2u*x+1u)*srcW)/(2u*viewW)),srcW-1u);
                const uint8_t *a=row0+(size_t)sx0*4u,*b=row0+(size_t)sx1*4u;
                const uint8_t *c=row1+(size_t)sx0*4u,*d=row1+(size_t)sx1*4u;
                uint8_t *o=dst+((size_t)y*destW+offset+x)*4u;
                const unsigned bi=rgba?2u:0u, ri=rgba?0u:2u;
                o[0]=(uint8_t)((a[bi]+b[bi]+c[bi]+d[bi]+2u)/4u);
                o[1]=(uint8_t)((a[1]+b[1]+c[1]+d[1]+2u)/4u);
                o[2]=(uint8_t)((a[ri]+b[ri]+c[ri]+d[ri]+2u)/4u);
                o[3]=(uint8_t)((a[3]+b[3]+c[3]+d[3]+2u)/4u);
            }
        }
        return;
    }
    if (stereoFull) {
        Az198CopyFullStereoBGRA(dst,destW,destH,src,srcW,srcH,srcPitch,rgba);
    } else {
        Az193CopyDownsampleBGRA(dst,destW,destH,src,srcW,srcH,srcPitch,rgba);
    }
}
static unsigned gAzVideoFrames = 0;
static void AzVideo(const void *data, unsigned width, unsigned height, size_t pitch) {
