    if (gAzVideoFrames < 3) {
        char line[240];
        snprintf(line, sizeof(line), "V10 VIDEO frame=%u data=%s width=%u height=%u pitch=%zu hw_sentinel=%s",
                 gAzVideoFrames, data ? "non-null" : "null", width, height, pitch,
                 data == (const void *)(intptr_t)-1 ? "yes" : "no");
        AzTrace(line);
    }
    if (data == (const void *)(intptr_t)-1) ++gAz111HardwareMarkers;
    else if (!data) ++gAz111NullFrames;
    else { ++gAz111SoftwareFrames; gAz111LastWidth=width; gAz111LastHeight=height; }
    // A milestone every 300 delivered software frames (~5s at 60fps).
    if (gAz111SoftwareFrames && gAz111SoftwareFrames % 300 == 0 &&
        data && data != (const void *)(intptr_t)-1) Az111Report("GAMEPLAY");
    // These checks observe libretro's actual software-frame contract without
    // dereferencing a hardware sentinel or accepting an unsupported Vulkan context.
    if (data && data != (const void *)(intptr_t)-1) {
        if (!width || !height || width > 8192 || height > 8192) ++gAz112BadGeometry;
        if (pitch && (size_t)width <= SIZE_MAX / 4 && pitch < (size_t)width * 4) ++gAz112BadPitch;
    }
    if (gAz111SoftwareFrames && gAz111SoftwareFrames % 300 == 0 &&
        data && data != (const void *)(intptr_t)-1) Az112Report("GAMEPLAY");
    ++gAzVideoFrames;
    // A hardware frame is an opaque marker, never a CPU-readable pixel pointer.
    // Do not dereference it even if a future core unexpectedly supplies one.
    if (data == (const void *)(intptr_t)-1) {
        if(gAzV12ProbeVulkan && gAzV187HardwareInterfaceActive) {
            ++gAzV187HwSentinels;
            // Bound readback to one small frame in preflight. Full presentation
            // requires longer-lived resource ownership across the real session.
            const size_t bytes=(size_t)width*height*4u;
            if(Az191ValidFrame(width,height)) {
                AzaharGameCore *readbackCore=gAzaharCore;
                if(readbackCore && bytes>readbackCore->_az189ReadbackCapacity){
                    uint8_t *newScratch=(uint8_t *)realloc(readbackCore->_az189ReadbackScratch,bytes);
                    if(newScratch){
                        readbackCore->_az189ReadbackScratch=newScratch;
                        readbackCore->_az189ReadbackCapacity=bytes;
                    }
                }
                unsigned char *pixels=(readbackCore &&
                    bytes<=readbackCore->_az189ReadbackCapacity)
                    ? readbackCore->_az189ReadbackScratch : nullptr;
                if(pixels){
                    const unsigned r=AzaharV187ConsumeHardwareImage(width,height,pixels,(unsigned)bytes);
                    if(r==0xffu) {
                        ++gAzV187HwReadbacks;
                        // The Vulkan copy completed and CPU memory was mapped.
                        // Convert only four supported VkFormats to OpenEmu's BGRA8 bitmap.
                        const unsigned fmt=AzaharV188LiveImageFormat();
                        const bool rgba=(fmt==37u || fmt==43u); // R8G8B8A8 UNORM/SRGB
                        const bool bgra=(fmt==44u || fmt==50u); // B8G8R8A8 UNORM/SRGB
                        if(rgba || bgra) {
                            AzaharGameCore *view=gAzaharCore;
                            if(view && view->_videoBuffer && Az191ValidFrame(width,height)) {
                                // v197: source dimensions can change; host dimensions must not.
                                const bool stereoFull197=Az197FullSelected(view);
                                Az208AdvanceScreenRect(view);
                                const unsigned outW193=view->_az208PaddedHost
                                    ? view->_az208VisibleWidth:view->_az197SessionWidth;
                                const unsigned outH193=view->_az208PaddedHost
                                    ? view->_az208VisibleHeight:view->_az197SessionHeight;
                                const bool normalize193=true;
                                const size_t outputBytes193=(size_t)outW193*outH193*4u;
                                if(!view->_az208PaddedHost && outputBytes193>view->_videoBufferCapacity) {
                                    // An OpenEmu hint may be borrowed; never realloc borrowed memory.
                                    uint8_t *next=view->_az191OwnsVideoBuffer
                                        ? (uint8_t *)realloc(view->_videoBuffer,outputBytes193)
                                        : (uint8_t *)malloc(outputBytes193);
                                    if(next) {
                                        view->_videoBuffer=next;
                                        view->_videoBufferCapacity=outputBytes193;
                                        view->_az191OwnsVideoBuffer=YES;
                                    }
                                }
                                if(outputBytes193<=(view->_az208PaddedHost
                                        ?view->_az208CompactCapacity:view->_videoBufferCapacity)) {
                                    uint8_t *frame208=view->_az208PaddedHost
                                        ?view->_az208CompactFrame:view->_videoBuffer;
                                    if(normalize193) {
                                        Az197CopyPresentationBGRA(frame208,outW193,outH193,
                                            pixels,width,height,(size_t)width*4u,rgba,stereoFull197);
                                        // v202: in parallel with v199 bitmap output, validate
                                        // a separate full-resolution GPU texture transfer.
                                        // Never replace the host's rendering interface.
                                        [view az202ProbeFullResolutionPixels:pixels
                                            sourceWidth:width sourceHeight:height
                                            sourcePitch:(size_t)width*4u rgba:rgba];
                                        [view az203ProbeMetalComposition:pixels
                                            sourceWidth:width sourceHeight:height
                                            sourcePitch:(size_t)width*4u rgba:rgba];
                                        [view az204ProbeContinuousMetalComposition:pixels
                                            sourceWidth:width sourceHeight:height
                                            sourcePitch:(size_t)width*4u rgba:rgba];
                                        const uint64_t v205Seq=view->_az208PaddedHost?0u:
                                          [view az205SubmitVisibleCandidate:pixels
                                            sourceWidth:width sourceHeight:height
                                            sourcePitch:(size_t)width*4u rgba:rgba
                                            destinationWidth:outW193 destinationHeight:outH193
                                            fullStereo:stereoFull197];
                                        // Keep v205 visible handoff private in padded mode:
                                        // the Metal candidate writer assumes a compact bitmap.
                                        if(!view->_az208PaddedHost)
                                        [view az205MaybePresentVerifiedFrame:frame208
                                            width:outW193 height:outH193
                                            sourceWidth:width sourceHeight:height
                                            sequence:v205Seq fullStereo:stereoFull197];
                                        // v206 runs independent GPU output sizes only once
                                        // per actual resolution/stereo combination.
                                        [view az206ProbeOutputMatrix:pixels
                                            sourceWidth:width sourceHeight:height
                                            sourcePitch:(size_t)width*4u rgba:rgba];
                                        if(view->_az207ActiveHostScale>1u && view->_az208HiResPublished) {
                                            ++view->_az207HostFrames;
                                            const bool genuine207=width>=outW193 && height>=outH193;
                                            if(genuine207) ++view->_az207RealHighResFrames;
                                            if(width==outW193 && height==outH193)
                                                ++view->_az207ExactCopyFrames;
                                            if(view->_az207HostFrames==1u ||
                                               (view->_az207HostFrames%300u)==0u) {
                                                char host207[285];
                                                snprintf(host207,sizeof(host207),
                                                    "V207 HOST_PHYSICAL_FRAME source=%ux%u host_bitmap=%ux%u physical_scale=%u actual_source_ge_host=%u frames=%u genuine_frames=%u exact_size_frames=%u renderer=BITMAP status=%s",
                                                    width,height,outW193,outH193,
                                                    view->_az207ActiveHostScale,(unsigned)genuine207,
                                                    view->_az207HostFrames,
                                                    view->_az207RealHighResFrames,
                                                    view->_az207ExactCopyFrames,
                                                    genuine207?"PASS":"SOURCE_BELOW_TARGET");
                                                AzTrace(host207);
                                            }
                                        }
                                        if (++view->_az197ReportFrames <= 12u ||
                                            (view->_az197ReportFrames%300u)==0u) {
                                            char frame197[280];
                                            snprintf(frame197,sizeof(frame197),
                                                "V199 GPU_FRAME src=%ux%u output=%ux%u stereo=%s rgba=%u "
                                                "bytes=%zu behavior=%s",
                                                width,height,outW193,outH193,
                                                (view->_az191Stereo ?: @"off").UTF8String,(unsigned)rgba,
                                                outputBytes193,(outW193==kAz197FullWidth && !stereoFull197)
                                                ?"PILLARBOX":stereoFull197 &&
                                                Az198HasCompactFullStereoLayout(width,height)
                                                ?"V198_STEREO_CENTER_CROP_FALLBACK":(width==outW193 && height==outH193)
                                                ?(stereoFull197 ? "V199_FULL_NATIVE_PIXEL_COPY" : "SAME_SIZE"):
                                                "RESAMPLE");
                                            AzTrace(frame197);
                                        }
                                        ++view->_az193NormalizedFrames;
                                        if(view->_az193NormalizedFrames<=4 ||
                                           (view->_az193NormalizedFrames%300u)==0u) {
                                            char normLog[220];
                                            snprintf(normLog,sizeof(normLog),
                                                "V193 STABLE_PRESENT source=%ux%u output=%ux%u normalized=%u",
                                                width,height,outW193,outH193,view->_az193NormalizedFrames);
                                            AzTrace(normLog);
                                        }
                                    } else {
                                        for(size_t n=0;n<outputBytes193;n+=4u){
                                            uint8_t *out=frame208+n;
                                            const uint8_t *in=pixels+n;
                                            out[0]=rgba?in[2]:in[0];out[1]=in[1];
                                            out[2]=rgba?in[0]:in[2];out[3]=in[3];
                                        }
                                    }
                                    // Copy the compact result into fixed-stride host rows
                                    // before returning control to OpenEmu's renderer.
                                    if(view->_az208PaddedHost) {
                                        const auto copyBegin=std::chrono::steady_clock::now();
                                        Az208CopyRowsToHost(view,frame208,outW193,outH193);
                                        const auto copyUs=std::chrono::duration_cast<std::chrono::microseconds>(
                                          std::chrono::steady_clock::now()-copyBegin).count();
                                        Az209AuditHostPitch(view,frame208,outW193,outH193,
                                          (uint64_t)std::max<int64_t>(0,copyUs));
                                    }
                                    uint32_t hash=2166136261u;
                                    unsigned nonzero=0;
                                    for(size_t n=0;n<outputBytes193;n+=4u){
                                        const uint8_t *out=frame208+n;
                                        nonzero += (out[0]!=0 || out[1]!=0 || out[2]!=0 || out[3]!=0);
                                        if(((n/4u)&127u)==0u)
                                            for(unsigned j=0;j<4u;++j)hash=(hash^out[j])*16777619u;
                                    }
                                    if(gAzV188FrameCopies && hash!=gAzV188LastHash)++gAzV188FrameHashesChanged;
                                    gAzV188LastHash=hash;gAzV188LastFormat=fmt;
                                    gAzV188FrameNonzero += (nonzero>0);
                                    ++gAzV188FrameCopies;
                                    // v197: never mutate _videoSize after geometry lock.
                                    if(gAzV188FrameCopies<=8u || (gAzV188FrameCopies%60u)==0u){
                                        char frame188[300];
                                        snprintf(frame188,sizeof(frame188),
                                            "V188 CORE_GPU_TO_OPENEMU_BITMAP frame=%u width=%u height=%u vk_format=%u bgra=1 nonzero_pixels=%u sample_hash=%08x changed=%u mode=%s status=PASS",
                                            gAzV188FrameCopies,width,height,fmt,nonzero,hash,gAzV188FrameHashesChanged,
                                            gAzV188HardwarePromoted?"PERSISTENT_HW":"HW_WARMUP");
                                        AzTrace(frame188);
                                    }
                                } else ++gAzV188VideoCopyFailures;
                            } else ++gAzV188VideoCopyFailures;
                        } else {++gAzV188RejectedFormats;}
                    } else ++gAzV187HwReadbackFailures;
                    char v187frame[240];
                    snprintf(v187frame,sizeof(v187frame),
                        "V187 CORE_GPU_FRAME_READBACK mask=0x%x expected=0xff width=%u height=%u sentinel=1 status=%s",
                        r,width,height,r==0xffu?"PASS":"BLOCKED");
                    // Successful frame telemetry is sampled, not logged 12k times.
                    if(r!=0xffu || gAzV187HwReadbacks<=8u || (gAzV187HwReadbacks%300u)==0u)
                        AzTrace(v187frame);
                    // pixels belongs to the reusable core staging allocation.
                } else {
                    ++gAzV187HwReadbackFailures;
                    AzTrace("V189 GPU_STAGING_ALLOCATION status=FAIL");
                }
            } else ++gAzV187HwReadbackFailures;
            return;
        }
        AzTrace("V13 VIDEO hardware framebuffer sentinel received; safely skipped (no presentation bridge)");
        return;
    }
    AzaharGameCore *core = gAzaharCore;
    if (!core || !data || width == 0 || height == 0)
        return;

    if (!Az191ValidFrame(width,height)) {
        AzTrace("V191 SOFTWARE_FRAME invalid_geometry_or_budget status=REJECTED");
        return;
    }
    const bool stereoFullSoftware197=Az197FullSelected(core);
    Az208AdvanceScreenRect(core);
    const unsigned outWSoftware193=core->_az208PaddedHost
        ?core->_az208VisibleWidth:core->_az197SessionWidth;
    const unsigned outHSoftware193=core->_az208PaddedHost
        ?core->_az208VisibleHeight:core->_az197SessionHeight;
    size_t required = (size_t)outWSoftware193*(size_t)outHSoftware193*4u;
    if (!core->_az208PaddedHost && required > core->_videoBufferCapacity) {
        uint8_t *newBuffer = core->_az191OwnsVideoBuffer
            ? (uint8_t *)realloc(core->_videoBuffer,required)
            : (uint8_t *)malloc(required);
        if (!newBuffer) return;
        core->_videoBuffer = newBuffer;
        core->_videoBufferCapacity = required;
        core->_az191OwnsVideoBuffer = YES;
    }

    const uint8_t *src = (const uint8_t *)data;
    uint8_t *dst = core->_az208PaddedHost
        ? core->_az208CompactFrame : core->_videoBuffer;
    if(!dst || required>(core->_az208PaddedHost
            ?core->_az208CompactCapacity:core->_videoBufferCapacity)) return;
    size_t srcPitch = pitch ? pitch : (size_t)width * 4;

    Az197CopyPresentationBGRA(dst,outWSoftware193,outHSoftware193,
                             src,width,height,srcPitch,false,stereoFullSoftware197);
    [core az202ProbeFullResolutionPixels:src sourceWidth:width
                          sourceHeight:height sourcePitch:srcPitch rgba:NO];
    [core az203ProbeMetalComposition:src sourceWidth:width
                          sourceHeight:height sourcePitch:srcPitch rgba:NO];
    [core az204ProbeContinuousMetalComposition:src sourceWidth:width
                          sourceHeight:height sourcePitch:srcPitch rgba:NO];
    if(!core->_az208PaddedHost) {
        const uint64_t v205SWSeq=[core az205SubmitVisibleCandidate:src
            sourceWidth:width sourceHeight:height sourcePitch:srcPitch rgba:NO
            destinationWidth:outWSoftware193 destinationHeight:outHSoftware193
            fullStereo:stereoFullSoftware197];
        [core az205MaybePresentVerifiedFrame:dst
            width:outWSoftware193 height:outHSoftware193
            sourceWidth:width sourceHeight:height
            sequence:v205SWSeq fullStereo:stereoFullSoftware197];
    }
    if(core->_az208PaddedHost) {
        const auto copyBegin=std::chrono::steady_clock::now();
        Az208CopyRowsToHost(core,dst,outWSoftware193,outHSoftware193);
        const auto copyUs=std::chrono::duration_cast<std::chrono::microseconds>(
          std::chrono::steady_clock::now()-copyBegin).count();
        Az209AuditHostPitch(core,dst,outWSoftware193,outHSoftware193,
          (uint64_t)std::max<int64_t>(0,copyUs));
    }
    if(gAzVideoFrames<=12u || (gAzVideoFrames%300u)==0u) {
        char frame197[240];
        snprintf(frame197,sizeof(frame197),
            "V199 SW_FRAME src=%ux%u pitch=%zu output=%ux%u stereo=%s crop_center_fallback=%u",
            width,height,srcPitch,outWSoftware193,outHSoftware193,
            (core->_az191Stereo ?: @"off").UTF8String,
            (unsigned)(stereoFullSoftware197 && Az198HasCompactFullStereoLayout(width,height)));
        AzTrace(frame197);
    }

    // Castle 144: frame interval measurement, prior to the test overlay.
    // Bottom screen is rows 240..479 in the 400x480 software bitmap.
    // This measures callback cadence, not actual display refresh.
    if (gAz141Ready && !gAz139Completed && width == 400 && height >= 480) {
        const auto sampleNow = std::chrono::steady_clock::now();
        if (!gAz144ClockStarted) {
            gAz144ClockStarted = true;
            gAz144ClockStart = sampleNow;
            gAz144LastFrame = sampleNow;
            AzTrace("V144 TIMING_START source=SOFTWARE_VIDEO_CALLBACK classification=SPARSE_BOTTOM_SAMPLE marker=TIME_BASED");
        } else {
            const auto delta = std::chrono::duration_cast<std::chrono::microseconds>(sampleNow - gAz144LastFrame).count();
            gAz144LastFrame = sampleNow;
            if (delta > 0 && delta < 1000000) {
                unsigned bright = 0;
                for (unsigned yy = 260; yy < 480; yy += 22)
                    for (unsigned xx = 20; xx < 400; xx += 38) {
                        const size_t pos = ((size_t)yy * 400u + xx) * 4u;
                        bright += dst[pos] > 28 || dst[pos+1] > 28 || dst[pos+2] > 28;
                    }
                const bool isBright = bright >= 6;
                const unsigned us = (unsigned)delta;
                if (isBright) {
                    ++gAz144BrightFrames; gAz144BrightDeltaUs += us;
                    if (us < gAz144BrightMinUs) gAz144BrightMinUs = us;
                    if (us > gAz144BrightMaxUs) gAz144BrightMaxUs = us;
                } else {
                    ++gAz144DarkFrames; gAz144DarkDeltaUs += us;
                    if (us < gAz144DarkMinUs) gAz144DarkMinUs = us;
                    if (us > gAz144DarkMaxUs) gAz144DarkMaxUs = us;
                }
                ++gAz144Samples;
                if (gAz144Samples % 120u == 0u) {
                    char line[400];
                    snprintf(line, sizeof(line),
                        "V144 TIMING_SAMPLE samples=%u bottom_image_frames=%u bottom_dark_frames=%u image_avg_us=%llu dark_avg_us=%llu image_min_us=%u image_max_us=%u dark_min_us=%u dark_max_us=%u",
                        gAz144Samples, gAz144BrightFrames, gAz144DarkFrames,
                        (unsigned long long)(gAz144BrightFrames ? gAz144BrightDeltaUs/gAz144BrightFrames : 0),
                        (unsigned long long)(gAz144DarkFrames ? gAz144DarkDeltaUs/gAz144DarkFrames : 0),
                        gAz144BrightFrames ? gAz144BrightMinUs : 0, gAz144BrightMaxUs,
                        gAz144DarkFrames ? gAz144DarkMinUs : 0, gAz144DarkMaxUs);
                    AzTrace(line);
                }
            }
        }
    }

    // Castle 141: 400x240 GPU clear/readback is presented using corrected BGRA
    // byte packing. Repeated copies are sourced from one verified GPU frame;
    // a moving CPU-side marker tests that the frontend consumes new buffers.
    // This is NOT a claim of multiple independent GPU render submissions.
    // Castle 163: old blue GPU-clear presentation and moving yellow CPU marker
    // are retired from routine runs. Keep the test implementation for optional
    // future presentation regression work; no software gameplay pixels are altered.
    static constexpr bool kAz163LegacyVisualExperimentEnabled = false;
    if (kAz163LegacyVisualExperimentEnabled && gAz141Ready && gAz141Pixels && !gAz139Completed &&
        width == 400 && height >= 240 && srcPitch >= (size_t)width * 4) {
        const auto now = std::chrono::steady_clock::now();
        if (!gAz139Started) { gAz139Start = now; gAz139Started = true; }
        const auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - gAz139Start).count();
        if (elapsed < 8000) {
            // Use elapsed time rather than frame count: ~140 pixels/second.
            // A fixed-speed marker should no longer accelerate on cheap frames.
            const unsigned movingX = (unsigned)((elapsed * 140LL / 1000LL) % 400LL);
            for (unsigned y = 0; y < 240; ++y) {
                for (unsigned x = 0; x < 400; ++x) {
                    const size_t i = ((size_t)y * 400 + x) * 4;
                    const uint8_t *s = gAz141Pixels + i;
                    uint8_t *d = dst + i;
                    d[0] = s[2]; d[1] = s[1]; d[2] = s[0]; d[3] = s[3];
                    // CPU-only animation marker, not another GPU render.
                    if (x >= movingX && x < movingX + 4u) {
                        d[0] = 0; d[1] = 255; d[2] = 255; d[3] = 255;
                    }
                }
            }
            ++gAz141Frames;
            if (gAz141Frames == 1u) {
                AzTrace("V141 PRESENT full_frame=400x240 format=BGRA gpu_source=VERIFIED_CLEAR moving_marker=CPU_ONLY bounds=PASS software_bottom_screen=PRESERVED status=PASS");
            }
            if (gAz141Frames == 2u)
                AzTrace("V141 REPEATED_FRAME frame=2 source=REUSED_VERIFIED_GPU_FRAME cpu_marker=ADVANCED status=PASS");
        } else {
            gAz139Completed = true;
            char msg[240];
            snprintf(msg, sizeof(msg), "V141 PRESENT_COMPLETE elapsed_ms=%lld frames=%u software_frame_restored=THIS_FRAME status=PASS", (long long)elapsed, gAz141Frames);
            AzTrace(msg);
            char v144Summary[420];
            snprintf(v144Summary, sizeof(v144Summary),
                "V144 TIMING_SUMMARY bottom_image_frames=%u bottom_dark_frames=%u image_avg_us=%llu dark_avg_us=%llu image_fps_est=%.2f dark_fps_est=%.2f marker=TIME_BASED status=COMPLETE",
                gAz144BrightFrames, gAz144DarkFrames,
                (unsigned long long)(gAz144BrightFrames ? gAz144BrightDeltaUs/gAz144BrightFrames : 0),
                (unsigned long long)(gAz144DarkFrames ? gAz144DarkDeltaUs/gAz144DarkFrames : 0),
                gAz144BrightDeltaUs ? 1000000.0 * gAz144BrightFrames / gAz144BrightDeltaUs : 0.0,
                gAz144DarkDeltaUs ? 1000000.0 * gAz144DarkFrames / gAz144DarkDeltaUs : 0.0);
            AzTrace(v144Summary);
        }
    }
    // v197: do not update host geometry from a software video callback.
    // V18: inspect copied pixels, not the source pointer. Read-only, bounded,
    // and limited to the first few callbacks to avoid disturbing frame timing.
    if (gAzVideoFrames <= 5 || gAzVideoFrames == 120) {
        const size_t sample = required < 4096 ? required : 4096;
        size_t nonzero = 0;
        uint32_t checksum = 2166136261u;
        for (size_t i = 0; i < sample; ++i) {
            nonzero += dst[i] != 0;
            checksum = (checksum ^ dst[i]) * 16777619u;
        }
        char v18line[280];
        snprintf(v18line, sizeof(v18line),
                 "V18 FRAME frame=%u size=%ux%u srcPitch=%zu bytes=%zu sample=%zu nonzero=%zu hash=%08x dst=%p",
                 gAzVideoFrames, width, height, srcPitch, required, sample, nonzero, checksum, (void *)dst);
        AzTrace(v18line);
        ++gAz112FrameSamples;
        if (nonzero) ++gAz112NonzeroFrameSamples;
    }
}

static void AzAudioSample(int16_t left, int16_t right) {
    AzaharGameCore *core = gAzaharCore;
    if (!core)
        return;

    int16_t samples[2] = { left, right };
    id<OEAudioBuffer> buffer = [core audioBufferAtIndex:0];
    if (buffer)
        [buffer write:samples maxLength:sizeof(samples)];
}

static size_t AzAudio(const int16_t *data, size_t frames) {
    ++gAz112AudioBatches;
    gAz112AudioFrames += frames;
    AzaharGameCore *core = gAzaharCore;
    if (!core || !data || !frames)
        return frames;

    id<OEAudioBuffer> buffer = [core audioBufferAtIndex:0];
    if (buffer)
        [buffer write:data maxLength:frames * 2 * sizeof(int16_t)];

    return frames;
}

static void AzInputPoll(void) {
    ++gAz111InputPolls;
    // A single summary every 600 game polls preserves the first build marker
    // in long-running diagnostics while diagnosing missing Start/Select presses.
    if(gAzV188HardwarePromoted && gAz111InputPolls>=gAz189LastInputSummaryPoll+600u){
        gAz189LastInputSummaryPoll=(unsigned)gAz111InputPolls;
        char input189[360];
        snprintf(input189,sizeof(input189),
          "V189 INPUT_ROUNDTRIP polls=%llu start_press=%u release=%u queries=%u positive=%u latched=%u select_press=%u release=%u queries=%u positive=%u latched=%u",
          gAz111InputPolls,gAz189StartPressEvents,gAz189StartReleaseEvents,
          gAz189StartQueries,gAz189StartPositive,gAz189StartLatched,
          gAz189SelectPressEvents,gAz189SelectReleaseEvents,
          gAz189SelectQueries,gAz189SelectPositive,gAz189SelectLatched);
        AzTrace(input189);
    }
}

static int16_t AzPointerValue(int16_t value) {
    return value;
}

static int16_t AzInputState(unsigned port, unsigned device, unsigned index, unsigned id) {
    ++gAz112InputReads;
    AzaharGameCore *core = gAzaharCore;
    if (!core || port != 0)
        return 0;

    if (device == RETRO_DEVICE_JOYPAD && index == 0 &&
        (core->_buttons[OENDSButtonA] || core->_buttons[OENDSButtonB] ||
         core->_buttons[OENDSButtonX] || core->_buttons[OENDSButtonY]))
        ++gAz111PressedSamples;
    switch (device) {
    case RETRO_DEVICE_JOYPAD:
        if (index != 0)
            return 0;
        switch (id) {
        case RETRO_DEVICE_ID_JOYPAD_B:      return core->_buttons[OENDSButtonB];
        case RETRO_DEVICE_ID_JOYPAD_Y:      return core->_buttons[OENDSButtonY];
        case RETRO_DEVICE_ID_JOYPAD_A:      return core->_buttons[OENDSButtonA];
        case RETRO_DEVICE_ID_JOYPAD_X:      return core->_buttons[OENDSButtonX];
        case RETRO_DEVICE_ID_JOYPAD_L:      return core->_buttons[OENDSButtonL];
        case RETRO_DEVICE_ID_JOYPAD_R:      return core->_buttons[OENDSButtonR];
        case RETRO_DEVICE_ID_JOYPAD_START: {
            ++gAz189StartQueries;
            const bool held=core->_buttons[OENDSButtonStart];
            const bool latched=!held && gAz189StartLatchUntilPoll &&
                               gAz111InputPolls<=gAz189StartLatchUntilPoll;
            if(held || latched) ++gAz189StartPositive;
            if(latched) ++gAz189StartLatched;
            return held || latched ? 1 : 0;
        }
        case RETRO_DEVICE_ID_JOYPAD_SELECT: {
            ++gAz189SelectQueries;
            const bool held=core->_buttons[OENDSButtonSelect];
            const bool latched=!held && gAz189SelectLatchUntilPoll &&
                               gAz111InputPolls<=gAz189SelectLatchUntilPoll;
            if(held || latched) ++gAz189SelectPositive;
            if(latched) ++gAz189SelectLatched;
            return held || latched ? 1 : 0;
        }
        case RETRO_DEVICE_ID_JOYPAD_UP:     return core->_buttons[OENDSButtonUp];
        case RETRO_DEVICE_ID_JOYPAD_DOWN:   return core->_buttons[OENDSButtonDown];
        case RETRO_DEVICE_ID_JOYPAD_LEFT:   return core->_buttons[OENDSButtonLeft];
        case RETRO_DEVICE_ID_JOYPAD_RIGHT:  return core->_buttons[OENDSButtonRight];
        case RETRO_DEVICE_ID_JOYPAD_L2:     return core->_buttons[14] ? 1 : 0; // 3DS ZL
        case RETRO_DEVICE_ID_JOYPAD_R2:     return core->_buttons[15] ? 1 : 0; // 3DS ZR
        case RETRO_DEVICE_ID_JOYPAD_L3:     return 0;
        case RETRO_DEVICE_ID_JOYPAD_R3:     return 0;
        default: return 0;
        }

    case RETRO_DEVICE_ANALOG:
        if (index != RETRO_DEVICE_INDEX_ANALOG_LEFT &&
            index != RETRO_DEVICE_INDEX_ANALOG_RIGHT)
            return 0;

        if (index == RETRO_DEVICE_INDEX_ANALOG_LEFT) {
            if (id == RETRO_DEVICE_ID_ANALOG_X) {++gAz190AnalogQueries[0];return core->_axisX;}
            if (id == RETRO_DEVICE_ID_ANALOG_Y) {++gAz190AnalogQueries[1];return core->_axisY;}
        } else {
            if (id == RETRO_DEVICE_ID_ANALOG_X) {++gAz190AnalogQueries[2];return core->_cStickX;}
            if (id == RETRO_DEVICE_ID_ANALOG_Y) {++gAz190AnalogQueries[3];return core->_cStickY;}
        }
        return 0;

    case RETRO_DEVICE_POINTER:
        if (index != 0)
            return 0;
        if (id == RETRO_DEVICE_ID_POINTER_PRESSED)
            return core->_touchPressed ? 1 : 0;
        if (id == RETRO_DEVICE_ID_POINTER_X)
            return AzPointerValue(core->_touchX);
        if (id == RETRO_DEVICE_ID_POINTER_Y)
            return AzPointerValue(core->_touchY);
        return 0;

    case RETRO_DEVICE_MOUSE:
        if (index != 0)
            return 0;
        if (id == RETRO_DEVICE_ID_MOUSE_LEFT)
            return core->_touchPressed ? 1 : 0;
        return 0;

    default:
        return 0;
    }
}

// V11: inspect what the bundled core advertises, without requesting a GPU context.
// The option list is authoritative for user-facing choices; it does not prove that
// the corresponding rendering backend was compiled into this dylib.
static void AzV11LogGraphicsOption(const char *key,
                                   const struct az_retro_core_option_value *values,
                                   const char *defaultValue) {
    if (!key || strcmp(key, "citra_graphics_api") != 0) return;
    char line[512];
    snprintf(line, sizeof(line), "V11 OPTIONS graphics_api default=%.160s",
             defaultValue ? defaultValue : "(none)");
    AzTrace(line);
    unsigned count = 0;
    for (unsigned i = 0; i < 128 && values[i].value; ++i) {
        snprintf(line, sizeof(line), "V11 OPTIONS graphics_api choice[%u]=%.160s", i, values[i].value);
        AzTrace(line);
        ++count;
    }
    snprintf(line, sizeof(line), "V11 OPTIONS graphics_api choices=%u (advertised, not verified compiled)", count);
    AzTrace(line);
}

// OpenEmu's display-mode strings feed Azahar's libretro core options.
// Reassert configuration after core-option re-registration and after the live
// Vulkan renderer initializes; otherwise restored stereo settings may revert
// to default during disposable hardware preflight or software fallback.
static void Az191ApplyGraphicsOptions(AzaharGameCore *core) {
    if (!core || !core->_variables) return;
    // Enforce the supported, Mac-tested 1x..6x menu range at the libretro ABI.
    const NSInteger r = (core->_az191Resolution >= 1 && core->_az191Resolution <= 6)
        ? core->_az191Resolution : 1;
    NSString *stereo = core->_az191Stereo ?: @"off";
    if (![@[@"off", @"side-by-side", @"side-by-side-full", @"anaglyph"] containsObject:stereo])
        stereo = @"off";
    core->_variables[@"citra_resolution_factor"] = [NSString stringWithFormat:@"%ld", (long)r];
    core->_variables[@"citra_render_3d"] = stereo;
    const NSInteger depth = (core->_az195Depth >= 10 && core->_az195Depth <= 100 && core->_az195Depth % 10 == 0)
        ? core->_az195Depth : 80;
    core->_variables[@"citra_factor_3d"] = [NSString stringWithFormat:@"%ld", (long)depth];
}

static bool AzEnvironment(unsigned cmd, void *data) {
    AzaharGameCore *core = gAzaharCore;
    if (!core)
        return false;

    switch (cmd) {
    case RETRO_ENVIRONMENT_SET_PIXEL_FORMAT: {
        enum retro_pixel_format format = *(enum retro_pixel_format *)data;
        return format == RETRO_PIXEL_FORMAT_XRGB8888;
    }

    case RETRO_ENVIRONMENT_SET_CORE_OPTIONS_V2: {
        if (!data) { AzTrace("ENV ERROR V2 definitions null"); return false; }
        const struct az_retro_core_options_v2 *opts = (const struct az_retro_core_options_v2 *)data;
        if (!opts->definitions) { AzTrace("ENV ERROR V2 definitions array null"); return false; }
        unsigned count = 0;
        for (const struct az_retro_core_option_v2_definition *d = opts->definitions;
             d->key && count < 1024; ++d, ++count) {
            const char *def = d->default_value ? d->default_value : d->values[0].value;
            AzV11LogGraphicsOption(d->key, d->values, def);
            if (!def) continue;
            NSString *key = [NSString stringWithUTF8String:d->key];
            NSString *value = [NSString stringWithUTF8String:def];
            if (key && value) core->_variables[key] = value;
        }
        Az191ApplyGraphicsOptions(core);
        char line[128]; snprintf(line, sizeof(line), "ENV registered V2 options count=%u", count); AzTrace(line);
        return true;
    }
    case RETRO_ENVIRONMENT_SET_CORE_OPTIONS: {
        if (!data) return false;
        const struct az_retro_core_option_definition *defs = (const struct az_retro_core_option_definition *)data;
        unsigned count = 0;
        for (const struct az_retro_core_option_definition *d = defs;
             d->key && count < 1024; ++d, ++count) {
            const char *def = d->default_value ? d->default_value : d->values[0].value;
            AzV11LogGraphicsOption(d->key, d->values, def);
            if (!def) continue;
            NSString *key = [NSString stringWithUTF8String:d->key];
            NSString *value = [NSString stringWithUTF8String:def];
            if (key && value) core->_variables[key] = value;
        }
        Az191ApplyGraphicsOptions(core);
        char line[128]; snprintf(line, sizeof(line), "ENV registered V1 options count=%u", count); AzTrace(line);
        return true;
    }
    case RETRO_ENVIRONMENT_SET_VARIABLES: {
        if (!data) return false;
        const struct retro_variable *defs = (const struct retro_variable *)data;
        unsigned count = 0;
        for (const struct retro_variable *d = defs; d->key && count < 1024; ++d, ++count) {
            // Legacy format: "Description; first_value|other_value".
            const char *sep = d->value ? strchr(d->value, ';') : NULL;
            if (!sep) continue;
            const char *begin = sep + 1;
            while (*begin == ' ') ++begin;
            const char *end = strchr(begin, '|');
            size_t len = end ? (size_t)(end - begin) : strlen(begin);
            NSString *key = [NSString stringWithUTF8String:d->key];
            NSString *value = [[NSString alloc] initWithBytes:begin length:len encoding:NSUTF8StringEncoding];
            if (key && value) core->_variables[key] = value;
        }
        Az191ApplyGraphicsOptions(core);
        char line[128]; snprintf(line, sizeof(line), "ENV registered legacy options count=%u", count); AzTrace(line);
        return true;
    }

    case RETRO_ENVIRONMENT_GET_CORE_OPTIONS_VERSION:
        if (data) {
            *(unsigned *)data = 2;
            return true;
        }
        return false;

    case RETRO_ENVIRONMENT_GET_VARIABLE: {
        struct retro_variable *var = (struct retro_variable *)data;
        if (!var || !var->key) {
            AzTrace("ENV GET_VARIABLE invalid request (null variable/key)");
            return false;
        }
        char requestLog[1024];
        snprintf(requestLog, sizeof(requestLog), "ENV GET_VARIABLE key=%.800s", var->key);
        AzTrace(requestLog);

        NSString *key = [NSString stringWithUTF8String:var->key];
        // v194: core option definitions can be registered again after a
        // Vulkan/context restart. Reassert the selected values immediately
        // before handing them to Azahar to prevent stale default "off".
        if ([key isEqualToString:@"citra_render_3d"] ||
            [key isEqualToString:@"citra_factor_3d"] ||
            [key isEqualToString:@"citra_resolution_factor"])
            Az191ApplyGraphicsOptions(core);

        // Experiment 04: retain known-working software rendering while
        // independently probing for Vulkan availability. A Vulkan context
        // must not be requested until the frontend can actually provide one.
        if ([key isEqualToString:@"citra_graphics_api"]) {
            NSString *advertised = core->_variables[key];
            char v11line[240];
            const char *selected = gAzV12ProbeVulkan ? "Vulkan" : "Software";
            snprintf(v11line, sizeof(v11line), "V12 POLICY graphics_api advertised_default=%.120s selected=%s",
                     advertised ? advertised.UTF8String : "(missing)", selected);
            AzTrace(v11line);
            core->_variables[key] = gAzV12ProbeVulkan ? @"Vulkan" : @"Software";
        }

        NSString *value = core->_variables[key];
        if (!value) {
            var->value = NULL;
            snprintf(requestLog, sizeof(requestLog), "ENV GET_VARIABLE missing key=%.800s (return false)", var->key);
            AzTrace(requestLog);
            return false;
        }

        var->value = value.UTF8String;
        snprintf(requestLog, sizeof(requestLog), "ENV GET_VARIABLE key=%.380s value=%.380s (return true)", var->key, var->value ? var->value : "(null)");
        AzTrace(requestLog);
        return true;
    }

    case RETRO_ENVIRONMENT_GET_VARIABLE_UPDATE:
        if (data) {
            const bool changed = core->_az191OptionDirty;
            *(bool *)data = changed;
            core->_az191OptionDirty = NO;
            if (changed) AzTrace("V191 LIBRETRO_VARIABLE_UPDATE changed=1 status=DELIVERED");
            return true;
        }
        return false;

    case RETRO_ENVIRONMENT_GET_SAVE_DIRECTORY:
        if (data) {
            const char *dir = core->_supportPath.fileSystemRepresentation;
            AzTrace(dir ? "ENV save directory valid" : "ENV ERROR save directory NULL");
            *(const char **)data = dir;
            return dir != NULL;
        }
        AzTrace("ENV ERROR save directory data NULL");
        return false;

    case RETRO_ENVIRONMENT_GET_SYSTEM_DIRECTORY:
        if (data) {
            const char *dir = core->_supportPath.fileSystemRepresentation;
            AzTrace(dir ? "ENV system directory valid" : "ENV ERROR system directory NULL");
            *(const char **)data = dir;
            return dir != NULL;
        }
        AzTrace("ENV ERROR system directory data NULL");
        return false;

    case RETRO_ENVIRONMENT_GET_LOG_INTERFACE: {
        if (!data)
            return false;
        struct retro_log_callback *cb = (struct retro_log_callback *)data;
        cb->log = AzLog;
        return true;
    }

    case RETRO_ENVIRONMENT_SET_GEOMETRY: {
        const struct retro_game_geometry *geom =
            (const struct retro_game_geometry *)data;
        if (!geom || !Az191ValidFrame(geom->base_width, geom->base_height)) {
            AzTrace("V191 SET_GEOMETRY invalid_or_over_budget status=REJECTED");
            return false;
        }
        ++core->_az191GeometryChanges;
        // Video callbacks remain authoritative for the buffer's real dimensions.
        // Setting size prematurely risks copying a stale/incorrect pitch.
        char line[260];
        snprintf(line,sizeof(line),
           "V191 SET_GEOMETRY base=%ux%u max=%ux%u changes=%u status=ACCEPTED",
           geom->base_width,geom->base_height,geom->max_width,geom->max_height,
           core->_az191GeometryChanges);
        AzTrace(line);
        char lockLog[260];
        snprintf(lockLog,sizeof(lockLog),
            "V197 UPSTREAM_GEOMETRY base=%ux%u expected=%ux%u locked=%u stereo=%s",
            geom->base_width,geom->base_height,
            core->_az197SessionWidth,core->_az197SessionHeight,
            (unsigned)core->_az197PresentationLocked,
            (core->_az191Stereo ?: @"off").UTF8String);
        AzTrace(lockLog);
        return true;
    }

    case RETRO_ENVIRONMENT_SET_INPUT_DESCRIPTORS:
    case RETRO_ENVIRONMENT_SET_CONTROLLER_INFO:
    case RETRO_ENVIRONMENT_SET_SERIALIZATION_QUIRKS:
    case RETRO_ENVIRONMENT_SET_MEMORY_MAPS:
        return true;

    case RETRO_ENVIRONMENT_SET_MESSAGE: {
        struct retro_message *msg = (struct retro_message *)data;
        if (msg && msg->msg)
            NSLog(@"Azahar: %s", msg->msg);
        return true;
    }

    case RETRO_ENVIRONMENT_GET_CURRENT_SOFTWARE_FRAMEBUFFER:
        return false;

    case RETRO_ENVIRONMENT_GET_HW_RENDER_INTERFACE:
        if (gAzV12ProbeVulkan && gAzV187HardwareInterfaceActive && data) {
            void *live=AzaharV187GetPublishedInterface();
            if(live) {
                *(const void **)data=live;
                ++gAzV187HwInterfaceQueries;
                if(gAzV187HwInterfaceQueries<=8u || (gAzV187HwInterfaceQueries%300u)==0u)
                    AzTrace("V187 OFFICIAL_V5_INTERFACE_REQUEST stage=LIVE_HW published=1 real_core_device=1 status=PASS");
                return true;
            }
        }
        ++gAzV13HWInterfaceQueries;
        AzV148Event("GET_HW_RENDER_INTERFACE", &gAzV148FirstInterfaceQuery, data ? 1u : 0u);
        if (gAzV174DiscoveryStage1 && gAzV12ProbeVulkan) {
            ++gAzV174DiscoveryInterfaceQuery;
            AzTrace("V174 DISCOVERY_INTERFACE_REQUEST requested=1 response=REJECTED no_uninitialized_pointer=1");
        }
        AzTrace("V115 GET_HW_RENDER_INTERFACE blocked: complete frontend-owned Vulkan interface unavailable");
        return false;

    case RETRO_ENVIRONMENT_GET_HW_RENDER_CONTEXT_NEGOTIATION_INTERFACE_SUPPORT:
        ++gAzV13NegotiationSupportQueries;
        AzV148Event("GET_NEGOTIATION_SUPPORT", &gAzV148FirstSupportQuery, data ? 1u : 0u);
        if (gAzV12ProbeVulkan) {
            ++gAzV174DiscoverySupportQuery;
            AzTrace("V174 DISCOVERY_NEGOTIATION_SUPPORT response=UNSUPPORTED_BY_DESIGN");
        }
        AzTrace("V115 GET_CONTEXT_NEGOTIATION_SUPPORT blocked: frontend Vulkan integration incomplete");
        return false;

    case RETRO_ENVIRONMENT_GET_PREFERRED_HW_RENDER:
        AzV148Event("GET_PREFERRED_HW_RENDER", &gAzV148FirstPreferred, data ? 1u : 0u);
        if (data) {
            *(enum retro_hw_context_type *)data = RETRO_HW_CONTEXT_NONE;
            AzTrace("V115 PREFERRED_HW_RENDER NONE (hardware bridge incomplete)");
            return true;
        }
        return false;

    // Castle 145: inspect the *actual* request sequence, rather than inferring
    // negotiation readiness from private tests. This command remains rejected.
    case RETRO_ENVIRONMENT_SET_HW_RENDER: {
        // Diagnostic only: context_type is the first field of retro_hw_render_callback.
        // Do not accept the request until OpenEmu can supply a real GPU context.
        if (data) {
            unsigned contextType = *(const unsigned *)data;
            char line[160];
            ++gAzV12HWRequests;
            AzV148Event("SET_HW_RENDER", &gAzV148FirstHW, contextType);
            if (contextType == RETRO_HW_CONTEXT_VULKAN) ++gAzV148VulkanRequests;
            if (contextType == RETRO_HW_CONTEXT_VULKAN) {
                // This gate runs *inside the actual libretro frontend callback*,
                // before returning to the Azahar core. No private probe can
                // substitute for a working image consumer and presenter.
                const unsigned readiness170 = AzaharV170LivePublicationPrerequisites();
                const bool publish170 = (readiness170 == 0x3fu);
                char bridge170[260];
                snprintf(bridge170,sizeof(bridge170),
                  "V170 REAL_STAGE1_READINESS preflight=%u mask=0x%x required=0x3f owner=%u handles=%u dispatch=%u callbacks=%u game_frame_consumer=0 presenter=0 publishable=%u response=REJECTED",
                  (unsigned)gAzV12ProbeVulkan,readiness170,
                  !!(readiness170&1u),!!(readiness170&2u),
                  !!(readiness170&4u),!!(readiness170&8u),
                  (unsigned)publish170);
                AzTrace(bridge170);
                char v171Actual[220];
                snprintf(v171Actual,sizeof(v171Actual),
                    "V171 REAL_STAGE1_EARLY_OWNER mask=0x%x expected=0xf owner=%u callbacks=%u consumer=0 presenter=0 publication=REJECTED status=%s",
                    readiness170,(unsigned)((readiness170&1u)!=0),
                    (unsigned)((readiness170&8u)!=0),
                    readiness170==0xfu?"PASS":"FAIL");
                AzTrace(v171Actual);
                AzTrace("V145 STAGE1_OBSERVED actual_core_request=VULKAN response=REJECTED_BY_DESIGN presenter=ABSENT");
                AzTrace("V145 PARALLEL_A request_capture=PASS no_core_callback_invoked=1");
            }

            // Castle 77: inspect the incoming Vulkan request without dereferencing
            // undocumented callback fields or pretending a context exists.
            if (gAzV12ProbeVulkan) {
                char audit77[256];
                snprintf(audit77,sizeof(audit77),
                         "V77 VULKAN REQUEST context_type=%u expected_vulkan=%u callback_pointer=%s request_number=%u",
                         contextType,(unsigned)RETRO_HW_CONTEXT_VULKAN,
                         data?"non-null":"null",gAzV12HWRequests);
                AzTrace(audit77);
                AzTrace("V77 VULKAN CONTRACT stage_1=SET_HW_RENDER; frontend must own VkInstance VkPhysicalDevice VkDevice VkQueue and frame handoff");
                AzTrace("V77 VULKAN CONTRACT stage_2=SET_HW_RENDER_CONTEXT_NEGOTIATION_INTERFACE; cannot safely run until stage_1 succeeds");
                AzTrace("V77 VULKAN CONTRACT status=NOT_READY; rejecting stage_1 intentionally; no fake GPU context or renderer switch");
                // Castle 78: verify the ABI layout needed to implement a real
                // libretro Vulkan bridge, without dereferencing Azahar's callback
                // beyond its guaranteed first context_type field.
                struct AzV78HWCallbackLayout {
                    unsigned context_type;
                    void (*context_reset)(void);
                    uintptr_t (*get_current_framebuffer)(void);
                    void *(*get_proc_address)(const char *);
                    bool depth;
                    bool stencil;
                    bool bottom_left_origin;
                    unsigned version_major;
                    unsigned version_minor;
                    bool cache_context;
                    void (*context_destroy)(void);
                    bool debug_context;
                };
                char v78[320];
                snprintf(v78,sizeof(v78),"V78 VULKAN ABI pointer_bytes=%zu callback_bytes=%zu reset_offset=%zu framebuffer_offset=%zu proc_offset=%zu destroy_offset=%zu",
                    sizeof(void*),sizeof(AzV78HWCallbackLayout),
                    offsetof(AzV78HWCallbackLayout,context_reset),
                    offsetof(AzV78HWCallbackLayout,get_current_framebuffer),
                    offsetof(AzV78HWCallbackLayout,get_proc_address),
                    offsetof(AzV78HWCallbackLayout,context_destroy));
                AzTrace(v78);
                AzTrace("V78 VULKAN BRIDGE GATE callback ABI inspected; next: create owned Vulkan device and implement libretro Vulkan negotiation and frame handoff");
                AzTrace("V78 VULKAN BRIDGE GATE status=NOT_READY; Vulkan request safely rejected; software fallback retained");
                // Castle 79: inspect the *actual* incoming Vulkan request's
                // callback configuration. Do not call any core-supplied pointer
                // or accept the context until frontend Vulkan lifecycle exists.
                if (contextType == RETRO_HW_CONTEXT_VULKAN) {
                    const AzV78HWCallbackLayout *request79 =
                        (const AzV78HWCallbackLayout *)data;
                    char audit79[384];
                    snprintf(audit79,sizeof(audit79),
                        "V79 REAL VULKAN CALLBACK version=%u.%u depth=%u stencil=%u bottom_left=%u cache_context=%u debug=%u",
                        request79->version_major,request79->version_minor,
                        (unsigned)request79->depth,(unsigned)request79->stencil,
                        (unsigned)request79->bottom_left_origin,
                        (unsigned)request79->cache_context,
                        (unsigned)request79->debug_context);
                    AzTrace(audit79);
                    snprintf(audit79,sizeof(audit79),
                        "V79 REAL VULKAN CALLBACK reset=%s framebuffer=%s proc_address=%s destroy=%s",
                        request79->context_reset?"provided":"null",
                        request79->get_current_framebuffer?"provided":"null",
                        request79->get_proc_address?"provided":"null",
                        request79->context_destroy?"provided":"null");
                    AzTrace(audit79);
                    AzTrace("V79 REAL VULKAN CALLBACK stage=REQUEST_CAPTURED; no callbacks invoked; awaiting owned Vulkan context and libretro interface");
                    // This is the first persistent piece of the real frontend
                    // bridge: retain the lifecycle contract by value so future
                    // context ownership cannot depend on a dangling pointer.
                    AzV80ClearRequest();
                    // Azahar reports Vulkan's packed VK_MAKE_API_VERSION encoding
                    // (0x00401000 for 1.1), not necessarily plain major=1.
                    // Accept either the packed Vulkan 1.x API encoding or the
                    // conventional libretro plain major/minor representation.
                    const unsigned rawMajor = request79->version_major;
                    const unsigned packedVariant = rawMajor >> 29;
                    const unsigned packedMajor = (rawMajor >> 22) & 0x7fu;
                    const unsigned packedMinor = (rawMajor >> 12) & 0x3ffu;
                    const unsigned packedPatch = rawMajor & 0xfffu;
                    const bool packedVersion = rawMajor >= (1u << 22);
                    const bool versionSupported = packedVersion
                        ? (packedVariant == 0 && packedMajor == 1)
                        : (rawMajor == 1 && request79->version_minor <= 3);
                    const bool lifecycleComplete = request79->context_reset &&
                        request79->context_destroy;
                    if (versionSupported) ++gAzV148VersionSupported;
                    if (lifecycleComplete) ++gAzV148LifecycleComplete;
                    if (versionSupported && lifecycleComplete) {
                        gAzV80Request.valid = true;
                        gAzV80Request.contextType = contextType;
                        gAzV80Request.major = request79->version_major;
                        gAzV80Request.minor = request79->version_minor;
                        gAzV80Request.depth = request79->depth;
                        gAzV80Request.stencil = request79->stencil;
                        gAzV80Request.bottomLeft = request79->bottom_left_origin;
                        gAzV80Request.cacheContext = request79->cache_context;
                        gAzV80Request.reset = request79->context_reset;
                        gAzV80Request.destroy = request79->context_destroy;
                    }
                    snprintf(audit79,sizeof(audit79),
                        "V80 CAPTURE valid=%u version_supported=%u lifecycle_complete=%u owned_copy=%u reset=%s destroy=%s",
                        (unsigned)gAzV80Request.valid,(unsigned)versionSupported,
                        (unsigned)lifecycleComplete,(unsigned)gAzV80Request.valid,
                        gAzV80Request.reset?"retained":"absent",
                        gAzV80Request.destroy?"retained":"absent");
                    AzTrace(audit79);
                    snprintf(audit79,sizeof(audit79),
                        "V81 VERSION DECODE raw_major=%u raw_minor=%u format=%s vulkan=%u.%u patch=%u supported=%u",
                        rawMajor,request79->version_minor,
                        packedVersion?"VK_API_VERSION":"plain",
                        packedVersion?packedMajor:rawMajor,
                        packedVersion?packedMinor:request79->version_minor,
                        packedVersion?packedPatch:0u,(unsigned)versionSupported);
                    AzTrace(audit79);
                    AzTrace("V81 CONTRACT state=VALIDATED_COPY_ONLY; no device, no Vulkan interface, hardware request still safely rejected");
                    AzTrace("V80 CAPTURE state=CONTRACT_RETAINED_ONLY; no Vulkan device, no callback invocation, hardware request rejected");
                }
            }
            // V174 deliberately crosses the *real* SET_HW_RENDER boundary only
            // in the disposable Vulkan preflight. Never signal a full bridge:
            // negotiation, device wrappers and HW image presentation are still
            // unavailable. Any further stage is explicitly refused.
            if (gAzV12ProbeVulkan && contextType == RETRO_HW_CONTEXT_VULKAN &&
                gAzV80Request.valid && AzaharV170LivePublicationPrerequisites() == 0xfu &&
                !gAzV174DiscoveryStage1) {
                gAzV174DiscoveryStage1 = true;
                AzTrace("V174 REAL_STAGE1_DISCOVERY request=VALID owned_device=READY callback_contract=VALID accepted=1 scope=DISPOSABLE_PREFLIGHT negotiation=NOT_IMPLEMENTED renderer_callbacks=NOT_INVOKED");
                return true;
            }
            snprintf(line, sizeof(line), "V12 HW SET_HW_RENDER context_type=%u (rejected: no frontend render interface)", contextType);
            AzTrace(line);
            if (gAzV12ProbeVulkan && contextType == RETRO_HW_CONTEXT_VULKAN) {
                AzTrace("V115 HANDSHAKE stage1 denied until official ABI, context callbacks, GPU exchange and presenter all exist");
                AzTrace("V13 HANDSHAKE Azahar source registers Vulkan negotiation only after SET_HW_RENDER succeeds");
                AzTrace("V13 HANDSHAKE accepting without retro_hw_render_interface_vulkan and frame handoff would be unsafe");
            }
        } else {
            AzTrace("ENV SET_HW_RENDER null callback (diagnostic; rejected)");
        }
        return false;
    }

    case RETRO_ENVIRONMENT_SET_HW_SHARED_CONTEXT:
        AzTrace("ENV SET_HW_SHARED_CONTEXT (diagnostic; rejected)");
        return false;

    // Castle 145: this branch is an observation of a *real* core request,
    // not the private ABI rehearsal. Do not dereference unknown extensions.
    case RETRO_ENVIRONMENT_SET_HW_RENDER_CONTEXT_NEGOTIATION_INTERFACE:
        if (data) {
            const unsigned *hdr = (const unsigned *)data;
            char line[200];
            ++gAzV12NegotiationRequests;
            if (gAzV174DiscoveryStage1 && gAzV12ProbeVulkan) {
                ++gAzV174DiscoveryStage2;
                char v174line[240];
                snprintf(v174line,sizeof(v174line),
                    "V174 REAL_STAGE2_OBSERVED interface_type=%u version=%u response=REJECTED unsupported_device_wrappers=1 no_core_callbacks_invoked=1",
                    hdr[0],hdr[1]);
                AzTrace(v174line);
                // Use the fully sized layout only for the v2 Vulkan contract.
                // No function pointers will be called, and no interface is
                // advertised as ready to the core.
                if (hdr[0] == 0u && hdr[1] == 2u) {
                    AzV175NegotiationV2View observed = {};
                    memcpy(&observed, data, sizeof(observed));
                    gAzV175Negotiation = observed;
                    gAzV175NegotiationCaptured = true;
                    ++gAzV175NegotiationCount;
                    gAzV175NegotiationValid = observed.get_application_info &&
                        (observed.create_device || observed.create_device2);
                    char v175line[320];
                    snprintf(v175line, sizeof(v175line),
                        "V175 REAL_NEGOTIATION_V2_CALLBACKS captured=1 app_info=%u create_device_v1=%u destroy_device=%u create_instance_v2=%u create_device_v2=%u required_present=%u callback_invocations=0 accepted=0",
                        (unsigned)(observed.get_application_info != nullptr),
                        (unsigned)(observed.create_device != nullptr),
                        (unsigned)(observed.destroy_device != nullptr),
                        (unsigned)(observed.create_instance != nullptr),
                        (unsigned)(observed.create_device2 != nullptr),
                        (unsigned)gAzV175NegotiationValid);
                    AzTrace(v175line);
                    // Castle 186: invoke v2 create_instance and create_device2
                    // on the actual core callback table with frontend wrappers.
                    // The scope is entirely disposable and never returned to Azahar.
                    // Older v1 tests below remain independent.
                    const unsigned v186V2 = (gAzV175NegotiationValid && observed.create_device2)
                        ? AzaharV186CoreV2WrappersGate(observed.get_application_info,
                            observed.create_instance,observed.create_device2,observed.destroy_device)
                        : 0u;
                    AzTrace(observed.create_device2
                        ? "V187 NEGOTIATION_SELECTION mode=V2_WRAPPER_AVAILABLE"
                        : observed.create_device
                          ? "V187 NEGOTIATION_SELECTION mode=V1_DEVICE_CALLBACK_IN_V2_STRUCTURE v2_optional=ABSENT status=SUPPORTED"
                          : "V187 NEGOTIATION_SELECTION mode=NO_DEVICE_CALLBACK status=BLOCKED");
                    char v186line[390];
                    snprintf(v186line,sizeof(v186line),
                        "V186 REAL_V2_WRAPPER_PATH mask=0x%x expected=0x3ff app=%u instance_wrapper=%u dispatch=%u gpu=%u device2_created=%u queue_valid=%u drained=%u resources_retired=%u scope_cleared=%u published=0 status=%s",
                        v186V2,(unsigned)!!(v186V2&2u),(unsigned)!!(v186V2&4u),
                        (unsigned)!!(v186V2&8u),(unsigned)!!(v186V2&16u),
                        (unsigned)!!(v186V2&32u),(unsigned)!!(v186V2&64u),
                        (unsigned)!!(v186V2&128u),(unsigned)!!(v186V2&256u),
                        (unsigned)!!(v186V2&512u),v186V2==0x3ffu?"PASS":"BLOCKED");
                    AzTrace(v186line);
                    AzTrace("V186 NEGOTIATION_SCOPE version=2 genuine_core_v2_callbacks=1 core_renderer=NOT_STARTED interface_publication=DISABLED software_fallback=ENABLED");
                    // The helper calls Azahar's real app-info callback and
                    // creates/destroys an actual VkInstance through the
                    // persistent frontend loader. Stage 2 still returns false.
                    if (gAzV175NegotiationValid) {
                        gAzV176LiveInstanceMask = AzaharV176CoreApplicationInstanceGate(observed.get_application_info);
                        char v176line[300];
                        snprintf(v176line, sizeof(v176line),
                            "V176 REAL_CORE_APP_INSTANCE mask=0x%x expected=0x3f core_callback=%u app_valid=%u version_valid=%u loader=%u instance_created=%u instance_destroyed=%u device_negotiated=0 status=%s",
                            gAzV176LiveInstanceMask,
                            (unsigned)((gAzV176LiveInstanceMask & 1u)!=0),
                            (unsigned)((gAzV176LiveInstanceMask & 2u)!=0),
                            (unsigned)((gAzV176LiveInstanceMask & 4u)!=0),
                            (unsigned)((gAzV176LiveInstanceMask & 8u)!=0),
                            (unsigned)((gAzV176LiveInstanceMask & 16u)!=0),
                            (unsigned)((gAzV176LiveInstanceMask & 32u)!=0),
                            gAzV176LiveInstanceMask == 0x3fu ? "PASS" : "BLOCKED");
                        AzTrace(v176line);
                        if (gAzV176LiveInstanceMask == 0x3fu && observed.create_device) {
                            gAzV177LiveDeviceMask = AzaharV177CoreDeviceGate(observed.get_application_info, observed.create_device);
                            char deviceLine[340];
                            snprintf(deviceLine,sizeof(deviceLine),
                                "V177 REAL_CORE_DEVICE mask=0x%x expected=0xff callback_available=%u app_valid=%u instance_created=%u physical_queue=%u device_created=%u queue_valid=%u device_destroyed=%u instance_destroyed=%u interface_published=0 status=%s",
                                gAzV177LiveDeviceMask,
                                (unsigned)((gAzV177LiveDeviceMask & 1u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 2u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 4u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 8u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 16u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 32u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 64u)!=0),
                                (unsigned)((gAzV177LiveDeviceMask & 128u)!=0),
                                gAzV177LiveDeviceMask == 0xffu ? "PASS" : "BLOCKED");
                            AzTrace(deviceLine);
                            if (gAzV177LiveDeviceMask == 0xffu) {
                                gAzV178RetainedMask = AzaharV178RetainCoreDevice(observed.get_application_info, observed.create_device);
                                char retainedLine[320];
                                snprintf(retainedLine,sizeof(retainedLine),
                                    "V178 CORE_DEVICE_RETENTION mask=0x%x expected=0xff state=0x%x persistent_through_callback=%u interface_published=0 status=%s",
                                    gAzV178RetainedMask,AzaharV178RetainedState(),
                                    (unsigned)((gAzV178RetainedMask&64u)!=0),
                                    gAzV178RetainedMask==0xffu ? "PASS":"BLOCKED");
                                AzTrace(retainedLine);
                                if (gAzV12ProbeVulkan && gAzV178RetainedMask==0xffu) {
                                    const unsigned staged=AzaharV187PublishPreflightInterface();
                                    char v187line[260];
                                    snprintf(v187line,sizeof(v187line),
                                        "V187 HARDWARE_INTERFACE_ACTIVATION mask=0x%x expected=0xff v1_core_device=1 official_v5=%u callbacks=%u gpu_consumer_dispatch=%u active=%u status=%s",
                                        staged,(unsigned)!!(staged&2u),(unsigned)!!(staged&16u),
                                        (unsigned)!!(staged&32u),(unsigned)(staged==0xffu),
                                        staged==0xffu?"PASS":"BLOCKED");
                                    AzTrace(v187line);
                                    gAzV187HardwareInterfaceActive=(staged==0xffu);
                                }
                            }
                        }
                    }
                } else {
                    AzTrace("V175 REAL_NEGOTIATION_V2_CALLBACKS captured=0 reason=UNSUPPORTED_ABI accepted=0");
                }
            }
            AzV148Event("SET_CONTEXT_NEGOTIATION", &gAzV148FirstNegotiation, hdr[1]);
            if (gAzV12ProbeVulkan && gAzV174DiscoveryStage1 &&
                gAzV187HardwareInterfaceActive && hdr[0]==0u && hdr[1]>=1u) {
                AzTrace("V187 REAL_STAGE2_NEGOTIATION accepted=1 mode=CORE_V1_DEVICE_WITH_V2_ABI scope=DISPOSABLE_PREFLIGHT");
                return true;
            }
            snprintf(line, sizeof(line), "V12 HW SET_CONTEXT_NEGOTIATION interface_type=%u version=%u (rejected)", hdr[0], hdr[1]);
            AzTrace(line);
        } else {
            AzTrace("V11 HW SET_CONTEXT_NEGOTIATION null interface (rejected)");
        }
        return false;

    case RETRO_ENVIRONMENT_GET_MICROPHONE_INTERFACE:
    case RETRO_ENVIRONMENT_GET_SENSOR_INTERFACE:
        return false;

    case RETRO_ENVIRONMENT_SHUTDOWN:
        return true;

    default: {
        char requestLog[128];
        snprintf(requestLog, sizeof(requestLog), "ENV unsupported command=%u (base=%u)", cmd, cmd & 0xFFFFu);
        AzTrace(requestLog);
        /*
         * Unknown optional frontend services should generally be reported as
         * unsupported. Azahar's libretro frontend code has fallbacks for the
         * services used by the software renderer.
         */
        return false;
    }
    }
}

- (instancetype)init
{
    AzTrace("01 entering AzaharGameCore init, before super");
    self = [super init];
    AzTrace("02 returned from super init");
    if (!self)
        return nil;

    AzTrace("03 assigning global core instance");
    gAzaharCore = self;

    // v197: fixed owned allocation handles either 400x480 or 800x480;
    // no reassignment/reallocation when the stereo mode changes.
    _videoBufferCapacity = (size_t)kAz197FullWidth*kNativeHeight*4u;
    _videoBuffer = (uint8_t *)calloc(1, _videoBufferCapacity);
    _az191OwnsVideoBuffer = YES;
    _videoSize = OEIntSizeMake(kNativeWidth, kNativeHeight);

    _variables = [NSMutableDictionary dictionary];
    _az191Resolution = 1;
    _az191Stereo = @"off";
    _az195Depth = 80; // nearest selectable increment to the former fixed 85%
    _az191OptionDirty = NO;
    _az191GeometryChanges = 0;
    _az193StablePresentation = NO;
    _az197PresentationLocked = NO;
    _az197SessionWidth = kNativeWidth;
    _az197SessionHeight = kNativeHeight;
    _az207PendingHostScale=1u;
    _az207ActiveHostScale=1u;
    _az207RealHighResFrames=0u;
    _az207HostFrames=0u;
    _az207ExactCopyFrames=0u;
    _az208PaddedHost=false;
    _az208VisibleWidth=kNativeWidth;
    _az208VisibleHeight=kNativeHeight;
    _az208StartupFrames=0u;
    _az208HiResPublished=0u;
    _az208CompactFrame=nullptr;
    _az208CompactCapacity=0u;
    _az209PitchCopies=0u;
    _az209PitchPass=0u;
    _az209PitchFail=0u;
    _az209PitchTotalUs=0u;
    _az209PitchMaxUs=0u;
    _az209NativeStartCopies=0u;
    _az209HiResCopies=0u;
    _az197TransitionCount=0;
    _az197ReportFrames=0;
    _az193NormalizedFrames = 0;
    _az194StartupReassertFrames = 0;
    Az191ApplyGraphicsOptions(self);

    AzTrace("04 completed AzaharGameCore init");
    return self;
}

- (void)dealloc
{
    if (_gameLoaded && _retroUnloadGame) {
        _retroUnloadGame();
        _gameLoaded=NO;
    }
    [self azV188RetireLiveHardware];
    if (_initialized && _retroDeinit)
        _retroDeinit();

    if (_azaharHandle)
        dlclose(_azaharHandle);

    if (_az208CompactFrame) {free(_az208CompactFrame); _az208CompactFrame=nullptr;}
    _az208CompactCapacity=0u;
    if (_az191OwnsVideoBuffer) free(_videoBuffer);
    free(_az189ReadbackScratch);
    free(_stableRomPath);

    if (gAzaharCore == self)
        gAzaharCore = nil;
}

#pragma mark - Libretro loading

// GPU experiment 09: temporary Vulkan instance, physical GPU and logical device probe.
// Does not hand any Vulkan objects to libretro and does not alter software rendering.
// Minimal Vulkan 1.0 ABI definitions keep the existing Xcode project independent
// of a system Vulkan SDK. MoltenVK is loaded from the core bundle.
typedef uint32_t AzVkFlags;
typedef int32_t AzVkResult;
typedef struct AzVkInstance_T *AzVkInstance;
typedef struct AzVkPhysicalDevice_T *AzVkPhysicalDevice;
typedef void (*AzVkVoidFunction)(void);
struct AzVkApplicationInfo {
    uint32_t sType; const void *pNext; const char *pApplicationName;
    uint32_t applicationVersion; const char *pEngineName;
    uint32_t engineVersion; uint32_t apiVersion;
};
struct AzVkInstanceCreateInfo {
    uint32_t sType; const void *pNext; AzVkFlags flags;
    const struct AzVkApplicationInfo *pApplicationInfo;
    uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
    uint32_t enabledExtensionCount; const char *const *ppEnabledExtensionNames;
};
struct AzVkExtensionProperties { char extensionName[256]; uint32_t specVersion; };
typedef AzVkVoidFunction (*AzVkGetInstanceProcAddr)(AzVkInstance, const char *);
typedef AzVkResult (*AzVkEnumerateInstanceExtensionProperties)(const char *, uint32_t *, struct AzVkExtensionProperties *);
typedef AzVkResult (*AzVkCreateInstance)(const struct AzVkInstanceCreateInfo *, const void *, AzVkInstance *);
typedef void (*AzVkDestroyInstance)(AzVkInstance, const void *);
typedef AzVkResult (*AzVkEnumeratePhysicalDevices)(AzVkInstance, uint32_t *, AzVkPhysicalDevice *);
// V15: ABI-compatible Vulkan surface declarations (no Vulkan SDK required).
// VK_STRUCTURE_TYPE_METAL_SURFACE_CREATE_INFO_EXT = 1000217000.
typedef struct AzVkSurfaceKHR_T *AzVkSurfaceKHR;
struct AzVkMetalSurfaceCreateInfoEXT {
    uint32_t sType; const void *pNext; AzVkFlags flags; const void *pLayer;
};
typedef AzVkResult (*AzVkCreateMetalSurfaceEXT)(AzVkInstance, const AzVkMetalSurfaceCreateInfoEXT *, const void *, AzVkSurfaceKHR *);
typedef void (*AzVkDestroySurfaceKHR)(AzVkInstance, AzVkSurfaceKHR, const void *);
typedef AzVkResult (*AzVkGetPhysicalDeviceSurfaceSupportKHR)(AzVkPhysicalDevice, uint32_t, AzVkSurfaceKHR, uint32_t *);

// V14: inspect actual device extension support before designing frontend-owned GPU resources.
typedef AzVkResult (*AzVkEnumerateDeviceExtensionProperties)(AzVkPhysicalDevice, const char *, uint32_t *, AzVkExtensionProperties *);
typedef struct AzVkDevice_T *AzVkDevice;
typedef struct AzVkQueue_T *AzVkQueue;
struct AzVkExtent3D { uint32_t width, height, depth; };
struct AzVkQueueFamilyProperties {
    AzVkFlags queueFlags; uint32_t queueCount; uint32_t timestampValidBits;
    struct AzVkExtent3D minImageTransferGranularity;
};
struct AzVkDeviceQueueCreateInfo {
    uint32_t sType; const void *pNext; AzVkFlags flags;
    uint32_t queueFamilyIndex; uint32_t queueCount; const float *pQueuePriorities;
};
struct AzVkDeviceCreateInfo {
    uint32_t sType; const void *pNext; AzVkFlags flags;
    uint32_t queueCreateInfoCount; const struct AzVkDeviceQueueCreateInfo *pQueueCreateInfos;
    uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
    uint32_t enabledExtensionCount; const char *const *ppEnabledExtensionNames;
    const void *pEnabledFeatures;
};
typedef void (*AzVkGetPhysicalDeviceQueueFamilyProperties)(AzVkPhysicalDevice, uint32_t *, struct AzVkQueueFamilyProperties *);
typedef AzVkResult (*AzVkCreateDevice)(AzVkPhysicalDevice, const struct AzVkDeviceCreateInfo *, const void *, AzVkDevice *);
typedef void (*AzVkDestroyDevice)(AzVkDevice, const void *);
typedef void (*AzVkGetDeviceQueue)(AzVkDevice, uint32_t, uint32_t, AzVkQueue *);

typedef struct AzVkCommandPool_T *AzVkCommandPool;
typedef struct AzVkCommandBuffer_T *AzVkCommandBuffer;
typedef struct AzVkFence_T *AzVkFence;
struct AzVkCommandPoolCreateInfo { uint32_t sType; const void *pNext; AzVkFlags flags; uint32_t queueFamilyIndex; };
struct AzVkCommandBufferAllocateInfo { uint32_t sType; const void *pNext; AzVkCommandPool commandPool; uint32_t level; uint32_t commandBufferCount; };
struct AzVkCommandBufferBeginInfo { uint32_t sType; const void *pNext; AzVkFlags flags; const void *pInheritanceInfo; };
struct AzVkSubmitInfo { uint32_t sType; const void *pNext; uint32_t waitSemaphoreCount; const void *pWaitSemaphores; const void *pWaitDstStageMask; uint32_t commandBufferCount; const AzVkCommandBuffer *pCommandBuffers; uint32_t signalSemaphoreCount; const void *pSignalSemaphores; };
struct AzVkFenceCreateInfo { uint32_t sType; const void *pNext; AzVkFlags flags; };
typedef AzVkVoidFunction (*AzVkGetDeviceProcAddr)(AzVkDevice, const char *);
typedef AzVkResult (*AzVkCreateCommandPool)(AzVkDevice, const AzVkCommandPoolCreateInfo *, const void *, AzVkCommandPool *);
typedef void (*AzVkDestroyCommandPool)(AzVkDevice, AzVkCommandPool, const void *);
typedef AzVkResult (*AzVkAllocateCommandBuffers)(AzVkDevice, const AzVkCommandBufferAllocateInfo *, AzVkCommandBuffer *);
typedef AzVkResult (*AzVkBeginCommandBuffer)(AzVkCommandBuffer, const AzVkCommandBufferBeginInfo *);
typedef AzVkResult (*AzVkEndCommandBuffer)(AzVkCommandBuffer);
typedef AzVkResult (*AzVkCreateFence)(AzVkDevice, const AzVkFenceCreateInfo *, const void *, AzVkFence *);
typedef void (*AzVkDestroyFence)(AzVkDevice, AzVkFence, const void *);
typedef AzVkResult (*AzVkQueueSubmit)(AzVkQueue, uint32_t, const AzVkSubmitInfo *, AzVkFence);
typedef AzVkResult (*AzVkWaitForFences)(AzVkDevice, uint32_t, const AzVkFence *, uint32_t, uint64_t);



static void AzProbeVulkanLoader(void)
{
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *bundled = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    const char *bundledPath = bundled.fileSystemRepresentation;
    if (![[NSFileManager defaultManager] fileExistsAtPath:bundled]) {
        AzTrace("GPU PROBE bundled MoltenVK file MISSING; skipping Vulkan device discovery");
        return;
    }
    AzTrace("GPU PROBE bundled MoltenVK file present");
    void *handle = dlopen(bundledPath, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        char line[512];
        snprintf(line, sizeof(line), "GPU PROBE MoltenVK dlopen failed: %.390s", dlerror() ?: "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("GPU PROBE bundled MoltenVK dlopen succeeded");
    AzVkGetInstanceProcAddr getProc = (AzVkGetInstanceProcAddr)dlsym(handle, "vkGetInstanceProcAddr");
    if (!getProc) {
        AzTrace("GPU PROBE vkGetInstanceProcAddr MISSING");
        dlclose(handle);
        return;
    }
    AzTrace("GPU PROBE vkGetInstanceProcAddr available");
    AzVkEnumerateInstanceExtensionProperties extensions =
        (AzVkEnumerateInstanceExtensionProperties)getProc(nullptr, "vkEnumerateInstanceExtensionProperties");
    AzVkCreateInstance create = (AzVkCreateInstance)getProc(nullptr, "vkCreateInstance");
    if (!extensions || !create) {
        AzTrace("GPU PROBE required Vulkan instance functions MISSING");
        dlclose(handle);
        return;
    }
    bool portability = false;
    bool metalSurface = false;
    bool surface = false;
    uint32_t extensionCount = 0;
    AzVkResult result = extensions(nullptr, &extensionCount, nullptr);
    if (result == 0 && extensionCount > 0 && extensionCount < 4096) {
        AzVkExtensionProperties *items = (AzVkExtensionProperties *)calloc(extensionCount, sizeof(*items));
        if (items) {
            result = extensions(nullptr, &extensionCount, items);
            if (result == 0) {
                for (uint32_t i = 0; i < extensionCount; ++i) {
                    if (strcmp(items[i].extensionName, "VK_KHR_portability_enumeration") == 0)
                        portability = true;
                    if (strcmp(items[i].extensionName, "VK_EXT_metal_surface") == 0) metalSurface = true;
                    if (strcmp(items[i].extensionName, "VK_KHR_surface") == 0) surface = true;
                }
            }
            free(items);
        }
    }
    AzTrace(portability ? "GPU PROBE portability enumeration extension available" :
                          "GPU PROBE portability enumeration extension unavailable");
    AzTrace(metalSurface ? "V14 INSTANCE VK_EXT_metal_surface available" : "V14 INSTANCE VK_EXT_metal_surface unavailable");
    AzTrace(surface ? "V14 INSTANCE VK_KHR_surface available" : "V14 INSTANCE VK_KHR_surface unavailable");
    AzTrace("V14 AUDIT instance extensions are capabilities only; no VkSurfaceKHR or Metal layer is created");
    // V15 enables the surface extensions only for this disposable probe instance.
    const char *enabledExtensions[3];
    uint32_t enabledCount = 0;
    if (portability) enabledExtensions[enabledCount++] = "VK_KHR_portability_enumeration";
    if (surface && metalSurface) {
        enabledExtensions[enabledCount++] = "VK_KHR_surface";
        enabledExtensions[enabledCount++] = "VK_EXT_metal_surface";
        AzTrace("V15 SURFACE required instance extensions enabled");
    } else {
        AzTrace("V15 SURFACE required extensions unavailable; surface probe skipped");
    }
    // Vulkan sType: APPLICATION_INFO=0, INSTANCE_CREATE_INFO=1.
    // VK_INSTANCE_CREATE_ENUMERATE_PORTABILITY_BIT_KHR = 0x00000001.
    const AzVkApplicationInfo app = {0, nullptr, "OpenEmu Azahar Vulkan Probe", 1,
                                     "Azahar", 1, (1u << 22)};
    const AzVkInstanceCreateInfo info = {1, nullptr, portability ? 1u : 0u,
                                         &app, 0, nullptr, enabledCount,
                                         enabledExtensions};
    AzVkInstance instance = nullptr;
    result = create(&info, nullptr, &instance);
    {
        char line[160];
        snprintf(line, sizeof(line), "GPU PROBE vkCreateInstance result=%d", (int)result);
        AzTrace(line);
    }
    if (result == 0 && instance) {
        AzVkEnumeratePhysicalDevices enumerate =
            (AzVkEnumeratePhysicalDevices)getProc(instance, "vkEnumeratePhysicalDevices");
        AzVkDestroyInstance destroy =
            (AzVkDestroyInstance)getProc(instance, "vkDestroyInstance");
        // V15: create and destroy a genuine VkSurfaceKHR with an owned, unattached
        // CAMetalLayer. This is a presentation capability test, not an OpenEmu view.
        // Keep the layer alive through vkDestroySurfaceKHR; never share this instance.
        AzVkSurfaceKHR probeSurface = nullptr;
        CAMetalLayer *probeLayer = nil;
        AzVkDestroySurfaceKHR destroySurface = nullptr;
        if (surface && metalSurface) {
            AzVkCreateMetalSurfaceEXT createMetalSurface =
                (AzVkCreateMetalSurfaceEXT)getProc(instance, "vkCreateMetalSurfaceEXT");
            destroySurface = (AzVkDestroySurfaceKHR)getProc(instance, "vkDestroySurfaceKHR");
            if (createMetalSurface && destroySurface) {
                probeLayer = [CAMetalLayer layer];
                probeLayer.framebufferOnly = YES;
                probeLayer.drawableSize = CGSizeMake(400, 480);
                const AzVkMetalSurfaceCreateInfoEXT surfaceInfo = {1000217000u, nullptr, 0, (__bridge const void *)probeLayer};
                AzVkResult surfaceResult = createMetalSurface(instance, &surfaceInfo, nullptr, &probeSurface);
                char surfaceLine[200];
                snprintf(surfaceLine, sizeof(surfaceLine), "V15 SURFACE vkCreateMetalSurfaceEXT result=%d created=%s", (int)surfaceResult, probeSurface ? "yes" : "no");
                AzTrace(surfaceLine);
                if (surfaceResult != 0) probeSurface = nullptr;
            } else AzTrace("V15 SURFACE create/destroy function missing; skipped");
        }
        if (enumerate) {
            uint32_t deviceCount = 0;
            result = enumerate(instance, &deviceCount, nullptr);
            char line[160];
            snprintf(line, sizeof(line), "GPU PROBE vkEnumeratePhysicalDevices result=%d count=%u",
                     (int)result, (unsigned)deviceCount);
            AzTrace(line);
            if (result == 0 && deviceCount > 0 && deviceCount < 128) {
                AzVkPhysicalDevice *physicalDevices = (AzVkPhysicalDevice *)calloc(deviceCount, sizeof(*physicalDevices));
                if (physicalDevices) {
                    result = enumerate(instance, &deviceCount, physicalDevices);
                    if (result == 0 && deviceCount > 0) {
                        if (probeSurface) {
                            AzVkGetPhysicalDeviceSurfaceSupportKHR getSurfaceSupport =
                                (AzVkGetPhysicalDeviceSurfaceSupportKHR)getProc(instance, "vkGetPhysicalDeviceSurfaceSupportKHR");
                            AzVkGetPhysicalDeviceQueueFamilyProperties getSurfaceFamilies =
                                (AzVkGetPhysicalDeviceQueueFamilyProperties)getProc(instance, "vkGetPhysicalDeviceQueueFamilyProperties");
                            if (getSurfaceSupport && getSurfaceFamilies) {
                                uint32_t count = 0;
                                getSurfaceFamilies(physicalDevices[0], &count, nullptr);
                                bool presentable = false;
                                if (count > 0 && count < 256) {
                                    AzVkQueueFamilyProperties *props = (AzVkQueueFamilyProperties *)calloc(count, sizeof(*props));
                                    if (props) {
                                        getSurfaceFamilies(physicalDevices[0], &count, props);
                                        for (uint32_t i = 0; i < count; ++i) {
                                            uint32_t supported = 0;
                                            AzVkResult sr = getSurfaceSupport(physicalDevices[0], i, probeSurface, &supported);
                                            if (sr == 0 && supported && props[i].queueCount) {
                                                char supportLine[160];
                                                snprintf(supportLine, sizeof(supportLine), "V15 SURFACE present-capable queue family=%u graphics=%s", (unsigned)i, (props[i].queueFlags & 1u) ? "yes" : "no");
                                                AzTrace(supportLine);
                                                presentable = true;
                                            }
                                        }
                                        free(props);
                                    }
                                }
                                AzTrace(presentable ? "V15 SURFACE presentation support confirmed" : "V15 SURFACE no present-capable queue confirmed");
                            } else AzTrace("V15 SURFACE support-query functions missing");
                        }
                        // Read-only Vulkan capability audit. No extension is enabled
                        // and no libretro hardware interface is claimed.
                        AzVkEnumerateDeviceExtensionProperties deviceExtensions =
                            (AzVkEnumerateDeviceExtensionProperties)getProc(instance, "vkEnumerateDeviceExtensionProperties");
                        if (deviceExtensions) {
                            uint32_t count = 0;
                            AzVkResult er = deviceExtensions(physicalDevices[0], nullptr, &count, nullptr);
                            char extLine[200];
                            snprintf(extLine, sizeof(extLine), "V14 DEVICE extension enumeration result=%d count=%u", (int)er, (unsigned)count);
                            AzTrace(extLine);
                            if (er == 0 && count > 0 && count < 4096) {
                                AzVkExtensionProperties *properties = (AzVkExtensionProperties *)calloc(count, sizeof(*properties));
                                if (properties) {
                                    er = deviceExtensions(physicalDevices[0], nullptr, &count, properties);
                                    if (er == 0) {
                                        bool swapchain = false, subset = false, externalMemory = false;
                                        for (uint32_t i = 0; i < count; ++i) {
                                            if (strcmp(properties[i].extensionName, "VK_KHR_swapchain") == 0) swapchain = true;
                                            if (strcmp(properties[i].extensionName, "VK_KHR_portability_subset") == 0) subset = true;
                                            if (strcmp(properties[i].extensionName, "VK_KHR_external_memory") == 0) externalMemory = true;
                                        }
                                        AzTrace(swapchain ? "V14 DEVICE VK_KHR_swapchain available" : "V14 DEVICE VK_KHR_swapchain unavailable");
                                        AzTrace(subset ? "V14 DEVICE VK_KHR_portability_subset available" : "V14 DEVICE VK_KHR_portability_subset unavailable");
                                        AzTrace(externalMemory ? "V14 DEVICE VK_KHR_external_memory available" : "V14 DEVICE VK_KHR_external_memory unavailable");
                                    } else AzTrace("V14 DEVICE extension detail enumeration failed");
                                    free(properties);
                                }
                            }
                        } else AzTrace("V14 DEVICE vkEnumerateDeviceExtensionProperties unavailable");
                        AzTrace("V14 AUDIT separate probe VkDevice must NOT be handed to Azahar; shared ownership and image synchronization not implemented");
                        AzVkGetPhysicalDeviceQueueFamilyProperties getFamilies =
                            (AzVkGetPhysicalDeviceQueueFamilyProperties)getProc(instance, "vkGetPhysicalDeviceQueueFamilyProperties");
                        AzVkCreateDevice createDevice = (AzVkCreateDevice)getProc(instance, "vkCreateDevice");
                        if (getFamilies && createDevice) {
                            uint32_t familyCount = 0;
                            getFamilies(physicalDevices[0], &familyCount, nullptr);
                            snprintf(line, sizeof(line), "GPU PROBE queue family count=%u", (unsigned)familyCount);
                            AzTrace(line);
                            if (familyCount > 0 && familyCount < 256) {
                                AzVkQueueFamilyProperties *families = (AzVkQueueFamilyProperties *)calloc(familyCount, sizeof(*families));
                                if (families) {
                                    getFamilies(physicalDevices[0], &familyCount, families);
                                    uint32_t graphicsFamily = UINT32_MAX;
                                    for (uint32_t i = 0; i < familyCount; ++i) {
                                        // VK_QUEUE_GRAPHICS_BIT = 0x1.
                                        if ((families[i].queueFlags & 1u) && families[i].queueCount > 0) {
                                            graphicsFamily = i;
                                            break;
                                        }
                                    }
                                    if (graphicsFamily != UINT32_MAX) {
                                        snprintf(line, sizeof(line), "GPU PROBE graphics queue family=%u", (unsigned)graphicsFamily);
                                        AzTrace(line);
                                        float priority = 1.0f;
                                        // Vulkan sType: DEVICE_QUEUE_CREATE_INFO=2, DEVICE_CREATE_INFO=3.
                                        const AzVkDeviceQueueCreateInfo queueInfo = {2, nullptr, 0, graphicsFamily, 1, &priority};
                                        const AzVkDeviceCreateInfo deviceInfo = {3, nullptr, 0, 1, &queueInfo,
                                                                                 0, nullptr, 0, nullptr, nullptr};
                                        AzVkDevice device = nullptr;
                                        AzVkResult deviceResult = createDevice(physicalDevices[0], &deviceInfo, nullptr, &device);
                                        snprintf(line, sizeof(line), "GPU PROBE vkCreateDevice result=%d", (int)deviceResult);
                                        AzTrace(line);
                                        if (deviceResult == 0 && device) {
                                            AzVkGetDeviceQueue getQueue =
                                                (AzVkGetDeviceQueue)getProc(instance, "vkGetDeviceQueue");
                                            AzVkDestroyDevice destroyDevice =
                                                (AzVkDestroyDevice)getProc(instance, "vkDestroyDevice");
                                            if (getQueue) {
                                                AzVkQueue queue = nullptr;
                                                getQueue(device, graphicsFamily, 0, &queue);
                                                AzTrace(queue ? "GPU PROBE graphics queue acquired" : "GPU PROBE graphics queue NULL");
                                                // Vulkan command-buffer and fence structures use core Vulkan 1.0 ABI.
                                                // Resolve device commands through vkGetDeviceProcAddr.
                                                AzVkGetDeviceProcAddr gdpa = (AzVkGetDeviceProcAddr)getProc(instance, "vkGetDeviceProcAddr");
                                                if (queue && gdpa) {
                                                    AzVkCreateCommandPool createPool = (AzVkCreateCommandPool)gdpa(device, "vkCreateCommandPool");
                                                    AzVkDestroyCommandPool destroyPool = (AzVkDestroyCommandPool)gdpa(device, "vkDestroyCommandPool");
                                                    AzVkAllocateCommandBuffers allocateBuffers = (AzVkAllocateCommandBuffers)gdpa(device, "vkAllocateCommandBuffers");
                                                    AzVkBeginCommandBuffer beginBuffer = (AzVkBeginCommandBuffer)gdpa(device, "vkBeginCommandBuffer");
                                                    AzVkEndCommandBuffer endBuffer = (AzVkEndCommandBuffer)gdpa(device, "vkEndCommandBuffer");
                                                    AzVkCreateFence createFence = (AzVkCreateFence)gdpa(device, "vkCreateFence");
                                                    AzVkDestroyFence destroyFence = (AzVkDestroyFence)gdpa(device, "vkDestroyFence");
                                                    AzVkQueueSubmit queueSubmit = (AzVkQueueSubmit)gdpa(device, "vkQueueSubmit");
                                                    AzVkWaitForFences waitFences = (AzVkWaitForFences)gdpa(device, "vkWaitForFences");
                                                    if (createPool && destroyPool && allocateBuffers && beginBuffer && endBuffer && createFence && destroyFence && queueSubmit && waitFences) {
                                                        // sType COMMAND_POOL_CREATE_INFO=39, COMMAND_BUFFER_ALLOCATE_INFO=40,
                                                        // COMMAND_BUFFER_BEGIN_INFO=42, SUBMIT_INFO=4, FENCE_CREATE_INFO=8.
                                                        AzVkCommandPool pool = nullptr;
                                                        const AzVkCommandPoolCreateInfo poolInfo = {39, nullptr, 0, graphicsFamily};
                                                        AzVkResult r = createPool(device, &poolInfo, nullptr, &pool);
                                                        snprintf(line, sizeof(line), "GPU PROBE vkCreateCommandPool result=%d", (int)r); AzTrace(line);
                                                        if (r == 0 && pool) {
                                                            AzVkCommandBuffer buffer = nullptr;
                                                            const AzVkCommandBufferAllocateInfo allocInfo = {40, nullptr, pool, 0, 1};
                                                            r = allocateBuffers(device, &allocInfo, &buffer);
                                                            snprintf(line, sizeof(line), "GPU PROBE vkAllocateCommandBuffers result=%d", (int)r); AzTrace(line);
                                                            if (r == 0 && buffer) {
                                                                const AzVkCommandBufferBeginInfo beginInfo = {42, nullptr, 1u, nullptr}; // ONE_TIME_SUBMIT
                                                                r = beginBuffer(buffer, &beginInfo);
                                                                snprintf(line, sizeof(line), "GPU PROBE vkBeginCommandBuffer result=%d", (int)r); AzTrace(line);
                                                                if (r == 0) {
                                                                    r = endBuffer(buffer); // Empty but valid executable command buffer.
                                                                    snprintf(line, sizeof(line), "GPU PROBE vkEndCommandBuffer result=%d", (int)r); AzTrace(line);
                                                                    if (r == 0) {
                                                                        AzVkFence fence = nullptr;
                                                                        const AzVkFenceCreateInfo fenceInfo = {8, nullptr, 0};
                                                                        r = createFence(device, &fenceInfo, nullptr, &fence);
                                                                        snprintf(line, sizeof(line), "GPU PROBE vkCreateFence result=%d", (int)r); AzTrace(line);
                                                                        if (r == 0 && fence) {
                                                                            const AzVkSubmitInfo submitInfo = {4, nullptr, 0, nullptr, nullptr, 1, &buffer, 0, nullptr};
                                                                            r = queueSubmit(queue, 1, &submitInfo, fence);
                                                                            snprintf(line, sizeof(line), "GPU PROBE vkQueueSubmit result=%d", (int)r); AzTrace(line);
                                                                            if (r == 0) {
                                                                                // 5 seconds, never wait indefinitely.
                                                                                AzVkResult waited = waitFences(device, 1, &fence, 1, 5000000000ULL);
                                                                                snprintf(line, sizeof(line), "GPU PROBE vkWaitForFences result=%d", (int)waited); AzTrace(line);
                                                                                if (waited == 0) AzTrace("GPU PROBE command submission completed successfully");
                                                                                // If the GPU timed out, do not destroy in-flight resources.
                                                                                if (waited != 0) AzTrace("GPU PROBE WARNING fence wait unsuccessful; cleanup may block if work remains in flight");
                                                                            }
                                                                            destroyFence(device, fence, nullptr);
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                            destroyPool(device, pool, nullptr);
                                                            AzTrace("GPU PROBE vkDestroyCommandPool completed");
                                                        }
                                                    } else AzTrace("GPU PROBE command submission functions unavailable");
                                                } else AzTrace("GPU PROBE vkGetDeviceProcAddr unavailable or queue missing");
                                            } else AzTrace("GPU PROBE vkGetDeviceQueue unavailable");
                                            if (destroyDevice) {
                                                destroyDevice(device, nullptr);
                                                AzTrace("GPU PROBE vkDestroyDevice completed");
                                            } else AzTrace("GPU PROBE WARNING vkDestroyDevice unavailable");
                                        }
                                    } else AzTrace("GPU PROBE no graphics-capable queue family");
                                    free(families);
                                }
                            }
                        } else AzTrace("GPU PROBE logical-device functions unavailable");
                    } else AzTrace("GPU PROBE physical device list retrieval failed");
                    free(physicalDevices);
                }
            }
        } else {
            AzTrace("GPU PROBE vkEnumeratePhysicalDevices unavailable");
        }
        if (probeSurface && destroySurface) {
            destroySurface(instance, probeSurface, nullptr);
            probeSurface = nullptr;
            AzTrace("V15 SURFACE vkDestroySurfaceKHR completed");
        }
        probeLayer = nil;
        if (destroy) destroy(instance, nullptr);
        else AzTrace("GPU PROBE WARNING vkDestroyInstance unavailable");
    }
    dlclose(handle);
    AzTrace("GPU PROBE finished; software rendering remains selected");
}

// V19: passive bundle audit only. No dlopen, Vulkan entry-point calls,
// Metal layer creation, GPU enumeration, or mutation of video state.
static void AzV19AuditBundledVulkan(void)
{
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *resources = [bundle resourcePath];
    NSString *molten = [resources stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    NSString *retro = [resources stringByAppendingPathComponent:@"azahar_libretro.dylib"];
    NSFileManager *fm = [NSFileManager defaultManager];
    NSDictionary *mv = [fm attributesOfItemAtPath:molten error:nil];
    NSDictionary *lr = [fm attributesOfItemAtPath:retro error:nil];
    char line[320];
    snprintf(line, sizeof(line),
             "V19 PASSIVE MoltenVK present=%s bytes=%llu; libretro present=%s bytes=%llu",
             [fm isReadableFileAtPath:molten] ? "yes" : "no",
             (unsigned long long)[mv fileSize],
             [fm isReadableFileAtPath:retro] ? "yes" : "no",
             (unsigned long long)[lr fileSize]);
    AzTrace(line);
    AzTrace("V19 PASSIVE no Vulkan loader opened; no Vulkan/Metal GPU work performed");
}

// V20: isolate dynamic-loader activity without creating a Vulkan instance.
// Run before Azahar's libretro library is loaded; never touch the video path.
static void AzV20OpenCloseMoltenVK(void)
{
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V20 LOADER before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *reason = dlerror();
        char line[420];
        snprintf(line, sizeof(line), "V20 LOADER dlopen failed: %.350s", reason ? reason : "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("V20 LOADER dlopen succeeded");
    dlerror();
    void *symbol = dlsym(handle, "vkGetInstanceProcAddr");
    const char *symbolError = dlerror();
    AzTrace((symbol && !symbolError) ? "V20 LOADER vkGetInstanceProcAddr symbol found (not called)"
                                     : "V20 LOADER vkGetInstanceProcAddr symbol missing");
    AzTrace("V20 LOADER before dlclose bundled MoltenVK");
    int result = dlclose(handle);
    AzTrace(result == 0 ? "V20 LOADER dlclose succeeded" : "V20 LOADER dlclose failed");
    AzTrace("V20 LOADER no Vulkan entry points called; no GPU work performed");
}

// V21: invoke only the Vulkan loader's instance-version query. No instance is created.
// vkEnumerateInstanceVersion was introduced in Vulkan 1.1, so absence is allowed.
static void AzV21QueryInstanceVersion(void)
{
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V21 VERSION before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *reason = dlerror();
        char line[420];
        snprintf(line, sizeof(line), "V21 VERSION dlopen failed: %.350s", reason ? reason : "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("V21 VERSION dlopen succeeded");
    // vkEnumerateInstanceVersion(VkVersion*): VkResult (int32_t) and uint32_t*.
    typedef int32_t (*az_vkEnumerateInstanceVersion_t)(uint32_t *);
    dlerror();
    void *raw = dlsym(handle, "vkEnumerateInstanceVersion");
    const char *symbolError = dlerror();
    if (symbolError || !raw) {
        AzTrace("V21 VERSION vkEnumerateInstanceVersion unavailable (Vulkan 1.0 loader possible)");
    } else {
        az_vkEnumerateInstanceVersion_t enumerate = (az_vkEnumerateInstanceVersion_t)raw;
        uint32_t version = 0;
        AzTrace("V21 VERSION before vkEnumerateInstanceVersion call");
        int32_t result = enumerate(&version);
        char line[220];
        snprintf(line, sizeof(line),
                 "V21 VERSION vkEnumerateInstanceVersion result=%d api=%u.%u.%u raw=0x%08x",
                 (int)result, (unsigned)(version >> 22),
                 (unsigned)((version >> 12) & 0x3ff), (unsigned)(version & 0xfff),
                 (unsigned)version);
        AzTrace(line);
    }
    AzTrace("V21 VERSION before dlclose bundled MoltenVK");
    int closeResult = dlclose(handle);
    AzTrace(closeResult == 0 ? "V21 VERSION dlclose succeeded" : "V21 VERSION dlclose failed");
    AzTrace("V21 VERSION no Vulkan instance/device/surface/swapchain created; software renderer unchanged");
}

// V22: read-only Vulkan instance extension enumeration. No instance is created.
static void AzV22EnumerateInstanceExtensions(void)
{
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V22 EXT before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *reason = dlerror();
        char line[420];
        snprintf(line, sizeof(line), "V22 EXT dlopen failed: %.350s", reason ? reason : "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("V22 EXT dlopen succeeded");
    // Vulkan ABI: VkExtensionProperties { char extensionName[256]; uint32_t specVersion; }.
    typedef struct { char extensionName[256]; uint32_t specVersion; } AzVkExtensionProperty;
    typedef int32_t (*AzVkEnumerateInstanceExtensions)(const char *, uint32_t *, AzVkExtensionProperty *);
    dlerror();
    void *raw = dlsym(handle, "vkEnumerateInstanceExtensionProperties");
    const char *symbolError = dlerror();
    if (symbolError || !raw) {
        AzTrace("V22 EXT vkEnumerateInstanceExtensionProperties symbol unavailable");
    } else {
        AzVkEnumerateInstanceExtensions enumerate = (AzVkEnumerateInstanceExtensions)raw;
        uint32_t count = 0;
        AzTrace("V22 EXT before count query (layerName=NULL)");
        int32_t result = enumerate(NULL, &count, NULL);
        char line[440];
        snprintf(line, sizeof(line), "V22 EXT count query result=%d count=%u", (int)result, (unsigned)count);
        AzTrace(line);
        if (result == 0 && count > 0 && count <= 256) {
            AzVkExtensionProperty *properties = (AzVkExtensionProperty *)calloc(count, sizeof(AzVkExtensionProperty));
            if (properties) {
                uint32_t capacity = count;
                AzTrace("V22 EXT before properties query");
                result = enumerate(NULL, &capacity, properties);
                snprintf(line, sizeof(line), "V22 EXT properties query result=%d returned=%u", (int)result, (unsigned)capacity);
                AzTrace(line);
                if (result == 0 || result == 5 /* VK_INCOMPLETE */) {
                    uint32_t limit = capacity < count ? capacity : count;
                    for (uint32_t i = 0; i < limit && i < 64; ++i) {
                        properties[i].extensionName[255] = '\0';
                        snprintf(line, sizeof(line), "V22 EXT [%u] %.255s spec=%u", (unsigned)i,
                                 properties[i].extensionName, (unsigned)properties[i].specVersion);
                        AzTrace(line);
                    }
                    if (limit > 64) AzTrace("V22 EXT remaining entries omitted (log capped at 64)");
                }
                free(properties);
            } else {
                AzTrace("V22 EXT allocation failed; enumeration skipped");
            }
        } else if (result == 0 && count > 256) {
            AzTrace("V22 EXT unusually large extension count; enumeration skipped for safety");
        }
    }
    AzTrace("V22 EXT before dlclose bundled MoltenVK");
    int closeResult = dlclose(handle);
    AzTrace(closeResult == 0 ? "V22 EXT dlclose succeeded" : "V22 EXT dlclose failed");
    AzTrace("V22 EXT no Vulkan instance/device/surface/swapchain created; software renderer unchanged");
}


// V23: create an isolated, short-lived Vulkan instance to enumerate physical devices.
// No surface, device, swapchain, command buffer, or OpenEmu video state is touched.
static void AzV23EnumeratePhysicalDevices(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef int32_t AzVkResult;
    typedef struct {
        uint32_t sType;
        const void *pNext;
        const char *pApplicationName;
        uint32_t applicationVersion;
        const char *pEngineName;
        uint32_t engineVersion;
        uint32_t apiVersion;
    } AzVkApplicationInfo;
    typedef struct {
        uint32_t sType;
        const void *pNext;
        uint32_t flags;
        const AzVkApplicationInfo *pApplicationInfo;
        uint32_t enabledLayerCount;
        const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount;
        const char *const *ppEnabledExtensionNames;
    } AzVkInstanceCreateInfo;
    typedef void *(*AzVkGetInstanceProcAddr)(AzVkInstance, const char *);
    typedef AzVkResult (*AzVkCreateInstance)(const AzVkInstanceCreateInfo *, const void *, AzVkInstance *);
    typedef void (*AzVkDestroyInstance)(AzVkInstance, const void *);
    typedef AzVkResult (*AzVkEnumeratePhysicalDevices)(AzVkInstance, uint32_t *, AzVkPhysicalDevice *);

    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V23 DEVICE before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *reason = dlerror();
        char line[420];
        snprintf(line, sizeof(line), "V23 DEVICE dlopen failed: %.350s", reason ? reason : "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("V23 DEVICE dlopen succeeded");
    dlerror();
    void *rawGetProc = dlsym(handle, "vkGetInstanceProcAddr");
    const char *symbolError = dlerror();
    if (!rawGetProc || symbolError) {
        AzTrace("V23 DEVICE vkGetInstanceProcAddr missing; skipping");
    } else {
        AzVkGetInstanceProcAddr getProc = (AzVkGetInstanceProcAddr)rawGetProc;
        AzVkCreateInstance createInstance = (AzVkCreateInstance)getProc(NULL, "vkCreateInstance");
        if (!createInstance) {
            AzTrace("V23 DEVICE vkCreateInstance unavailable; skipping");
        } else {
            // Vulkan constants: VK_STRUCTURE_TYPE_APPLICATION_INFO=0,
            // VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO=1, VK_API_VERSION_1_0=0x00400000.
            AzVkApplicationInfo appInfo = {0, NULL, "Azahar OpenEmu GPU Probe", 1,
                                            "Azahar OpenEmu", 1, (1u << 22)};
            AzVkInstanceCreateInfo createInfo = {1, NULL, 0, &appInfo, 0, NULL, 0, NULL};
            AzVkInstance instance = NULL;
            AzTrace("V23 DEVICE before vkCreateInstance (Vulkan 1.0, no extensions/layers)");
            AzVkResult result = createInstance(&createInfo, NULL, &instance);
            char line[440];
            snprintf(line, sizeof(line), "V23 DEVICE vkCreateInstance result=%d instance=%s",
                     (int)result, instance ? "non-null" : "null");
            AzTrace(line);
            if (result == 0 && instance) {
                AzVkDestroyInstance destroyInstance =
                    (AzVkDestroyInstance)getProc(instance, "vkDestroyInstance");
                AzVkEnumeratePhysicalDevices enumerate =
                    (AzVkEnumeratePhysicalDevices)getProc(instance, "vkEnumeratePhysicalDevices");
                if (enumerate) {
                    uint32_t count = 0;
                    AzTrace("V23 DEVICE before physical device count query");
                    result = enumerate(instance, &count, NULL);
                    snprintf(line, sizeof(line), "V23 DEVICE count query result=%d count=%u",
                             (int)result, (unsigned)count);
                    AzTrace(line);
                    if (result == 0 && count > 0 && count <= 32) {
                        AzVkPhysicalDevice devices[32] = {NULL};
                        uint32_t capacity = count;
                        AzTrace("V23 DEVICE before physical device handles query");
                        result = enumerate(instance, &capacity, devices);
                        snprintf(line, sizeof(line), "V23 DEVICE handles query result=%d returned=%u",
                                 (int)result, (unsigned)capacity);
                        AzTrace(line);
                        if (result == 0 || result == 5 /* VK_INCOMPLETE */) {
                            uint32_t limit = capacity < count ? capacity : count;
                            for (uint32_t i = 0; i < limit; ++i) {
                                snprintf(line, sizeof(line), "V23 DEVICE [%u] handle=%s",
                                         (unsigned)i, devices[i] ? "non-null" : "null");
                                AzTrace(line);
                            }
                        }
                    } else if (result == 0 && count == 0) {
                        AzTrace("V23 DEVICE zero devices exposed (may require portability enumeration)");
                    } else if (result == 0 && count > 32) {
                        AzTrace("V23 DEVICE count exceeds 32; handles query skipped");
                    }
                } else {
                    AzTrace("V23 DEVICE vkEnumeratePhysicalDevices unavailable");
                }
                if (destroyInstance) {
                    AzTrace("V23 DEVICE before vkDestroyInstance");
                    destroyInstance(instance, NULL);
                    AzTrace("V23 DEVICE vkDestroyInstance completed");
                } else {
                    // Never dlclose code that may still own a live instance.
                    AzTrace("V23 DEVICE vkDestroyInstance missing; leaving loader open for safety");
                    return;
                }
            }
        }
    }
    AzTrace("V23 DEVICE before dlclose bundled MoltenVK");
    int closeResult = dlclose(handle);
    AzTrace(closeResult == 0 ? "V23 DEVICE dlclose succeeded" : "V23 DEVICE dlclose failed");
    AzTrace("V23 DEVICE no logical device/surface/swapchain/GPU submission; software renderer unchanged");
}

// V24: create an isolated, short-lived Vulkan instance to enumerate physical devices.
// No surface, device, swapchain, command buffer, or OpenEmu video state is touched.
static void AzV24QueryPhysicalDeviceProperties(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef int32_t AzVkResult;
    typedef struct {
        uint32_t sType;
        const void *pNext;
        const char *pApplicationName;
        uint32_t applicationVersion;
        const char *pEngineName;
        uint32_t engineVersion;
        uint32_t apiVersion;
    } AzVkApplicationInfo;
    typedef struct {
        uint32_t sType;
        const void *pNext;
        uint32_t flags;
        const AzVkApplicationInfo *pApplicationInfo;
        uint32_t enabledLayerCount;
        const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount;
        const char *const *ppEnabledExtensionNames;
    } AzVkInstanceCreateInfo;
    typedef void *(*AzVkGetInstanceProcAddr)(AzVkInstance, const char *);
    typedef AzVkResult (*AzVkCreateInstance)(const AzVkInstanceCreateInfo *, const void *, AzVkInstance *);
    typedef void (*AzVkDestroyInstance)(AzVkInstance, const void *);
    typedef AzVkResult (*AzVkEnumeratePhysicalDevices)(AzVkInstance, uint32_t *, AzVkPhysicalDevice *);

    // vkGetPhysicalDeviceProperties writes VkPhysicalDeviceProperties, whose tail
    // contains a large VkPhysicalDeviceLimits struct. Reserve generously sized,
    // 8-byte-aligned storage to avoid depending on SDK Vulkan headers.
    typedef void (*AzVkGetPhysicalDeviceProperties)(AzVkPhysicalDevice, void *);
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V24 GPU before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *reason = dlerror();
        char line[420];
        snprintf(line, sizeof(line), "V24 GPU dlopen failed: %.350s", reason ? reason : "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("V24 GPU dlopen succeeded");
    dlerror();
    void *rawGetProc = dlsym(handle, "vkGetInstanceProcAddr");
    const char *symbolError = dlerror();
    if (!rawGetProc || symbolError) {
        AzTrace("V24 GPU vkGetInstanceProcAddr missing; skipping");
    } else {
        AzVkGetInstanceProcAddr getProc = (AzVkGetInstanceProcAddr)rawGetProc;
        AzVkCreateInstance createInstance = (AzVkCreateInstance)getProc(NULL, "vkCreateInstance");
        if (!createInstance) {
            AzTrace("V24 GPU vkCreateInstance unavailable; skipping");
        } else {
            // Vulkan constants: VK_STRUCTURE_TYPE_APPLICATION_INFO=0,
            // VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO=1, VK_API_VERSION_1_0=0x00400000.
            AzVkApplicationInfo appInfo = {0, NULL, "Azahar OpenEmu GPU Probe", 1,
                                            "Azahar OpenEmu", 1, (1u << 22)};
            AzVkInstanceCreateInfo createInfo = {1, NULL, 0, &appInfo, 0, NULL, 0, NULL};
            AzVkInstance instance = NULL;
            AzTrace("V24 GPU before vkCreateInstance (Vulkan 1.0, no extensions/layers)");
            AzVkResult result = createInstance(&createInfo, NULL, &instance);
            char line[440];
            snprintf(line, sizeof(line), "V24 GPU vkCreateInstance result=%d instance=%s",
                     (int)result, instance ? "non-null" : "null");
            AzTrace(line);
            if (result == 0 && instance) {
                AzVkDestroyInstance destroyInstance =
                    (AzVkDestroyInstance)getProc(instance, "vkDestroyInstance");
                AzVkEnumeratePhysicalDevices enumerate =
                    (AzVkEnumeratePhysicalDevices)getProc(instance, "vkEnumeratePhysicalDevices");
                AzVkGetPhysicalDeviceProperties properties =
                    (AzVkGetPhysicalDeviceProperties)getProc(instance, "vkGetPhysicalDeviceProperties");
                if (enumerate) {
                    uint32_t count = 0;
                    AzTrace("V24 GPU before physical device count query");
                    result = enumerate(instance, &count, NULL);
                    snprintf(line, sizeof(line), "V24 GPU count query result=%d count=%u",
                             (int)result, (unsigned)count);
                    AzTrace(line);
                    if (result == 0 && count > 0 && count <= 32) {
                        AzVkPhysicalDevice devices[32] = {NULL};
                        uint32_t capacity = count;
                        AzTrace("V24 GPU before physical device handles query");
                        result = enumerate(instance, &capacity, devices);
                        snprintf(line, sizeof(line), "V24 GPU handles query result=%d returned=%u",
                                 (int)result, (unsigned)capacity);
                        AzTrace(line);
                        if (result == 0 || result == 5 /* VK_INCOMPLETE */) {
                            uint32_t limit = capacity < count ? capacity : count;
                            for (uint32_t i = 0; i < limit; ++i) {
                                snprintf(line, sizeof(line), "V24 GPU [%u] handle=%s",
                                         (unsigned)i, devices[i] ? "non-null" : "null");
                                AzTrace(line);
                                if (devices[i] && properties) {
                                    uint64_t propertyStorage[512] = {0};
                                    AzTrace("V24 GPU before vkGetPhysicalDeviceProperties");
                                    properties(devices[i], propertyStorage);
                                    const unsigned char *bytes = (const unsigned char *)propertyStorage;
                                    uint32_t api = 0, driver = 0, vendor = 0, device = 0, type = 0;
                                    memcpy(&api, bytes + 0, 4);
                                    memcpy(&driver, bytes + 4, 4);
                                    memcpy(&vendor, bytes + 8, 4);
                                    memcpy(&device, bytes + 12, 4);
                                    memcpy(&type, bytes + 16, 4);
                                    char name[257] = {0};
                                    memcpy(name, bytes + 20, 256);
                                    name[256] = '\0';
                                    snprintf(line, sizeof(line),
                                             "V24 GPU [%u] name=%.255s vendor=0x%04x device=0x%04x type=%u",
                                             (unsigned)i, name, (unsigned)vendor,
                                             (unsigned)device, (unsigned)type);
                                    AzTrace(line);
                                    snprintf(line, sizeof(line),
                                             "V24 GPU [%u] api=%u.%u.%u driverRaw=0x%08x",
                                             (unsigned)i, (unsigned)(api >> 22),
                                             (unsigned)((api >> 12) & 0x3ff),
                                             (unsigned)(api & 0xfff), (unsigned)driver);
                                    AzTrace(line);
                                } else if (!properties) {
                                    AzTrace("V24 GPU vkGetPhysicalDeviceProperties unavailable");
                                }
                            }
                        }
                    } else if (result == 0 && count == 0) {
                        AzTrace("V24 GPU zero devices exposed (may require portability enumeration)");
                    } else if (result == 0 && count > 32) {
                        AzTrace("V24 GPU count exceeds 32; handles query skipped");
                    }
                } else {
                    AzTrace("V24 GPU vkEnumeratePhysicalDevices unavailable");
                }
                if (destroyInstance) {
                    AzTrace("V24 GPU before vkDestroyInstance");
                    destroyInstance(instance, NULL);
                    AzTrace("V24 GPU vkDestroyInstance completed");
                } else {
                    // Never dlclose code that may still own a live instance.
                    AzTrace("V24 GPU vkDestroyInstance missing; leaving loader open for safety");
                    return;
                }
            }
        }
    }
    AzTrace("V24 GPU before dlclose bundled MoltenVK");
    int closeResult = dlclose(handle);
    AzTrace(closeResult == 0 ? "V24 GPU dlclose succeeded" : "V24 GPU dlclose failed");
    AzTrace("V24 GPU read-only physical device properties; no logical device/surface/swapchain/GPU submission");
}

// V25: query physical-device queue-family properties in a temporary Vulkan instance.
// No surface, device, swapchain, command buffer, or OpenEmu video state is touched.
static void AzV25QueryQueueFamilies(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef int32_t AzVkResult;
    typedef struct {
        uint32_t sType;
        const void *pNext;
        const char *pApplicationName;
        uint32_t applicationVersion;
        const char *pEngineName;
        uint32_t engineVersion;
        uint32_t apiVersion;
    } AzVkApplicationInfo;
    typedef struct {
        uint32_t sType;
        const void *pNext;
        uint32_t flags;
        const AzVkApplicationInfo *pApplicationInfo;
        uint32_t enabledLayerCount;
        const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount;
        const char *const *ppEnabledExtensionNames;
    } AzVkInstanceCreateInfo;
    typedef void *(*AzVkGetInstanceProcAddr)(AzVkInstance, const char *);
    typedef AzVkResult (*AzVkCreateInstance)(const AzVkInstanceCreateInfo *, const void *, AzVkInstance *);
    typedef void (*AzVkDestroyInstance)(AzVkInstance, const void *);
    typedef AzVkResult (*AzVkEnumeratePhysicalDevices)(AzVkInstance, uint32_t *, AzVkPhysicalDevice *);

    // VkQueueFamilyProperties has four-byte fields only (VkExtent3D = 3 x uint32_t).
    typedef struct {
        uint32_t queueFlags;
        uint32_t queueCount;
        uint32_t timestampValidBits;
        uint32_t minImageTransferGranularity[3];
    } AzVkQueueFamilyProperties;
    typedef void (*AzVkGetPhysicalDeviceQueueFamilyProperties)(
        AzVkPhysicalDevice, uint32_t *, AzVkQueueFamilyProperties *);
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V25 GPU before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *reason = dlerror();
        char line[420];
        snprintf(line, sizeof(line), "V25 GPU dlopen failed: %.350s", reason ? reason : "unknown");
        AzTrace(line);
        return;
    }
    AzTrace("V25 GPU dlopen succeeded");
    dlerror();
    void *rawGetProc = dlsym(handle, "vkGetInstanceProcAddr");
    const char *symbolError = dlerror();
    if (!rawGetProc || symbolError) {
        AzTrace("V25 GPU vkGetInstanceProcAddr missing; skipping");
    } else {
        AzVkGetInstanceProcAddr getProc = (AzVkGetInstanceProcAddr)rawGetProc;
        AzVkCreateInstance createInstance = (AzVkCreateInstance)getProc(NULL, "vkCreateInstance");
        if (!createInstance) {
            AzTrace("V25 GPU vkCreateInstance unavailable; skipping");
        } else {
            // Vulkan constants: VK_STRUCTURE_TYPE_APPLICATION_INFO=0,
            // VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO=1, VK_API_VERSION_1_0=0x00400000.
            AzVkApplicationInfo appInfo = {0, NULL, "Azahar OpenEmu GPU Probe", 1,
                                            "Azahar OpenEmu", 1, (1u << 22)};
            AzVkInstanceCreateInfo createInfo = {1, NULL, 0, &appInfo, 0, NULL, 0, NULL};
            AzVkInstance instance = NULL;
            AzTrace("V25 GPU before vkCreateInstance (Vulkan 1.0, no extensions/layers)");
            AzVkResult result = createInstance(&createInfo, NULL, &instance);
            char line[440];
            snprintf(line, sizeof(line), "V25 GPU vkCreateInstance result=%d instance=%s",
                     (int)result, instance ? "non-null" : "null");
            AzTrace(line);
            if (result == 0 && instance) {
                AzVkDestroyInstance destroyInstance =
                    (AzVkDestroyInstance)getProc(instance, "vkDestroyInstance");
                AzVkEnumeratePhysicalDevices enumerate =
                    (AzVkEnumeratePhysicalDevices)getProc(instance, "vkEnumeratePhysicalDevices");
                AzVkGetPhysicalDeviceQueueFamilyProperties properties =
                    (AzVkGetPhysicalDeviceQueueFamilyProperties)getProc(instance, "vkGetPhysicalDeviceQueueFamilyProperties");
                if (enumerate) {
                    uint32_t count = 0;
                    AzTrace("V25 GPU before physical device count query");
                    result = enumerate(instance, &count, NULL);
                    snprintf(line, sizeof(line), "V25 GPU count query result=%d count=%u",
                             (int)result, (unsigned)count);
                    AzTrace(line);
                    if (result == 0 && count > 0 && count <= 32) {
                        AzVkPhysicalDevice devices[32] = {NULL};
                        uint32_t capacity = count;
                        AzTrace("V25 GPU before physical device handles query");
                        result = enumerate(instance, &capacity, devices);
                        snprintf(line, sizeof(line), "V25 GPU handles query result=%d returned=%u",
                                 (int)result, (unsigned)capacity);
                        AzTrace(line);
                        if (result == 0 || result == 5 /* VK_INCOMPLETE */) {
                            uint32_t limit = capacity < count ? capacity : count;
                            for (uint32_t i = 0; i < limit; ++i) {
                                snprintf(line, sizeof(line), "V25 GPU [%u] handle=%s",
                                         (unsigned)i, devices[i] ? "non-null" : "null");
                                AzTrace(line);
                                if (devices[i] && properties) {
                                    uint32_t queueCount = 0;
                                    AzTrace("V25 GPU before queue-family count query");
                                    properties(devices[i], &queueCount, NULL);
                                    snprintf(line, sizeof(line),
                                             "V25 GPU [%u] queue-family count=%u",
                                             (unsigned)i, (unsigned)queueCount);
                                    AzTrace(line);
                                    if (queueCount > 0 && queueCount <= 32) {
                                        AzVkQueueFamilyProperties queues[32] = {};
                                        uint32_t capacity = queueCount;
                                        AzTrace("V25 GPU before queue-family properties query");
                                        properties(devices[i], &capacity, queues);
                                        snprintf(line, sizeof(line),
                                                 "V25 GPU [%u] queue families returned=%u",
                                                 (unsigned)i, (unsigned)capacity);
                                        AzTrace(line);
                                        uint32_t limit = capacity < 32 ? capacity : 32;
                                        for (uint32_t q = 0; q < limit; ++q) {
                                            const AzVkQueueFamilyProperties *p = &queues[q];
                                            snprintf(line, sizeof(line),
                                                     "V25 GPU [%u] queue[%u] flags=0x%08x graphics=%s compute=%s transfer=%s sparse=%s count=%u timestampBits=%u granularity=%ux%ux%u",
                                                     (unsigned)i, (unsigned)q, (unsigned)p->queueFlags,
                                                     (p->queueFlags & 1u) ? "yes" : "no",
                                                     (p->queueFlags & 2u) ? "yes" : "no",
                                                     (p->queueFlags & 4u) ? "yes" : "no",
                                                     (p->queueFlags & 8u) ? "yes" : "no",
                                                     (unsigned)p->queueCount,
                                                     (unsigned)p->timestampValidBits,
                                                     (unsigned)p->minImageTransferGranularity[0],
                                                     (unsigned)p->minImageTransferGranularity[1],
                                                     (unsigned)p->minImageTransferGranularity[2]);
                                            AzTrace(line);
                                        }
                                    } else if (queueCount > 32) {
                                        AzTrace("V25 GPU queue-family count exceeds 32; properties skipped");
                                    }
                                } else if (!properties) {
                                    AzTrace("V25 GPU vkGetPhysicalDeviceQueueFamilyProperties unavailable");
                                }
                            }
                        }
                    } else if (result == 0 && count == 0) {
                        AzTrace("V25 GPU zero devices exposed (may require portability enumeration)");
                    } else if (result == 0 && count > 32) {
                        AzTrace("V25 GPU count exceeds 32; handles query skipped");
                    }
                } else {
                    AzTrace("V25 GPU vkEnumeratePhysicalDevices unavailable");
                }
                if (destroyInstance) {
                    AzTrace("V25 GPU before vkDestroyInstance");
                    destroyInstance(instance, NULL);
                    AzTrace("V25 GPU vkDestroyInstance completed");
                } else {
                    // Never dlclose code that may still own a live instance.
                    AzTrace("V25 GPU vkDestroyInstance missing; leaving loader open for safety");
                    return;
                }
            }
        }
    }
    AzTrace("V25 GPU before dlclose bundled MoltenVK");
    int closeResult = dlclose(handle);
    AzTrace(closeResult == 0 ? "V25 GPU dlclose succeeded" : "V25 GPU dlclose failed");
    AzTrace("V25 GPU read-only queue-family properties; no logical device/surface/swapchain/GPU submission");
}

// V26: isolated temporary Vulkan logical-device and graphics-queue probe.
// The software video path remains the only active renderer.
static void AzV26CreateTemporaryLogicalDevice(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef void *AzVkDevice;
    typedef void *AzVkQueue;
    typedef int32_t AzVkResult;
    typedef struct {
        uint32_t sType; const void *pNext; const char *pApplicationName;
        uint32_t applicationVersion; const char *pEngineName;
        uint32_t engineVersion; uint32_t apiVersion;
    } AzVkApplicationInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        const AzVkApplicationInfo *pApplicationInfo;
        uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount; const char *const *ppEnabledExtensionNames;
    } AzVkInstanceCreateInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t queueFamilyIndex; uint32_t queueCount; const float *pQueuePriorities;
    } AzVkDeviceQueueCreateInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t queueCreateInfoCount; const AzVkDeviceQueueCreateInfo *pQueueCreateInfos;
        uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount; const char *const *ppEnabledExtensionNames;
        const void *pEnabledFeatures;
    } AzVkDeviceCreateInfo;
    typedef struct {
        uint32_t queueFlags, queueCount, timestampValidBits;
        uint32_t minImageTransferGranularity[3];
    } AzVkQueueFamilyProperties;
    typedef void *(*AzVkGetInstanceProcAddr)(AzVkInstance, const char *);
    typedef void *(*AzVkGetDeviceProcAddr)(AzVkDevice, const char *);
    typedef AzVkResult (*AzVkCreateInstance)(const AzVkInstanceCreateInfo *, const void *, AzVkInstance *);
    typedef void (*AzVkDestroyInstance)(AzVkInstance, const void *);
    typedef AzVkResult (*AzVkEnumeratePhysicalDevices)(AzVkInstance, uint32_t *, AzVkPhysicalDevice *);
    typedef void (*AzVkGetPhysicalDeviceQueueFamilyProperties)(AzVkPhysicalDevice, uint32_t *, AzVkQueueFamilyProperties *);
    typedef AzVkResult (*AzVkCreateDevice)(AzVkPhysicalDevice, const AzVkDeviceCreateInfo *, const void *, AzVkDevice *);
    typedef void (*AzVkDestroyDevice)(AzVkDevice, const void *);
    typedef void (*AzVkGetDeviceQueue)(AzVkDevice, uint32_t, uint32_t, AzVkQueue *);
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V26 DEVICE before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *err = dlerror(); char line[420];
        snprintf(line, sizeof(line), "V26 DEVICE dlopen failed: %.350s", err ? err : "unknown");
        AzTrace(line); return;
    }
    AzTrace("V26 DEVICE dlopen succeeded");
    AzVkGetInstanceProcAddr getProc = (AzVkGetInstanceProcAddr)dlsym(handle, "vkGetInstanceProcAddr");
    if (!getProc) { AzTrace("V26 DEVICE vkGetInstanceProcAddr missing"); goto close_loader; }
    {
        AzVkCreateInstance createInstance = (AzVkCreateInstance)getProc(NULL, "vkCreateInstance");
        if (!createInstance) { AzTrace("V26 DEVICE vkCreateInstance missing"); goto close_loader; }
        AzVkApplicationInfo app = {0, NULL, "Azahar OpenEmu GPU Probe", 1, "Azahar OpenEmu", 1, (1u << 22)};
        AzVkInstanceCreateInfo info = {1, NULL, 0, &app, 0, NULL, 0, NULL};
        AzVkInstance instance = NULL;
        AzTrace("V26 DEVICE before vkCreateInstance");
        AzVkResult result = createInstance(&info, NULL, &instance);
        char line[440];
        snprintf(line, sizeof(line), "V26 DEVICE vkCreateInstance result=%d instance=%s", (int)result, instance ? "non-null" : "null");
        AzTrace(line);
        if (result != 0 || !instance) goto close_loader;
        AzVkDestroyInstance destroyInstance = (AzVkDestroyInstance)getProc(instance, "vkDestroyInstance");
        if (!destroyInstance) { AzTrace("V26 DEVICE vkDestroyInstance unavailable; leaving loader open"); return; }
        AzVkEnumeratePhysicalDevices enumerate = (AzVkEnumeratePhysicalDevices)getProc(instance, "vkEnumeratePhysicalDevices");
        AzVkGetPhysicalDeviceQueueFamilyProperties properties = (AzVkGetPhysicalDeviceQueueFamilyProperties)getProc(instance, "vkGetPhysicalDeviceQueueFamilyProperties");
        AzVkCreateDevice createDevice = (AzVkCreateDevice)getProc(instance, "vkCreateDevice");
        AzVkGetDeviceProcAddr getDeviceProc = (AzVkGetDeviceProcAddr)getProc(instance, "vkGetDeviceProcAddr");
        if (!enumerate || !properties || !createDevice || !getDeviceProc) {
            AzTrace("V26 DEVICE required Vulkan function unavailable; skipping device creation");
        } else {
            uint32_t count = 0;
            result = enumerate(instance, &count, NULL);
            snprintf(line, sizeof(line), "V26 DEVICE physical count result=%d count=%u", (int)result, (unsigned)count);
            AzTrace(line);
            if (result == 0 && count > 0 && count <= 32) {
                AzVkPhysicalDevice devices[32] = {NULL};
                uint32_t capacity = count;
                result = enumerate(instance, &capacity, devices);
                snprintf(line, sizeof(line), "V26 DEVICE physical handles result=%d returned=%u", (int)result, (unsigned)capacity);
                AzTrace(line);
                if ((result == 0 || result == 5) && capacity > 0 && devices[0]) {
                    uint32_t familyCount = 0;
                    properties(devices[0], &familyCount, NULL);
                    snprintf(line, sizeof(line), "V26 DEVICE queue-family count=%u", (unsigned)familyCount);
                    AzTrace(line);
                    if (familyCount > 0 && familyCount <= 32) {
                        AzVkQueueFamilyProperties families[32] = {};
                        uint32_t available = familyCount;
                        properties(devices[0], &available, families);
                        uint32_t graphicsFamily = UINT32_MAX;
                        for (uint32_t q = 0; q < available && q < 32; ++q) {
                            if ((families[q].queueFlags & 1u) && families[q].queueCount > 0) {
                                graphicsFamily = q; break;
                            }
                        }
                        if (graphicsFamily != UINT32_MAX) {
                            snprintf(line, sizeof(line), "V26 DEVICE selected graphics family=%u", (unsigned)graphicsFamily);
                            AzTrace(line);
                            float priority = 1.0f;
                            // Vulkan structure types: DEVICE_QUEUE_CREATE_INFO=2; DEVICE_CREATE_INFO=3.
                            AzVkDeviceQueueCreateInfo queueInfo = {2, NULL, 0, graphicsFamily, 1, &priority};
                            AzVkDeviceCreateInfo deviceInfo = {3, NULL, 0, 1, &queueInfo, 0, NULL, 0, NULL, NULL};
                            AzVkDevice device = NULL;
                            AzTrace("V26 DEVICE before vkCreateDevice (one graphics queue; no extensions)");
                            result = createDevice(devices[0], &deviceInfo, NULL, &device);
                            snprintf(line, sizeof(line), "V26 DEVICE vkCreateDevice result=%d device=%s", (int)result, device ? "non-null" : "null");
                            AzTrace(line);
                            if (result == 0 && device) {
                                AzVkDestroyDevice destroyDevice = (AzVkDestroyDevice)getDeviceProc(device, "vkDestroyDevice");
                                AzVkGetDeviceQueue getQueue = (AzVkGetDeviceQueue)getDeviceProc(device, "vkGetDeviceQueue");
                                if (!destroyDevice) {
                                    AzTrace("V26 DEVICE vkDestroyDevice unavailable; leaving Vulkan resources loaded for safety");
                                    return;
                                }
                                if (getQueue) {
                                    AzVkQueue queue = NULL;
                                    AzTrace("V26 DEVICE before vkGetDeviceQueue");
                                    getQueue(device, graphicsFamily, 0, &queue);
                                    snprintf(line, sizeof(line), "V26 DEVICE vkGetDeviceQueue queue=%s", queue ? "non-null" : "null");
                                    AzTrace(line);
                                } else {
                                    AzTrace("V26 DEVICE vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V26 DEVICE before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V26 DEVICE vkDestroyDevice completed");
                            }
                        } else { AzTrace("V26 DEVICE no graphics-capable queue found"); }
                    } else { AzTrace("V26 DEVICE invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V26 DEVICE before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V26 DEVICE vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V26 DEVICE before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V26 DEVICE dlclose succeeded" : "V26 DEVICE dlclose failed");
    AzTrace("V26 DEVICE isolated probe only; no surface/swapchain/command submission; software renderer unchanged");
}

