    AzTrace("V29 SUBMIT before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V29 SUBMIT dlclose succeeded" : "V29 SUBMIT dlclose failed");
    AzTrace("V29 SUBMIT isolated empty command-buffer submission only; no surface/swapchain; software renderer unchanged");
