                                                                    snprintf(line, sizeof(line), "V30 FILL vkAllocateMemory result=%d", (int)ar);
                                                                    AzTrace(line);
                                                                    if (ar == 0 && testMemory) {
                                                                        AzVkResult bindResult = bindMemory(device, testBuffer, testMemory, 0);
                                                                        snprintf(line, sizeof(line), "V30 FILL vkBindBufferMemory result=%d", (int)bindResult);
                                                                        AzTrace(line);
                                                                        if (bindResult == 0) {
                                                                            AzVkResult mapResult = mapMemory(device, testMemory, 0, testBytes, 0, &mapped);
                                                                            snprintf(line, sizeof(line), "V30 FILL vkMapMemory result=%d mapped=%s", (int)mapResult, mapped ? "non-null" : "null");
                                                                            AzTrace(line);
                                                                            if (mapResult == 0 && mapped) {
                                                                                memset(mapped, 0, (size_t)testBytes);
                                                                                testReady = true;
                                                                            }
                                                                        }
                                                                    }
                                                                } else {
                                                                    AzTrace("V30 FILL no compatible HOST_VISIBLE|HOST_COHERENT memory type; skipping GPU write");
                                                                }
                                                            }
                                                        } else {
                                                            AzTrace("V30 FILL buffer/memory/fill Vulkan entrypoint missing; skipping GPU write");
                                                        }
                                                        if (testReady) {
                                                        AzVkCommandBufferBeginInfo beginInfo = {42, NULL, 0, NULL};
                                                        AzTrace("V30 FILL before vkBeginCommandBuffer");
                                                        AzVkResult beginResult = beginBuffer(buffer, &beginInfo);
                                                        snprintf(line, sizeof(line), "V30 FILL vkBeginCommandBuffer result=%d", (int)beginResult);
                                                        AzTrace(line);
                                                        if (beginResult == 0) {
                                                            AzTrace("V30 FILL before vkCmdFillBuffer (64 bytes, pattern=0xA1B2C3D4)");
                                                            cmdFill(buffer, testBuffer, 0, testBytes, pattern);
                                                            AzTrace("V30 FILL vkCmdFillBuffer recorded");
                                                            AzTrace("V30 FILL before vkEndCommandBuffer");
                                                            AzVkResult endResult = endBuffer(buffer);
                                                            snprintf(line, sizeof(line), "V30 FILL vkEndCommandBuffer result=%d", (int)endResult);
                                                            AzTrace(line);
                                                            if (endResult == 0) {
                                                                AzVkQueueSubmit submit = (AzVkQueueSubmit)getDeviceProc(device, "vkQueueSubmit");
                                                                AzVkQueueWaitIdle waitIdle = (AzVkQueueWaitIdle)getDeviceProc(device, "vkQueueWaitIdle");
                                                                if (submit && waitIdle) {
                                                                    AzVkSubmitInfo submitInfo = {4, NULL, 0, NULL, NULL, 1, &buffer, 0, NULL};
                                                                    AzTrace("V30 FILL before vkQueueSubmit (one empty command buffer)");
                                                                    AzVkResult submitResult = submit(queue, 1, &submitInfo, NULL);
                                                                    snprintf(line, sizeof(line), "V30 FILL vkQueueSubmit result=%d", (int)submitResult);
                                                                    AzTrace(line);
                                                                    AzTrace("V30 FILL before vkQueueWaitIdle");
                                                                    AzVkResult waitResult = waitIdle(queue);
                                                                    snprintf(line, sizeof(line), "V30 FILL vkQueueWaitIdle result=%d", (int)waitResult);
                                                                    AzTrace(line);
                                                                    if (waitResult != 0) {
                                                                        AzTrace("V30 FILL queue not confirmed idle; retaining Vulkan objects and loader for safety");
                                                                        return;
                                                                    }
                                                                    if (submitResult == 0 && waitResult == 0 && mapped) {
                                                                        const uint32_t *words = (const uint32_t *)mapped;
                                                                        uint32_t good = 0;
                                                                        for (uint32_t wi = 0; wi < 16; ++wi) {
                                                                            if (words[wi] == pattern) ++good;
                                                                        }
                                                                        snprintf(line, sizeof(line), "V30 FILL GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)pattern);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 ? "V30 FILL GPU BUFFER WRITE VERIFIED SUCCESS" : "V30 FILL GPU BUFFER WRITE VERIFICATION FAILED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V30 FILL queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (mapped && unmapMemory && testMemory) {
                                                            unmapMemory(device, testMemory);
                                                            AzTrace("V30 FILL vkUnmapMemory completed");
                                                        }
                                                        if (testBuffer && destroyBuffer) {
                                                            destroyBuffer(device, testBuffer, NULL);
                                                            AzTrace("V30 FILL vkDestroyBuffer completed");
                                                        }
                                                        if (testMemory && freeMemory) {
                                                            freeMemory(device, testMemory, NULL);
                                                            AzTrace("V30 FILL vkFreeMemory completed");
                                                        }
                                                    } else {
                                                        AzTrace("V30 FILL command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V30 FILL before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V30 FILL vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V30 FILL before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V30 FILL vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V30 FILL command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V30 FILL vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V30 FILL before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V30 FILL vkDestroyDevice completed");
                            }
                        } else { AzTrace("V30 FILL no graphics-capable queue found"); }
                    } else { AzTrace("V30 FILL invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V30 FILL before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V30 FILL vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V30 FILL before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V30 FILL dlclose succeeded" : "V30 FILL dlclose failed");
    AzTrace("V30 FILL isolated GPU buffer fill/readback only; no surface/swapchain; software renderer unchanged");
}


