                                                            AzTrace("V31 COPY recording GPU fill(source), barrier, copy(source->destination), host barrier");
                                                            cmdFill(buffer, testBuffer, 0, testBytes, pattern);
                                                            // TRANSFER_WRITE=0x1000 -> TRANSFER_READ=0x800; TRANSFER stage=0x1000.
                                                            AzVkMemoryBarrier fillBarrier = {46, NULL, 0x1000u, 0x800u};
                                                            cmdBarrier(buffer, 0x1000u, 0x1000u, 0, 1, &fillBarrier, 0, NULL, 0, NULL);
                                                            AzVkBufferCopy copyRegion = {0, 0, testBytes};
                                                            cmdCopy(buffer, testBuffer, dstBuffer, 1, &copyRegion);
                                                            // TRANSFER_WRITE -> HOST_READ=0x2000, HOST stage=0x4000.
                                                            AzVkMemoryBarrier hostBarrier = {46, NULL, 0x1000u, 0x2000u};
                                                            cmdBarrier(buffer, 0x1000u, 0x4000u, 0, 1, &hostBarrier, 0, NULL, 0, NULL);
                                                            AzTrace("V31 COPY vkCmdCopyBuffer recorded (64 bytes)");
                                                            AzTrace("V31 COPY before vkEndCommandBuffer");
                                                            AzVkResult endResult = endBuffer(buffer);
                                                            snprintf(line, sizeof(line), "V31 COPY vkEndCommandBuffer result=%d", (int)endResult);
                                                            AzTrace(line);
                                                            if (endResult == 0) {
                                                                AzVkQueueSubmit submit = (AzVkQueueSubmit)getDeviceProc(device, "vkQueueSubmit");
                                                                AzVkQueueWaitIdle waitIdle = (AzVkQueueWaitIdle)getDeviceProc(device, "vkQueueWaitIdle");
                                                                if (submit && waitIdle) {
                                                                    AzVkSubmitInfo submitInfo = {4, NULL, 0, NULL, NULL, 1, &buffer, 0, NULL};
                                                                    AzTrace("V31 COPY before vkQueueSubmit (GPU fill and buffer copy)");
                                                                    AzVkResult submitResult = submit(queue, 1, &submitInfo, NULL);
                                                                    snprintf(line, sizeof(line), "V31 COPY vkQueueSubmit result=%d", (int)submitResult);
                                                                    AzTrace(line);
                                                                    AzTrace("V31 COPY before vkQueueWaitIdle");
                                                                    AzVkResult waitResult = waitIdle(queue);
                                                                    snprintf(line, sizeof(line), "V31 COPY vkQueueWaitIdle result=%d", (int)waitResult);
                                                                    AzTrace(line);
                                                                    if (waitResult != 0) {
                                                                        AzTrace("V31 COPY queue not confirmed idle; retaining Vulkan objects and loader for safety");
                                                                        return;
                                                                    }
                                                                    if (submitResult == 0 && waitResult == 0 && mapped) {
                                                                        const uint32_t *words = (const uint32_t *)mapped;
                                                                        uint32_t good = 0;
                                                                        for (uint32_t wi = 0; wi < 16; ++wi) {
                                                                            if (words[wi] == pattern) ++good;
                                                                        }
                                                                        snprintf(line, sizeof(line), "V31 COPY GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)pattern);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 ? "V31 COPY GPU-TO-GPU BUFFER COPY VERIFIED SUCCESS" : "V31 COPY GPU-TO-GPU BUFFER COPY VERIFICATION FAILED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V31 COPY queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (mapped && unmapMemory && testMemory) {
                                                            unmapMemory(device, testMemory);
                                                            AzTrace("V31 COPY vkUnmapMemory completed");
                                                        }
                                                        if (dstBuffer && destroyBuffer) {
                                                            destroyBuffer(device, dstBuffer, NULL);
                                                            AzTrace("V31 COPY destination vkDestroyBuffer completed");
                                                        }
                                                        if (dstMemory && freeMemory) {
                                                            freeMemory(device, dstMemory, NULL);
                                                            AzTrace("V31 COPY destination vkFreeMemory completed");
                                                        }
                                                        if (testBuffer && destroyBuffer) {
                                                            destroyBuffer(device, testBuffer, NULL);
                                                            AzTrace("V31 COPY vkDestroyBuffer completed");
                                                        }
                                                        if (testMemory && freeMemory) {
                                                            freeMemory(device, testMemory, NULL);
                                                            AzTrace("V31 COPY vkFreeMemory completed");
                                                        }
                                                    } else {
                                                        AzTrace("V31 COPY command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V31 COPY before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V31 COPY vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V31 COPY before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V31 COPY vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V31 COPY command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V31 COPY vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V31 COPY before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V31 COPY vkDestroyDevice completed");
                            }
                        } else { AzTrace("V31 COPY no graphics-capable queue found"); }
                    } else { AzTrace("V31 COPY invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V31 COPY before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V31 COPY vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V31 COPY before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V31 COPY dlclose succeeded" : "V31 COPY dlclose failed");
    AzTrace("V31 COPY isolated GPU-to-GPU buffer copy/readback only; no surface/swapchain; software renderer unchanged");
}


static void AzV32ImageClearReadback(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef void *AzVkDevice;
    typedef void *AzVkQueue;
    typedef int32_t AzVkResult;
    typedef struct {
        uint32_t sType; const void *pNext; const char *pApplicationName;
        uint32_t applicationVersion; const char *pEngineName;
        uint32_t engineVersion; uint32_t apiVersion;
    } AzVkApplicationInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        const AzVkApplicationInfo *pApplicationInfo;
        uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
