    typedef struct { float float32[4]; } AzVkClearColorValue;
    typedef struct { uint32_t sType; const void *pNext; uint32_t srcAccessMask, dstAccessMask; } AzVkMemoryBarrier;
    typedef AzVkResult (*AzVkCreateImage)(AzVkDevice, const AzVkImageCreateInfo *, const void *, AzVkImage *);
    typedef void (*AzVkDestroyImage)(AzVkDevice, AzVkImage, const void *);
    typedef void (*AzVkGetImageMemoryRequirements)(AzVkDevice, AzVkImage, AzVkMemoryRequirements *);
    typedef AzVkResult (*AzVkBindImageMemory)(AzVkDevice, AzVkImage, AzVkDeviceMemory, AzVkDeviceSize);
    typedef void (*AzVkCmdClearColorImage)(AzVkCommandBuffer, AzVkImage, uint32_t, const AzVkClearColorValue *, uint32_t, const AzVkImageSubresourceRange *);
    typedef void (*AzVkCmdCopyImageToBuffer)(AzVkCommandBuffer, AzVkImage, uint32_t, AzVkBuffer, uint32_t, const AzVkBufferImageCopy *);
    typedef void (*AzVkCmdPipelineBarrier)(AzVkCommandBuffer, uint32_t, uint32_t, uint32_t, uint32_t, const AzVkMemoryBarrier *, uint32_t, const void *, uint32_t, const AzVkImageMemoryBarrier *);
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];
    AzTrace("V32 IMAGE before dlopen bundled MoltenVK");
    dlerror();
    void *handle = dlopen(path.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        const char *err = dlerror(); char line[420];
        snprintf(line, sizeof(line), "V32 IMAGE dlopen failed: %.350s", err ? err : "unknown");
        AzTrace(line); return;
    }
    AzTrace("V32 IMAGE dlopen succeeded");
    AzVkGetInstanceProcAddr getProc = (AzVkGetInstanceProcAddr)dlsym(handle, "vkGetInstanceProcAddr");
    if (!getProc) { AzTrace("V32 IMAGE vkGetInstanceProcAddr missing"); goto close_loader; }
    {
        AzVkCreateInstance createInstance = (AzVkCreateInstance)getProc(NULL, "vkCreateInstance");
        if (!createInstance) { AzTrace("V32 IMAGE vkCreateInstance missing"); goto close_loader; }
        AzVkApplicationInfo app = {0, NULL, "Azahar OpenEmu GPU Probe", 1, "Azahar OpenEmu", 1, (1u << 22)};
        AzVkInstanceCreateInfo info = {1, NULL, 0, &app, 0, NULL, 0, NULL};
        AzVkInstance instance = NULL;
        AzTrace("V32 IMAGE before vkCreateInstance");
        AzVkResult result = createInstance(&info, NULL, &instance);
        char line[440];
        snprintf(line, sizeof(line), "V32 IMAGE vkCreateInstance result=%d instance=%s", (int)result, instance ? "non-null" : "null");
        AzTrace(line);
        if (result != 0 || !instance) goto close_loader;
        AzVkDestroyInstance destroyInstance = (AzVkDestroyInstance)getProc(instance, "vkDestroyInstance");
        if (!destroyInstance) { AzTrace("V32 IMAGE vkDestroyInstance unavailable; leaving loader open"); return; }
