        AzVkGetPhysicalDeviceQueueFamilyProperties properties = (AzVkGetPhysicalDeviceQueueFamilyProperties)getProc(instance, "vkGetPhysicalDeviceQueueFamilyProperties");
        AzVkCreateDevice createDevice = (AzVkCreateDevice)getProc(instance, "vkCreateDevice");
        AzVkGetDeviceProcAddr getDeviceProc = (AzVkGetDeviceProcAddr)getProc(instance, "vkGetDeviceProcAddr");
        AzVkGetPhysicalDeviceMemoryProperties getMemoryProps = (AzVkGetPhysicalDeviceMemoryProperties)getProc(instance, "vkGetPhysicalDeviceMemoryProperties");
        if (!enumerate || !properties || !createDevice || !getDeviceProc) {
            AzTrace("V32 IMAGE required Vulkan function unavailable; skipping device creation");
        } else {
            uint32_t count = 0;
            result = enumerate(instance, &count, NULL);
            snprintf(line, sizeof(line), "V32 IMAGE physical count result=%d count=%u", (int)result, (unsigned)count);
            AzTrace(line);
            if (result == 0 && count > 0 && count <= 32) {
                AzVkPhysicalDevice devices[32] = {NULL};
                uint32_t capacity = count;
                result = enumerate(instance, &capacity, devices);
                snprintf(line, sizeof(line), "V32 IMAGE physical handles result=%d returned=%u", (int)result, (unsigned)capacity);
                AzTrace(line);
                if ((result == 0 || result == 5) && capacity > 0 && devices[0]) {
                    uint32_t familyCount = 0;
                    properties(devices[0], &familyCount, NULL);
                    snprintf(line, sizeof(line), "V32 IMAGE queue-family count=%u", (unsigned)familyCount);
                    AzTrace(line);
                    if (familyCount > 0 && familyCount <= 32) {
                        AzVkQueueFamilyProperties families[32] = {};
                        uint32_t available = familyCount;
                        properties(devices[0], &available, families);
                        uint32_t graphicsFamily = UINT32_MAX;
                        for (uint32_t q = 0; q < available && q < 32; ++q) {
                            if ((families[q].queueFlags & 1u) && families[q].queueCount > 0) {
                                graphicsFamily = q; break;
                            }
                        }
                        if (graphicsFamily != UINT32_MAX) {
                            snprintf(line, sizeof(line), "V32 IMAGE selected graphics family=%u", (unsigned)graphicsFamily);
                            AzTrace(line);
                            float priority = 1.0f;
                            // Vulkan structure types: DEVICE_QUEUE_CREATE_INFO=2; DEVICE_CREATE_INFO=3.
                            AzVkDeviceQueueCreateInfo queueInfo = {2, NULL, 0, graphicsFamily, 1, &priority};
                            AzVkDeviceCreateInfo deviceInfo = {3, NULL, 0, 1, &queueInfo, 0, NULL, 0, NULL, NULL};
                            AzVkDevice device = NULL;
                            AzTrace("V32 IMAGE before vkCreateDevice (one graphics queue; no extensions)");
                            result = createDevice(devices[0], &deviceInfo, NULL, &device);
                            snprintf(line, sizeof(line), "V32 IMAGE vkCreateDevice result=%d device=%s", (int)result, device ? "non-null" : "null");
                            AzTrace(line);
                            if (result == 0 && device) {
                                AzVkDestroyDevice destroyDevice = (AzVkDestroyDevice)getDeviceProc(device, "vkDestroyDevice");
                                AzVkGetDeviceQueue getQueue = (AzVkGetDeviceQueue)getDeviceProc(device, "vkGetDeviceQueue");
                                if (!destroyDevice) {
                                    AzTrace("V32 IMAGE vkDestroyDevice unavailable; leaving Vulkan resources loaded for safety");
                                    return;
                                }
                                if (getQueue) {
                                    AzVkQueue queue = NULL;
                                    AzTrace("V32 IMAGE before vkGetDeviceQueue");
                                    getQueue(device, graphicsFamily, 0, &queue);
                                    snprintf(line, sizeof(line), "V32 IMAGE vkGetDeviceQueue queue=%s", queue ? "non-null" : "null");
                                    AzTrace(line);
                                    if (queue) {
                                        AzVkCreateCommandPool createPool = (AzVkCreateCommandPool)getDeviceProc(device, "vkCreateCommandPool");
                                        AzVkDestroyCommandPool destroyPool = (AzVkDestroyCommandPool)getDeviceProc(device, "vkDestroyCommandPool");
