    } AzVkPhysicalDeviceMemoryProperties;
    typedef struct { uint32_t sType; const void *pNext; AzVkDeviceSize allocationSize;
        uint32_t memoryTypeIndex;
    } AzVkMemoryAllocateInfo;
    typedef AzVkResult (*AzVkCreateBuffer)(AzVkDevice, const AzVkBufferCreateInfo *, const void *, AzVkBuffer *);
    typedef void (*AzVkDestroyBuffer)(AzVkDevice, AzVkBuffer, const void *);
    typedef void (*AzVkGetBufferMemoryRequirements)(AzVkDevice, AzVkBuffer, AzVkMemoryRequirements *);
    typedef void (*AzVkGetPhysicalDeviceMemoryProperties)(AzVkPhysicalDevice, AzVkPhysicalDeviceMemoryProperties *);
    typedef AzVkResult (*AzVkAllocateMemory)(AzVkDevice, const AzVkMemoryAllocateInfo *, const void *, AzVkDeviceMemory *);
    typedef void (*AzVkFreeMemory)(AzVkDevice, AzVkDeviceMemory, const void *);
    typedef AzVkResult (*AzVkBindBufferMemory)(AzVkDevice, AzVkBuffer, AzVkDeviceMemory, AzVkDeviceSize);
    typedef AzVkResult (*AzVkMapMemory)(AzVkDevice, AzVkDeviceMemory, AzVkDeviceSize, AzVkDeviceSize, uint32_t, void **);
    typedef void (*AzVkUnmapMemory)(AzVkDevice, AzVkDeviceMemory);
    // Vulkan 1.0 image structures and function signatures (no Vulkan SDK required).
    typedef void *AzVkImage;
    typedef struct { uint32_t width, height, depth; } AzVkExtent3D;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t imageType, format; AzVkExtent3D extent; uint32_t mipLevels, arrayLayers;
