    } AzVkImageMemoryBarrier;
    typedef struct { float float32[4]; } AzVkClearColorValue;
    typedef struct { uint32_t sType; const void *pNext; uint32_t srcAccessMask, dstAccessMask; } AzVkMemoryBarrier;
    typedef AzVkResult (*AzVkCreateImage)(AzVkDevice, const AzVkImageCreateInfo *, const void *, AzVkImage *);
    typedef void (*AzVkDestroyImage)(AzVkDevice, AzVkImage, const void *);
    typedef void (*AzVkGetImageMemoryRequirements)(AzVkDevice, AzVkImage, AzVkMemoryRequirements *);
    typedef AzVkResult (*AzVkBindImageMemory)(AzVkDevice, AzVkImage, AzVkDeviceMemory, AzVkDeviceSize);
    typedef void (*AzVkCmdClearColorImage)(AzVkCommandBuffer, AzVkImage, uint32_t, const AzVkClearColorValue *, uint32_t, const AzVkImageSubresourceRange *);
    typedef void (*AzVkCmdCopyImageToBuffer)(AzVkCommandBuffer, AzVkImage, uint32_t, AzVkBuffer, uint32_t, const AzVkBufferImageCopy *);
    typedef void (*AzVkCmdPipelineBarrier)(AzVkCommandBuffer, uint32_t, uint32_t, uint32_t, uint32_t, const AzVkMemoryBarrier *, uint32_t, const void *, uint32_t, const AzVkImageMemoryBarrier *);
    // Vulkan 1.0 render pass, image view, and framebuffer ABI.
    typedef void *AzVkImageView;
    typedef void *AzVkRenderPass;
    typedef void *AzVkFramebuffer;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        AzVkImage image; uint32_t viewType, format;
        uint32_t components[4]; AzVkImageSubresourceRange subresourceRange;
    } AzVkImageViewCreateInfo;
    typedef struct { uint32_t flags, format, samples, loadOp, storeOp, stencilLoadOp, stencilStoreOp, initialLayout, finalLayout; } AzVkAttachmentDescription;
    typedef struct { uint32_t attachment, layout; } AzVkAttachmentReference;
    typedef struct { uint32_t flags, pipelineBindPoint, inputAttachmentCount;
        const AzVkAttachmentReference *pInputAttachments;
        uint32_t colorAttachmentCount; const AzVkAttachmentReference *pColorAttachments;
        const AzVkAttachmentReference *pResolveAttachments;
        const AzVkAttachmentReference *pDepthStencilAttachment;
        uint32_t preserveAttachmentCount; const uint32_t *pPreserveAttachments;
    } AzVkSubpassDescription;
    typedef struct { uint32_t srcSubpass, dstSubpass, srcStageMask, dstStageMask, srcAccessMask, dstAccessMask, dependencyFlags; } AzVkSubpassDependency;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t attachmentCount; const AzVkAttachmentDescription *pAttachments;
        uint32_t subpassCount; const AzVkSubpassDescription *pSubpasses;
        uint32_t dependencyCount; const AzVkSubpassDependency *pDependencies;
