static void AzV35PipelinePreparation(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef void *AzVkDevice;
    typedef void *AzVkQueue;
    typedef int32_t AzVkResult;
    typedef struct {
        uint32_t sType; const void *pNext; const char *pApplicationName;
        uint32_t applicationVersion; const char *pEngineName;
        uint32_t engineVersion; uint32_t apiVersion;
    } AzVkApplicationInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        const AzVkApplicationInfo *pApplicationInfo;
        uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount; const char *const *ppEnabledExtensionNames;
    } AzVkInstanceCreateInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t queueFamilyIndex; uint32_t queueCount; const float *pQueuePriorities;
    } AzVkDeviceQueueCreateInfo;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t queueCreateInfoCount; const AzVkDeviceQueueCreateInfo *pQueueCreateInfos;
        uint32_t enabledLayerCount; const char *const *ppEnabledLayerNames;
        uint32_t enabledExtensionCount; const char *const *ppEnabledExtensionNames;
        const void *pEnabledFeatures;
    } AzVkDeviceCreateInfo;
    typedef struct {
        uint32_t queueFlags, queueCount, timestampValidBits;
        uint32_t minImageTransferGranularity[3];
    } AzVkQueueFamilyProperties;
    typedef void *(*AzVkGetInstanceProcAddr)(AzVkInstance, const char *);
    typedef void *(*AzVkGetDeviceProcAddr)(AzVkDevice, const char *);
    typedef AzVkResult (*AzVkCreateInstance)(const AzVkInstanceCreateInfo *, const void *, AzVkInstance *);
    typedef void (*AzVkDestroyInstance)(AzVkInstance, const void *);
    typedef AzVkResult (*AzVkEnumeratePhysicalDevices)(AzVkInstance, uint32_t *, AzVkPhysicalDevice *);
    typedef void (*AzVkGetPhysicalDeviceQueueFamilyProperties)(AzVkPhysicalDevice, uint32_t *, AzVkQueueFamilyProperties *);
    typedef AzVkResult (*AzVkCreateDevice)(AzVkPhysicalDevice, const AzVkDeviceCreateInfo *, const void *, AzVkDevice *);
    typedef void (*AzVkDestroyDevice)(AzVkDevice, const void *);
    typedef void (*AzVkGetDeviceQueue)(AzVkDevice, uint32_t, uint32_t, AzVkQueue *);
    typedef void *AzVkCommandPool;
    typedef void *AzVkCommandBuffer;
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags; uint32_t queueFamilyIndex;
    } AzVkCommandPoolCreateInfo;
    typedef struct {
        uint32_t sType; const void *pNext; AzVkCommandPool commandPool;
        uint32_t level; uint32_t commandBufferCount;
    } AzVkCommandBufferAllocateInfo;
    typedef AzVkResult (*AzVkCreateCommandPool)(AzVkDevice, const AzVkCommandPoolCreateInfo *, const void *, AzVkCommandPool *);
    typedef void (*AzVkDestroyCommandPool)(AzVkDevice, AzVkCommandPool, const void *);
    typedef AzVkResult (*AzVkAllocateCommandBuffers)(AzVkDevice, const AzVkCommandBufferAllocateInfo *, AzVkCommandBuffer *);
    typedef void (*AzVkFreeCommandBuffers)(AzVkDevice, AzVkCommandPool, uint32_t, const AzVkCommandBuffer *);
    // Vulkan sType COMMAND_BUFFER_BEGIN_INFO=42; empty primary recording, no inheritance.
    typedef struct {
        uint32_t sType; const void *pNext; uint32_t flags;
        const void *pInheritanceInfo;
    } AzVkCommandBufferBeginInfo;
    typedef AzVkResult (*AzVkBeginCommandBuffer)(AzVkCommandBuffer, const AzVkCommandBufferBeginInfo *);
    typedef AzVkResult (*AzVkEndCommandBuffer)(AzVkCommandBuffer);
    // VkSubmitInfo (Vulkan 1.0); VK_STRUCTURE_TYPE_SUBMIT_INFO = 4.
    typedef struct {
        uint32_t sType; const void *pNext;
        uint32_t waitSemaphoreCount; const void *pWaitSemaphores;
        const uint32_t *pWaitDstStageMask;
        uint32_t commandBufferCount; const AzVkCommandBuffer *pCommandBuffers;
        uint32_t signalSemaphoreCount; const void *pSignalSemaphores;
    } AzVkSubmitInfo;
    typedef AzVkResult (*AzVkQueueSubmit)(AzVkQueue, uint32_t, const AzVkSubmitInfo *, void *);
    typedef AzVkResult (*AzVkQueueWaitIdle)(AzVkQueue);
    // Vulkan 1.0 buffer and host-visible memory ABI; no Vulkan SDK dependency.
    typedef uint64_t AzVkDeviceSize;
    typedef void *AzVkBuffer;
    typedef void *AzVkDeviceMemory;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        AzVkDeviceSize size; uint32_t usage; uint32_t sharingMode;
        uint32_t queueFamilyIndexCount; const uint32_t *pQueueFamilyIndices;
    } AzVkBufferCreateInfo;
    typedef struct { AzVkDeviceSize size; AzVkDeviceSize alignment; uint32_t memoryTypeBits; } AzVkMemoryRequirements;
    typedef struct { uint32_t propertyFlags; uint32_t heapIndex; } AzVkMemoryType;
    typedef struct { AzVkDeviceSize size; uint32_t flags; } AzVkMemoryHeap;
    typedef struct { uint32_t memoryTypeCount; AzVkMemoryType memoryTypes[32];
        uint32_t memoryHeapCount; AzVkMemoryHeap memoryHeaps[16];
    } AzVkPhysicalDeviceMemoryProperties;
    typedef struct { uint32_t sType; const void *pNext; AzVkDeviceSize allocationSize;
        uint32_t memoryTypeIndex;
    } AzVkMemoryAllocateInfo;
    typedef AzVkResult (*AzVkCreateBuffer)(AzVkDevice, const AzVkBufferCreateInfo *, const void *, AzVkBuffer *);
    typedef void (*AzVkDestroyBuffer)(AzVkDevice, AzVkBuffer, const void *);
    typedef void (*AzVkGetBufferMemoryRequirements)(AzVkDevice, AzVkBuffer, AzVkMemoryRequirements *);
