                                                                AzVkQueueSubmit submit = (AzVkQueueSubmit)getDeviceProc(device, "vkQueueSubmit");
                                                                AzVkQueueWaitIdle waitIdle = (AzVkQueueWaitIdle)getDeviceProc(device, "vkQueueWaitIdle");
                                                                if (submit && waitIdle) {
                                                                    AzVkSubmitInfo submitInfo = {4, NULL, 0, NULL, NULL, 1, &buffer, 0, NULL};
                                                                    AzTrace("V35 PIPELINE before vkQueueSubmit (GPU image clear and image-to-buffer copy)");
                                                                    AzVkResult submitResult = submit(queue, 1, &submitInfo, NULL);
                                                                    snprintf(line, sizeof(line), "V35 PIPELINE vkQueueSubmit result=%d", (int)submitResult);
                                                                    AzTrace(line);
                                                                    AzTrace("V35 PIPELINE before vkQueueWaitIdle");
                                                                    AzVkResult waitResult = waitIdle(queue);
                                                                    snprintf(line, sizeof(line), "V35 PIPELINE vkQueueWaitIdle result=%d", (int)waitResult);
                                                                    AzTrace(line);
                                                                    if (waitResult != 0) {
                                                                        AzTrace("V35 PIPELINE queue not confirmed idle; retaining Vulkan objects and loader for safety");
                                                                        return;
                                                                    }
                                                                    if (submitResult == 0 && waitResult == 0 && mapped) {
                                                                        const uint32_t *words = (const uint32_t *)mapped;
                                                                        uint32_t good = 0;
                                                                        for (uint32_t wi = 0; wi < 16; ++wi) {
                                                                            if (words[wi] == pattern) ++good;
                                                                        }
                                                                        snprintf(line, sizeof(line), "V35 PIPELINE GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)pattern);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 ? "V35 PIPELINE RENDER TARGET AND PIPELINE LAYOUT VERIFIED SUCCESS" : "V35 PIPELINE RENDER PASS FRAMEBUFFER VERIFICATION FAILED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V35 PIPELINE queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (vertexModule && destroyShaderModule) destroyShaderModule(device, vertexModule, NULL);
                                                        if (fragmentModule && destroyShaderModule) destroyShaderModule(device, fragmentModule, NULL);
                                                        if (pipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device, pipelineLayout, NULL); AzTrace("V35 PIPELINE vkDestroyPipelineLayout completed"); }
                                                        if (framebuffer && destroyFramebuffer) { destroyFramebuffer(device, framebuffer, NULL); AzTrace("V35 PIPELINE vkDestroyFramebuffer completed"); }
                                                        if (pass && destroyPass) { destroyPass(device, pass, NULL); AzTrace("V35 PIPELINE vkDestroyRenderPass completed"); }
                                                        if (view && destroyView) { destroyView(device, view, NULL); AzTrace("V35 PIPELINE vkDestroyImageView completed"); }
                                                        if (mapped && unmapMemory && dstMemory) {
                                                            unmapMemory(device, dstMemory); AzTrace("V35 PIPELINE vkUnmapMemory completed");
                                                        }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V35 PIPELINE vkDestroyBuffer completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V35 PIPELINE vkDestroyImage completed"); }
                                                        if (dstMemory && freeMemory) { freeMemory(device, dstMemory, NULL); AzTrace("V35 PIPELINE readback vkFreeMemory completed"); }
                                                        if (imageMemory && freeMemory) { freeMemory(device, imageMemory, NULL); AzTrace("V35 PIPELINE image vkFreeMemory completed"); }
                                                    } else {
                                                        AzTrace("V35 PIPELINE command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V35 PIPELINE before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V35 PIPELINE vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V35 PIPELINE before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V35 PIPELINE vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V35 PIPELINE command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V35 PIPELINE vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V35 PIPELINE before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V35 PIPELINE vkDestroyDevice completed");
                            }
                        } else { AzTrace("V35 PIPELINE no graphics-capable queue found"); }
                    } else { AzTrace("V35 PIPELINE invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V35 PIPELINE before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V35 PIPELINE vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V35 PIPELINE before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V35 PIPELINE dlclose succeeded" : "V35 PIPELINE dlclose failed");
    AzTrace("V35 PIPELINE isolated render target and pipeline-layout setup only; no surface/swapchain; software renderer unchanged");
}


