        AzTrace("V43 GRADIENT before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V43 GRADIENT vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V43 GRADIENT before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V43 GRADIENT dlclose succeeded" : "V43 GRADIENT dlclose failed");
    AzTrace("V43 GRADIENT isolated offscreen edge-coverage verification only; no surface/swapchain; software renderer unchanged");
