                                                                        uint32_t good = 0;
                                                                        for (uint32_t wi = 0; wi < 16; ++wi) {
                                                                            if (words[wi] == pattern) ++good;
                                                                        }
                                                                        snprintf(line, sizeof(line), "V36 SHADER GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)pattern);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 ? "V36 SHADER RENDER TARGET AND PIPELINE LAYOUT VERIFIED SUCCESS" : "V36 SHADER RENDER PASS FRAMEBUFFER VERIFICATION FAILED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V36 SHADER queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (vertexModule && destroyShaderModule) destroyShaderModule(device, vertexModule, NULL);
                                                        if (fragmentModule && destroyShaderModule) destroyShaderModule(device, fragmentModule, NULL);
                                                        if (pipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device, pipelineLayout, NULL); AzTrace("V36 SHADER vkDestroyPipelineLayout completed"); }
                                                        if (framebuffer && destroyFramebuffer) { destroyFramebuffer(device, framebuffer, NULL); AzTrace("V36 SHADER vkDestroyFramebuffer completed"); }
                                                        if (pass && destroyPass) { destroyPass(device, pass, NULL); AzTrace("V36 SHADER vkDestroyRenderPass completed"); }
                                                        if (view && destroyView) { destroyView(device, view, NULL); AzTrace("V36 SHADER vkDestroyImageView completed"); }
                                                        if (mapped && unmapMemory && dstMemory) {
                                                            unmapMemory(device, dstMemory); AzTrace("V36 SHADER vkUnmapMemory completed");
                                                        }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V36 SHADER vkDestroyBuffer completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V36 SHADER vkDestroyImage completed"); }
                                                        if (dstMemory && freeMemory) { freeMemory(device, dstMemory, NULL); AzTrace("V36 SHADER readback vkFreeMemory completed"); }
                                                        if (imageMemory && freeMemory) { freeMemory(device, imageMemory, NULL); AzTrace("V36 SHADER image vkFreeMemory completed"); }
                                                    } else {
                                                        AzTrace("V36 SHADER command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V36 SHADER before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V36 SHADER vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V36 SHADER before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V36 SHADER vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V36 SHADER command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V36 SHADER vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V36 SHADER before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V36 SHADER vkDestroyDevice completed");
                            }
                        } else { AzTrace("V36 SHADER no graphics-capable queue found"); }
                    } else { AzTrace("V36 SHADER invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V36 SHADER before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V36 SHADER vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V36 SHADER before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V36 SHADER dlclose succeeded" : "V36 SHADER dlclose failed");
    AzTrace("V36 SHADER isolated render target and pipeline-layout setup only; no surface/swapchain; software renderer unchanged");
}


