                                            AzTrace("V46 GUARD before vkCreateCommandPool");
                                            AzVkResult poolResult = createPool(device, &poolInfo, NULL, &pool);
                                            snprintf(line, sizeof(line), "V46 GUARD vkCreateCommandPool result=%d pool=%s", (int)poolResult, pool ? "non-null" : "null");
