                                                        AzVkMapMemory mapMemory = (AzVkMapMemory)getDeviceProc(device, "vkMapMemory");
                                                        AzVkUnmapMemory unmapMemory = (AzVkUnmapMemory)getDeviceProc(device, "vkUnmapMemory");
                                                        AzVkCreateImage createImage = (AzVkCreateImage)getDeviceProc(device, "vkCreateImage");
                                                        AzVkDestroyImage destroyImage = (AzVkDestroyImage)getDeviceProc(device, "vkDestroyImage");
