                                                        AzVkImage targetImage = NULL;
                                                        AzVkBuffer dstBuffer = NULL;
                                                        AzVkDeviceMemory imageMemory = NULL;
                                                        AzVkDeviceMemory targetMemory = NULL;
                                                        AzVkDeviceMemory dstMemory = NULL;
                                                        void *mapped = NULL;
