                                                        const AzVkDeviceSize testBytes = 192; // 64-byte readback + 64-byte offset + 4 padded rows of 32 bytes
                                                        const uint32_t texels[16] = {0xff0000ffu,0xff00ff00u,0xffff0000u,0xffffffffu, 0xff00ff00u,0xffff0000u,0xffffffffu,0xff0000ffu, 0xffff0000u,0xffffffffu,0xff0000ffu,0xff00ff00u, 0xffffffffu,0xff0000ffu,0xff00ff00u,0xffff0000u};
