                                                                        return;
                                                                    }
                                                                    if (submitResult == 0 && waitResult == 0 && mapped) {
                                                                        const uint32_t *words = (const uint32_t *)mapped;
                                                                        uint32_t good = 0;
                                                                        for (uint32_t wi = 0; wi < 16; ++wi) {
                                                                            if (words[wi] == texels[wi]) ++good;
                                                                        }
                                                                        snprintf(line, sizeof(line), "V46 GUARD GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)texels[0]);
                                                                        AzTrace(line);
                                                                        // Guard bytes in the padded upload region must remain untouched.
                                                                        uint32_t paddingGood = 0;
                                                                        const uint8_t *raw = (const uint8_t *)mapped;
                                                                        for (uint32_t row = 0; row < 4; ++row) {
                                                                            for (uint32_t pi = 16; pi < 32; ++pi) {
                                                                                if (raw[64 + row * 32 + pi] == 0xa5u) ++paddingGood;
                                                                            }
                                                                        }
                                                                        snprintf(line, sizeof(line), "V46 GUARD upload padding intact=%u/64", (unsigned)paddingGood);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V46 GUARD SENTINEL-PROTECTED TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V46 GUARD SENTINEL-PROTECTED TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                    }
                                                                } else {
