    typedef AzVkResult (*AzVkMapMemory)(AzVkDevice, AzVkDeviceMemory, AzVkDeviceSize, AzVkDeviceSize, uint32_t, void **);
    typedef void (*AzVkUnmapMemory)(AzVkDevice, AzVkDeviceMemory);
    // Vulkan 1.0 image structures and function signatures (no Vulkan SDK required).
    typedef void *AzVkImage;
    typedef struct { uint32_t width, height, depth; } AzVkExtent3D;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t imageType, format; AzVkExtent3D extent; uint32_t mipLevels, arrayLayers;
