    typedef void (*AzVkCmdCopyImage)(AzVkCommandBuffer, AzVkImage, uint32_t, AzVkImage, uint32_t, uint32_t, const AzVkImageCopy *);
    typedef void (*AzVkCmdCopyBufferToImage)(AzVkCommandBuffer, AzVkBuffer, AzVkImage, uint32_t, uint32_t, const AzVkBufferImageCopy *);
    typedef void (*AzVkCmdCopyImageToBuffer)(AzVkCommandBuffer, AzVkImage, uint32_t, AzVkBuffer, uint32_t, const AzVkBufferImageCopy *);
    typedef void (*AzVkCmdPipelineBarrier)(AzVkCommandBuffer, uint32_t, uint32_t, uint32_t, uint32_t, const AzVkMemoryBarrier *, uint32_t, const void *, uint32_t, const AzVkImageMemoryBarrier *);
    NSBundle *bundle = [NSBundle bundleForClass:[AzaharGameCore class]];
    NSString *path = [[bundle resourcePath] stringByAppendingPathComponent:@"Vulkan/libMoltenVK.dylib"];

    // Castle 47: Vulkan 1.0 sampled-image view, sampler and descriptor ABI.
    typedef void *AzVkImageView;
    typedef void *AzVkSampler;
    typedef void *AzVkDescriptorSetLayout;
    typedef void *AzVkDescriptorPool;
    typedef void *AzVkDescriptorSet;
    typedef struct { uint32_t r,g,b,a; } AzVkComponentMapping;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags; AzVkImage image;
