    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t bindingCount; const AzVkDescriptorSetLayoutBinding *pBindings;
    } AzVkDescriptorSetLayoutCreateInfo;
    typedef struct { uint32_t type,descriptorCount; } AzVkDescriptorPoolSize;
    typedef struct { uint32_t sType; const void *pNext; uint32_t flags;
        uint32_t maxSets,poolSizeCount; const AzVkDescriptorPoolSize *pPoolSizes;
    } AzVkDescriptorPoolCreateInfo;
    typedef struct { uint32_t sType; const void *pNext; AzVkDescriptorPool descriptorPool;
        uint32_t descriptorSetCount; const AzVkDescriptorSetLayout *pSetLayouts;
    } AzVkDescriptorSetAllocateInfo;
    typedef struct { AzVkSampler sampler; AzVkImageView imageView; uint32_t imageLayout; } AzVkDescriptorImageInfo;
    typedef struct { uint32_t sType; const void *pNext; AzVkDescriptorSet dstSet;
        uint32_t dstBinding,dstArrayElement,descriptorCount,descriptorType;
        const AzVkDescriptorImageInfo *pImageInfo; const void *pBufferInfo; const void *pTexelBufferView;
    } AzVkWriteDescriptorSet;
    typedef AzVkResult (*AzVkCreateImageView)(AzVkDevice,const AzVkImageViewCreateInfo *,const void *,AzVkImageView *);
    typedef void (*AzVkDestroyImageView)(AzVkDevice,AzVkImageView,const void *);
    typedef AzVkResult (*AzVkCreateSampler)(AzVkDevice,const AzVkSamplerCreateInfo *,const void *,AzVkSampler *);
    typedef void (*AzVkDestroySampler)(AzVkDevice,AzVkSampler,const void *);
    typedef AzVkResult (*AzVkCreateDescriptorSetLayout)(AzVkDevice,const AzVkDescriptorSetLayoutCreateInfo *,const void *,AzVkDescriptorSetLayout *);
    typedef void (*AzVkDestroyDescriptorSetLayout)(AzVkDevice,AzVkDescriptorSetLayout,const void *);
    typedef AzVkResult (*AzVkCreateDescriptorPool)(AzVkDevice,const AzVkDescriptorPoolCreateInfo *,const void *,AzVkDescriptorPool *);
