    typedef struct { uint32_t aspectMask, baseMipLevel, levelCount, baseArrayLayer, layerCount; } AzVkImageSubresourceRange;
    typedef struct { uint32_t aspectMask, mipLevel, baseArrayLayer, layerCount; } AzVkImageSubresourceLayers;
    typedef struct { int32_t x,y,z; } AzVkOffset3D;
    typedef struct { AzVkDeviceSize bufferOffset; uint32_t bufferRowLength, bufferImageHeight;
        AzVkImageSubresourceLayers imageSubresource; AzVkOffset3D imageOffset; AzVkExtent3D imageExtent;
    } AzVkBufferImageCopy;
    typedef struct { AzVkImageSubresourceLayers srcSubresource; AzVkOffset3D srcOffset;
        AzVkImageSubresourceLayers dstSubresource; AzVkOffset3D dstOffset; AzVkExtent3D extent;
    } AzVkImageCopy;
    typedef struct { uint32_t sType; const void *pNext; uint32_t srcAccessMask, dstAccessMask;
        uint32_t oldLayout, newLayout, srcQueueFamilyIndex, dstQueueFamilyIndex;
        AzVkImage image; AzVkImageSubresourceRange subresourceRange;
    } AzVkImageMemoryBarrier;
