                                                                                                                } else AzTrace("V54 PIPELINE pipeline or renderpass symbols unavailable");
                                                                                                            } else AzTrace("V54 PIPELINE SKIPPED vkCreateGraphicsPipelines: shader stages or pipeline layout unavailable");

                                                                                                        }
                                                                                                        snprintf(line,sizeof(line),"V54 PIPELINE vkCreateShaderModule vertex result=%d module=%s",(int)vertexResult50,vertexShaderReady50?"non-null":"null"); AzTrace(line);
                                                                                                        snprintf(line,sizeof(line),"V54 PIPELINE vkCreateShaderModule result=%d module=%s",(int)shaderResult49,shaderModuleReady49?"non-null":"null"); AzTrace(line);
                                                                                                    } else AzTrace("V54 PIPELINE shader module entry points unavailable");
                                                                                                }
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                }
                                                                            } else AzTrace("V54 PIPELINE descriptor entry points missing");
                                                                            AzVkResult mr = mapMemory(device, dstMemory, 0, testBytes, 0, &mapped);
                                                                            snprintf(line, sizeof(line), "V54 PIPELINE vkMapMemory result=%d", (int)mr); AzTrace(line);
                                                                            if (mr == 0 && mapped) {
                                                                                memset(mapped, 0xa5, (size_t)testBytes);
