                                                                                for (uint32_t row = 0; row < 4; ++row) {
                                                                                    memcpy(staging + row * 32, texels + row * 4, 16);
                                                                                }
                                                                                // Pre-submit proof: the GPU destination contains no source texels.
                                                                                bool cleanReadback = true;
                                                                                const uint8_t *initial = (const uint8_t *)mapped;
                                                                                for (uint32_t ci = 0; ci < 64; ++ci) {
                                                                                    if (initial[ci] != 0xa5u) cleanReadback = false;
                                                                                }
                                                                                AzTrace(cleanReadback ? "V54 PIPELINE pre-submit readback sentinel verified=64/64" : "V54 PIPELINE pre-submit readback sentinel FAILED");
                                                                                testReady = cleanReadback;
                                                                            }
                                                                        }
                                                                    }
                                                                } else { AzTrace("V54 PIPELINE no compatible memory type"); }
                                                            }
                                                        } else { AzTrace("V54 PIPELINE required Vulkan image functions unavailable"); }
                                                        if (testReady) {
                                                        AzVkCommandBufferBeginInfo beginInfo = {42, NULL, 0, NULL};
                                                        AzTrace("V54 PIPELINE before vkBeginCommandBuffer");
                                                        AzVkResult beginResult = beginBuffer(buffer, &beginInfo);
                                                        snprintf(line, sizeof(line), "V54 PIPELINE vkBeginCommandBuffer result=%d", (int)beginResult);
                                                        AzTrace(line);
                                                        if (beginResult == 0) {
                                                            // Bind the sampled texture descriptor for GRAPHICS (0).
                                                            // This probe intentionally has no draw call or sampling shader.
