                                                                        }
                                                                        snprintf(line, sizeof(line), "V54 PIPELINE GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)texels[0]);
                                                                        AzTrace(line);
                                                                        // Guard bytes in the padded upload region must remain untouched.
                                                                        uint32_t paddingGood = 0;
                                                                        const uint8_t *raw = (const uint8_t *)mapped;
                                                                        for (uint32_t row = 0; row < 4; ++row) {
                                                                            for (uint32_t pi = 16; pi < 32; ++pi) {
