                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V54 PIPELINE SENTINEL-PROTECTED TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V54 PIPELINE SENTINEL-PROTECTED TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady ? "V54 PIPELINE IMAGE VIEW SAMPLER DESCRIPTORS VERIFIED SUCCESS" : "V54 PIPELINE IMAGE VIEW SAMPLER DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded ? "V54 PIPELINE PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND VERIFIED SUCCESS" : "V54 PIPELINE PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V54 PIPELINE FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V54 PIPELINE FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V54 PIPELINE VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V54 PIPELINE VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V54 PIPELINE SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V54 PIPELINE SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 ? "V54 PIPELINE TEXTURE SAMPLING FRAGMENT SHADER MODULE VERIFIED SUCCESS" : "V54 PIPELINE TEXTURE SAMPLING FRAGMENT SHADER MODULE NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 && pipelineStagesReady53 ? "V54 PIPELINE SAMPLING PIPELINE SHADER STAGES PREPARED SUCCESS" : "V54 PIPELINE SAMPLING PIPELINE SHADER STAGES NOT VERIFIED");
