                                                        if (texturePipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device,texturePipelineLayout,NULL); AzTrace("V54 PIPELINE vkDestroyPipelineLayout completed"); }
                                                        if (sampledPool && destroyPool) { destroyPool(device,sampledPool,NULL); AzTrace("V54 PIPELINE vkDestroyDescriptorPool completed"); }
                                                        if (sampledLayout && destroyLayout) { destroyLayout(device,sampledLayout,NULL); AzTrace("V54 PIPELINE vkDestroyDescriptorSetLayout completed"); }
                                                        if (sampledSampler && destroySampler) { destroySampler(device,sampledSampler,NULL); AzTrace("V54 PIPELINE vkDestroySampler completed"); }
                                                        if (sampledView && destroyView) { destroyView(device,sampledView,NULL); AzTrace("V54 PIPELINE vkDestroyImageView completed"); }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V54 PIPELINE vkDestroyBuffer completed"); }
                                                        if (targetImage && destroyImage) { destroyImage(device, targetImage, NULL); AzTrace("V54 PIPELINE vkDestroyImage target completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V54 PIPELINE vkDestroyImage completed"); }
                                                        if (dstMemory && freeMemory) { freeMemory(device, dstMemory, NULL); AzTrace("V54 PIPELINE readback vkFreeMemory completed"); }
                                                        if (targetMemory && freeMemory) { freeMemory(device, targetMemory, NULL); AzTrace("V54 PIPELINE target vkFreeMemory completed"); }
                                                        if (imageMemory && freeMemory) { freeMemory(device, imageMemory, NULL); AzTrace("V54 PIPELINE image vkFreeMemory completed"); }
                                                    } else {
                                                        AzTrace("V54 PIPELINE command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V54 PIPELINE before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V54 PIPELINE vkFreeCommandBuffers completed");
