                                                AzTrace("V54 PIPELINE before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V54 PIPELINE vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V54 PIPELINE command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V54 PIPELINE vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V54 PIPELINE before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V54 PIPELINE vkDestroyDevice completed");
                            }
                        } else { AzTrace("V54 PIPELINE no graphics-capable queue found"); }
                    } else { AzTrace("V54 PIPELINE invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V54 PIPELINE before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V54 PIPELINE vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V54 PIPELINE before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V54 PIPELINE dlclose succeeded" : "V54 PIPELINE dlclose failed");
    AzTrace("V54 PIPELINE isolated GPU image-to-image copy and readback only; no surface/swapchain; software renderer unchanged");
}

static void AzV55PipelineControl(void)
{
