                                                            AzTrace("V56 VERTEX-INPUT CONTROL before vkEndCommandBuffer");
                                                            AzVkResult endResult = endBuffer(buffer);
                                                            snprintf(line, sizeof(line), "V56 VERTEX-INPUT CONTROL vkEndCommandBuffer result=%d", (int)endResult);
                                                            AzTrace(line);
                                                            if (endResult == 0) {
                                                                AzVkQueueSubmit submit = (AzVkQueueSubmit)getDeviceProc(device, "vkQueueSubmit");
                                                                AzVkQueueWaitIdle waitIdle = (AzVkQueueWaitIdle)getDeviceProc(device, "vkQueueWaitIdle");
                                                                if (submit && waitIdle) {
                                                                    AzVkSubmitInfo submitInfo = {4, NULL, 0, NULL, NULL, 1, &buffer, 0, NULL};
                                                                    AzTrace("V56 VERTEX-INPUT CONTROL before vkQueueSubmit (padded texture upload, image-to-image copy, readback)");
                                                                    AzVkResult submitResult = submit(queue, 1, &submitInfo, NULL);
                                                                    snprintf(line, sizeof(line), "V56 VERTEX-INPUT CONTROL vkQueueSubmit result=%d", (int)submitResult);
                                                                    AzTrace(line);
                                                                    AzTrace("V56 VERTEX-INPUT CONTROL before vkQueueWaitIdle");
                                                                    AzVkResult waitResult = waitIdle(queue);
                                                                    snprintf(line, sizeof(line), "V56 VERTEX-INPUT CONTROL vkQueueWaitIdle result=%d", (int)waitResult);
                                                                    AzTrace(line);
                                                                    if (waitResult != 0) {
                                                                        AzTrace("V56 VERTEX-INPUT CONTROL queue not confirmed idle; retaining Vulkan objects and loader for safety");
                                                                        return;
                                                                    }
                                                                    if (submitResult == 0 && waitResult == 0 && mapped) {
                                                                        const uint32_t *words = (const uint32_t *)mapped;
                                                                        uint32_t good = 0;
                                                                        for (uint32_t wi = 0; wi < 16; ++wi) {
                                                                            if (words[wi] == texels[wi]) ++good;
                                                                        }
                                                                        snprintf(line, sizeof(line), "V56 VERTEX-INPUT CONTROL GPU readback verified=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)texels[0]);
                                                                        AzTrace(line);
                                                                        // Guard bytes in the padded upload region must remain untouched.
                                                                        uint32_t paddingGood = 0;
                                                                        const uint8_t *raw = (const uint8_t *)mapped;
                                                                        for (uint32_t row = 0; row < 4; ++row) {
                                                                            for (uint32_t pi = 16; pi < 32; ++pi) {
                                                                                if (raw[64 + row * 32 + pi] == 0xa5u) ++paddingGood;
                                                                            }
                                                                        }
                                                                        snprintf(line, sizeof(line), "V56 VERTEX-INPUT CONTROL upload padding intact=%u/64", (unsigned)paddingGood);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V56 VERTEX-INPUT CONTROL SENTINEL-PROTECTED TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL SENTINEL-PROTECTED TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady ? "V56 VERTEX-INPUT CONTROL IMAGE VIEW SAMPLER DESCRIPTORS VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL IMAGE VIEW SAMPLER DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded ? "V56 VERTEX-INPUT CONTROL PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V56 VERTEX-INPUT CONTROL FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V56 VERTEX-INPUT CONTROL VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V56 VERTEX-INPUT CONTROL SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 ? "V56 VERTEX-INPUT CONTROL TEXTURE SAMPLING FRAGMENT SHADER MODULE VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL TEXTURE SAMPLING FRAGMENT SHADER MODULE NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 && pipelineStagesReady53 ? "V56 VERTEX-INPUT CONTROL SAMPLING PIPELINE SHADER STAGES PREPARED SUCCESS" : "V56 VERTEX-INPUT CONTROL SAMPLING PIPELINE SHADER STAGES NOT VERIFIED");
                                                                        AzTrace(pipelineCreated54 && good == 16 && paddingGood == 64 ? "V56 VERTEX-INPUT CONTROL KNOWN-GOOD FRAGMENT GRAPHICS PIPELINE VERIFIED SUCCESS" : "V56 VERTEX-INPUT CONTROL KNOWN-GOOD FRAGMENT GRAPHICS PIPELINE NOT VERIFIED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V56 VERTEX-INPUT CONTROL queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (mapped && unmapMemory && dstMemory) {
                                                            unmapMemory(device, dstMemory); AzTrace("V56 VERTEX-INPUT CONTROL vkUnmapMemory completed");
                                                        }
                                                        // Descriptors reference the image view and sampler; release dependents first.
                                                        if (samplingShader52 && destroyShaderModule49) { destroyShaderModule49(device,samplingShader52,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyShaderModule sampling fragment completed"); }
                                                        if (vertexShader50 && destroyShaderModule49) { destroyShaderModule49(device,vertexShader50,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyShaderModule vertex completed"); }
                                                        if (fragmentShader49 && destroyShaderModule49) { destroyShaderModule49(device,fragmentShader49,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyShaderModule completed"); }
                                                        if (texturePipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device,texturePipelineLayout,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyPipelineLayout completed"); }
                                                        if (sampledPool && destroyPool) { destroyPool(device,sampledPool,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyDescriptorPool completed"); }
                                                        if (sampledLayout && destroyLayout) { destroyLayout(device,sampledLayout,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyDescriptorSetLayout completed"); }
                                                        if (sampledSampler && destroySampler) { destroySampler(device,sampledSampler,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroySampler completed"); }
                                                        if (sampledView && destroyView) { destroyView(device,sampledView,NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyImageView completed"); }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyBuffer completed"); }
                                                        if (targetImage && destroyImage) { destroyImage(device, targetImage, NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyImage target completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyImage completed"); }
                                                        if (dstMemory && freeMemory) { freeMemory(device, dstMemory, NULL); AzTrace("V56 VERTEX-INPUT CONTROL readback vkFreeMemory completed"); }
                                                        if (targetMemory && freeMemory) { freeMemory(device, targetMemory, NULL); AzTrace("V56 VERTEX-INPUT CONTROL target vkFreeMemory completed"); }
                                                        if (imageMemory && freeMemory) { freeMemory(device, imageMemory, NULL); AzTrace("V56 VERTEX-INPUT CONTROL image vkFreeMemory completed"); }
                                                    } else {
                                                        AzTrace("V56 VERTEX-INPUT CONTROL command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V56 VERTEX-INPUT CONTROL before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V56 VERTEX-INPUT CONTROL vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V56 VERTEX-INPUT CONTROL before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V56 VERTEX-INPUT CONTROL command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V56 VERTEX-INPUT CONTROL vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V56 VERTEX-INPUT CONTROL before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyDevice completed");
                            }
                        } else { AzTrace("V56 VERTEX-INPUT CONTROL no graphics-capable queue found"); }
                    } else { AzTrace("V56 VERTEX-INPUT CONTROL invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V56 VERTEX-INPUT CONTROL before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V56 VERTEX-INPUT CONTROL vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V56 VERTEX-INPUT CONTROL before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V56 VERTEX-INPUT CONTROL dlclose succeeded" : "V56 VERTEX-INPUT CONTROL dlclose failed");
    AzTrace("V56 VERTEX-INPUT CONTROL isolated GPU image-to-image copy and readback only; no surface/swapchain; software renderer unchanged");
}

