                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V57 SAMPLING PIPELINE SENTINEL-PROTECTED TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE SENTINEL-PROTECTED TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady ? "V57 SAMPLING PIPELINE IMAGE VIEW SAMPLER DESCRIPTORS VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE IMAGE VIEW SAMPLER DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded ? "V57 SAMPLING PIPELINE PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V57 SAMPLING PIPELINE FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V57 SAMPLING PIPELINE VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V57 SAMPLING PIPELINE SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 ? "V57 SAMPLING PIPELINE TEXTURE SAMPLING FRAGMENT SHADER MODULE VERIFIED SUCCESS" : "V57 SAMPLING PIPELINE TEXTURE SAMPLING FRAGMENT SHADER MODULE NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 && pipelineStagesReady53 ? "V57 SAMPLING PIPELINE SAMPLING PIPELINE SHADER STAGES PREPARED SUCCESS" : "V57 SAMPLING PIPELINE SAMPLING PIPELINE SHADER STAGES NOT VERIFIED");
