                                                        if (vertexShader50 && destroyShaderModule49) { destroyShaderModule49(device,vertexShader50,NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyShaderModule vertex completed"); }
                                                        if (fragmentShader49 && destroyShaderModule49) { destroyShaderModule49(device,fragmentShader49,NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyShaderModule completed"); }
                                                        if (texturePipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device,texturePipelineLayout,NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyPipelineLayout completed"); }
