                                                        if (sampledView && destroyView) { destroyView(device,sampledView,NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyImageView completed"); }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyBuffer completed"); }
                                                        if (targetImage && destroyImage) { destroyImage(device, targetImage, NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyImage target completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V57 SAMPLING PIPELINE vkDestroyImage completed"); }
