                                            }
                                        } else {
                                            AzTrace("V57 SAMPLING PIPELINE command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V57 SAMPLING PIPELINE vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V57 SAMPLING PIPELINE before vkDestroyDevice");
