            }
        }
        AzTrace("V57 SAMPLING PIPELINE before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V57 SAMPLING PIPELINE vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V57 SAMPLING PIPELINE before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V57 SAMPLING PIPELINE dlclose succeeded" : "V57 SAMPLING PIPELINE dlclose failed");
    AzTrace("V57 SAMPLING PIPELINE isolated sampling-pipeline creation and texture-transfer diagnostics only; no surface/swapchain; software renderer unchanged");
}

// Castle 58: independent framebuffer readiness probe; software path unchanged.
static void AzV58FramebufferControl(void)
{
    typedef void *AzVkInstance;
    typedef void *AzVkPhysicalDevice;
    typedef void *AzVkDevice;
    typedef void *AzVkQueue;
    typedef int32_t AzVkResult;
