                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V59 TEXTURED DRAW FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V59 TEXTURED DRAW FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V59 TEXTURED DRAW VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V59 TEXTURED DRAW VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
