        destroyInstance(instance, NULL);
        AzTrace("V59 TEXTURED DRAW vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V59 TEXTURED DRAW before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V59 TEXTURED DRAW dlclose succeeded" : "V59 TEXTURED DRAW dlclose failed");
    AzTrace("V59 TEXTURED DRAW isolated experimental offscreen textured draw; no surface/swapchain; software renderer unchanged");
}


