                                                                            for (uint32_t pi = 16; pi < 32; ++pi) {
                                                                                if (raw[64 + row * 32 + pi] == 0xa5u) ++paddingGood;
                                                                            }
                                                                        }
                                                                        snprintf(line, sizeof(line), "V60 UV FLIP DRAW upload padding intact=%u/64", (unsigned)paddingGood);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V60 UV FLIP DRAW HORIZONTAL UV FLIP EXACT PIXEL MATCH VERIFIED SUCCESS" : "V60 UV FLIP DRAW HORIZONTAL UV FLIP PIXEL MATCH INCOMPLETE (inspect pixel values)");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady ? "V60 UV FLIP DRAW IMAGE VIEW SAMPLER DESCRIPTORS VERIFIED SUCCESS" : "V60 UV FLIP DRAW IMAGE VIEW SAMPLER DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded ? "V60 UV FLIP DRAW PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND VERIFIED SUCCESS" : "V60 UV FLIP DRAW PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V60 UV FLIP DRAW FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V60 UV FLIP DRAW FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V60 UV FLIP DRAW VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V60 UV FLIP DRAW VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V60 UV FLIP DRAW SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V60 UV FLIP DRAW SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 ? "V60 UV FLIP DRAW TEXTURE SAMPLING FRAGMENT SHADER MODULE VERIFIED SUCCESS" : "V60 UV FLIP DRAW TEXTURE SAMPLING FRAGMENT SHADER MODULE NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 && pipelineStagesReady53 ? "V60 UV FLIP DRAW SAMPLING PIPELINE SHADER STAGES PREPARED SUCCESS" : "V60 UV FLIP DRAW SAMPLING PIPELINE SHADER STAGES NOT VERIFIED");
                                                                        AzTrace(pipelineCreated54 && good == 16 && paddingGood == 64 ? "V60 UV FLIP DRAW TEXTURE-SAMPLING FRAGMENT GRAPHICS PIPELINE VERIFIED SUCCESS" : "V60 UV FLIP DRAW KNOWN-GOOD FRAGMENT GRAPHICS PIPELINE NOT VERIFIED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V60 UV FLIP DRAW queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (mapped && unmapMemory && dstMemory) {
                                                            unmapMemory(device, dstMemory); AzTrace("V60 UV FLIP DRAW vkUnmapMemory completed");
                                                        }
                                                        // Descriptors reference the image view and sampler; release dependents first.
                                                        if (samplingShader52 && destroyShaderModule49) { destroyShaderModule49(device,samplingShader52,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyShaderModule sampling fragment completed"); }
                                                        if (vertexShader50 && destroyShaderModule49) { destroyShaderModule49(device,vertexShader50,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyShaderModule vertex completed"); }
                                                        if (fragmentShader49 && destroyShaderModule49) { destroyShaderModule49(device,fragmentShader49,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyShaderModule completed"); }
                                                        if (texturePipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device,texturePipelineLayout,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyPipelineLayout completed"); }
                                                        if (sampledPool && destroyPool) { destroyPool(device,sampledPool,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyDescriptorPool completed"); }
                                                        if (sampledLayout && destroyLayout) { destroyLayout(device,sampledLayout,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyDescriptorSetLayout completed"); }
                                                        if (sampledSampler && destroySampler) { destroySampler(device,sampledSampler,NULL); AzTrace("V60 UV FLIP DRAW vkDestroySampler completed"); }
                                                        if (sampledView && destroyView) { destroyView(device,sampledView,NULL); AzTrace("V60 UV FLIP DRAW vkDestroyImageView completed"); }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V60 UV FLIP DRAW vkDestroyBuffer completed"); }
                                                        if (drawFramebuffer60) {
                                                            typedef void (*Az60DestroyFramebuffer)(AzVkDevice,void *,const void *);
                                                            Az60DestroyFramebuffer df59=(Az60DestroyFramebuffer)getDeviceProc(device,"vkDestroyFramebuffer");
                                                            if (df59) df59(device,drawFramebuffer60,NULL);
                                                        }
                                                        if (drawPipeline60) {
                                                            typedef void (*Az60DestroyPipeline)(AzVkDevice,void *,const void *);
                                                            Az60DestroyPipeline dp59=(Az60DestroyPipeline)getDeviceProc(device,"vkDestroyPipeline");
                                                            if (dp59) dp59(device,drawPipeline60,NULL);
                                                        }
                                                        if (drawPass60) {
                                                            typedef void (*Az60DestroyRenderPass)(AzVkDevice,void *,const void *);
                                                            Az60DestroyRenderPass dr59=(Az60DestroyRenderPass)getDeviceProc(device,"vkDestroyRenderPass");
                                                            if (dr59) dr59(device,drawPass60,NULL);
                                                        }
                                                        if (drawTargetView60 && destroyView) destroyView(device,drawTargetView60,NULL);
                                                        if (targetImage && destroyImage) { destroyImage(device, targetImage, NULL); AzTrace("V60 UV FLIP DRAW vkDestroyImage target completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V60 UV FLIP DRAW vkDestroyImage completed"); }
                                                        if (dstMemory && freeMemory) { freeMemory(device, dstMemory, NULL); AzTrace("V60 UV FLIP DRAW readback vkFreeMemory completed"); }
                                                        if (targetMemory && freeMemory) { freeMemory(device, targetMemory, NULL); AzTrace("V60 UV FLIP DRAW target vkFreeMemory completed"); }
                                                        if (imageMemory && freeMemory) { freeMemory(device, imageMemory, NULL); AzTrace("V60 UV FLIP DRAW image vkFreeMemory completed"); }
                                                    } else {
                                                        AzTrace("V60 UV FLIP DRAW command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V60 UV FLIP DRAW before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V60 UV FLIP DRAW vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V60 UV FLIP DRAW before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V60 UV FLIP DRAW vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V60 UV FLIP DRAW command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V60 UV FLIP DRAW vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V60 UV FLIP DRAW before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V60 UV FLIP DRAW vkDestroyDevice completed");
                            }
                        } else { AzTrace("V60 UV FLIP DRAW no graphics-capable queue found"); }
                    } else { AzTrace("V60 UV FLIP DRAW invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V60 UV FLIP DRAW before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V60 UV FLIP DRAW vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V60 UV FLIP DRAW before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V60 UV FLIP DRAW dlclose succeeded" : "V60 UV FLIP DRAW dlclose failed");
    AzTrace("V60 UV FLIP DRAW isolated horizontal-UV-flip offscreen textured draw; no surface/swapchain; software renderer unchanged");
}


