                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V64 TEXTURE SCALE TEXTURE SCALE EXACT PIXEL MATCH VERIFIED SUCCESS" : "V64 TEXTURE SCALE TEXTURE SCALE PIXEL MATCH INCOMPLETE (inspect pixel values)");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady ? "V64 TEXTURE SCALE IMAGE VIEW SAMPLER DESCRIPTORS VERIFIED SUCCESS" : "V64 TEXTURE SCALE IMAGE VIEW SAMPLER DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded ? "V64 TEXTURE SCALE PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND VERIFIED SUCCESS" : "V64 TEXTURE SCALE PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V64 TEXTURE SCALE FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V64 TEXTURE SCALE FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V64 TEXTURE SCALE VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V64 TEXTURE SCALE VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V64 TEXTURE SCALE SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V64 TEXTURE SCALE SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 ? "V64 TEXTURE SCALE TEXTURE SAMPLING FRAGMENT SHADER MODULE VERIFIED SUCCESS" : "V64 TEXTURE SCALE TEXTURE SAMPLING FRAGMENT SHADER MODULE NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 && pipelineStagesReady53 ? "V64 TEXTURE SCALE SAMPLING PIPELINE SHADER STAGES PREPARED SUCCESS" : "V64 TEXTURE SCALE SAMPLING PIPELINE SHADER STAGES NOT VERIFIED");
