    }
close_loader:
    AzTrace("V64 TEXTURE SCALE before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V64 TEXTURE SCALE dlclose succeeded" : "V64 TEXTURE SCALE dlclose failed");
