close_loader:
    AzTrace("V72 FRACTIONAL REPEAT before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V72 FRACTIONAL REPEAT dlclose succeeded" : "V72 FRACTIONAL REPEAT dlclose failed");
    AzTrace("V72 FRACTIONAL REPEAT isolated quarter-period-shifted repeat-wrapped UV diagnostic draw; no surface/swapchain; software renderer unchanged");
}


