                                                            AzVkImageMemoryBarrier targetToSrc = {45, NULL, 0x100u, 0x800u, 6, 6, 0xffffffffu, 0xffffffffu, targetImage, range};
                                                            cmdBarrier(buffer, 0x400u, 0x1000u, 0, 0, NULL, 0, NULL, 1, &targetToSrc);
