                                                                                (unsigned)words[yy*4], (unsigned)words[yy*4+1], (unsigned)words[yy*4+2], (unsigned)words[yy*4+3]);
                                                                            AzTrace(line);
                                                                        }
                                                                        for (uint32_t yy = 0; yy < 4; ++yy) {
                                                                            uint32_t ry = yy % 2u;
                                                                            snprintf(line, sizeof(line), "V73 NEGATIVE REPEAT periodic reference row %u: %08x %08x %08x %08x", (unsigned)yy,
                                                                                (unsigned)words[ry*4], (unsigned)words[ry*4+1], (unsigned)words[ry*4], (unsigned)words[ry*4+1]);
                                                                            AzTrace(line);
                                                                        }
                                                                        snprintf(line, sizeof(line), "V73 NEGATIVE REPEAT GPU repeat periodicity rendered pixel matches=%u/16 first=0x%08x expected=0x%08x", (unsigned)good, (unsigned)words[0], (unsigned)words[0]);
                                                                        AzTrace(line);
                                                                        // Guard bytes in the padded upload region must remain untouched.
                                                                        uint32_t paddingGood = 0;
                                                                        const uint8_t *raw = (const uint8_t *)mapped;
                                                                        for (uint32_t row = 0; row < 4; ++row) {
                                                                            for (uint32_t pi = 16; pi < 32; ++pi) {
                                                                                if (raw[64 + row * 32 + pi] == 0xa5u) ++paddingGood;
                                                                            }
                                                                        }
                                                                        snprintf(line, sizeof(line), "V73 NEGATIVE REPEAT upload padding intact=%u/64", (unsigned)paddingGood);
                                                                        AzTrace(line);
                                                                        AzTrace(good == 16 && paddingGood == 64 ? "V73 NEGATIVE REPEAT FRACTIONAL REPEAT PERIODICITY VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT REPEAT PERIODICITY INCOMPLETE (inspect pixel values)");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady ? "V73 NEGATIVE REPEAT IMAGE VIEW SAMPLER DESCRIPTORS VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT IMAGE VIEW SAMPLER DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded ? "V73 NEGATIVE REPEAT PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT PIPELINE LAYOUT AND GRAPHICS DESCRIPTOR BIND NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 ? "V73 NEGATIVE REPEAT FRAGMENT MODULE AND DESCRIPTOR RESOURCES VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT FRAGMENT MODULE AND DESCRIPTOR RESOURCES NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V73 NEGATIVE REPEAT VERTEX FRAGMENT AND TEXTURE DESCRIPTORS VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT VERTEX FRAGMENT AND TEXTURE DESCRIPTORS NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 ? "V73 NEGATIVE REPEAT SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT SHADER READ TRANSITIONS AND TEXTURE ROUNDTRIP NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 ? "V73 NEGATIVE REPEAT TEXTURE SAMPLING FRAGMENT SHADER MODULE VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT TEXTURE SAMPLING FRAGMENT SHADER MODULE NOT VERIFIED");
                                                                        AzTrace(good == 16 && paddingGood == 64 && descriptorsReady && texturePipelineLayout && descriptorBindRecorded && shaderModuleReady49 && vertexShaderReady50 && samplingShaderReady52 && pipelineStagesReady53 ? "V73 NEGATIVE REPEAT SAMPLING PIPELINE SHADER STAGES PREPARED SUCCESS" : "V73 NEGATIVE REPEAT SAMPLING PIPELINE SHADER STAGES NOT VERIFIED");
                                                                        AzTrace(pipelineCreated54 && good == 16 && paddingGood == 64 ? "V73 NEGATIVE REPEAT TEXTURE-SAMPLING FRAGMENT GRAPHICS PIPELINE VERIFIED SUCCESS" : "V73 NEGATIVE REPEAT KNOWN-GOOD FRAGMENT GRAPHICS PIPELINE NOT VERIFIED");
                                                                    }
                                                                } else {
                                                                    AzTrace("V73 NEGATIVE REPEAT queue submit/wait functions missing; skipping submission");
                                                                }
                                                            }
                                                        }
                                                        } // testReady
                                                        if (mapped && unmapMemory && dstMemory) {
                                                            unmapMemory(device, dstMemory); AzTrace("V73 NEGATIVE REPEAT vkUnmapMemory completed");
                                                        }
                                                        // Descriptors reference the image view and sampler; release dependents first.
                                                        if (samplingShader52 && destroyShaderModule49) { destroyShaderModule49(device,samplingShader52,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyShaderModule sampling fragment completed"); }
                                                        if (vertexShader50 && destroyShaderModule49) { destroyShaderModule49(device,vertexShader50,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyShaderModule vertex completed"); }
                                                        if (fragmentShader49 && destroyShaderModule49) { destroyShaderModule49(device,fragmentShader49,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyShaderModule completed"); }
                                                        if (texturePipelineLayout && destroyPipelineLayout) { destroyPipelineLayout(device,texturePipelineLayout,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyPipelineLayout completed"); }
                                                        if (sampledPool && destroyPool) { destroyPool(device,sampledPool,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyDescriptorPool completed"); }
                                                        if (sampledLayout && destroyLayout) { destroyLayout(device,sampledLayout,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyDescriptorSetLayout completed"); }
                                                        if (sampledSampler && destroySampler) { destroySampler(device,sampledSampler,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroySampler completed"); }
                                                        if (sampledView && destroyView) { destroyView(device,sampledView,NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyImageView completed"); }
                                                        if (dstBuffer && destroyBuffer) { destroyBuffer(device, dstBuffer, NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyBuffer completed"); }
                                                        if (drawFramebuffer73) {
                                                            typedef void (*Az73DestroyFramebuffer)(AzVkDevice,void *,const void *);
                                                            Az73DestroyFramebuffer df59=(Az73DestroyFramebuffer)getDeviceProc(device,"vkDestroyFramebuffer");
                                                            if (df59) df59(device,drawFramebuffer73,NULL);
                                                        }
                                                        if (drawPipeline73) {
                                                            typedef void (*Az73DestroyPipeline)(AzVkDevice,void *,const void *);
                                                            Az73DestroyPipeline dp59=(Az73DestroyPipeline)getDeviceProc(device,"vkDestroyPipeline");
                                                            if (dp59) dp59(device,drawPipeline73,NULL);
                                                        }
                                                        if (drawPass73) {
                                                            typedef void (*Az73DestroyRenderPass)(AzVkDevice,void *,const void *);
                                                            Az73DestroyRenderPass dr59=(Az73DestroyRenderPass)getDeviceProc(device,"vkDestroyRenderPass");
                                                            if (dr59) dr59(device,drawPass73,NULL);
                                                        }
                                                        if (drawTargetView73 && destroyView) destroyView(device,drawTargetView73,NULL);
                                                        if (targetImage && destroyImage) { destroyImage(device, targetImage, NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyImage target completed"); }
                                                        if (image && destroyImage) { destroyImage(device, image, NULL); AzTrace("V73 NEGATIVE REPEAT vkDestroyImage completed"); }
                                                        if (dstMemory && freeMemory) { freeMemory(device, dstMemory, NULL); AzTrace("V73 NEGATIVE REPEAT readback vkFreeMemory completed"); }
                                                        if (targetMemory && freeMemory) { freeMemory(device, targetMemory, NULL); AzTrace("V73 NEGATIVE REPEAT target vkFreeMemory completed"); }
                                                        if (imageMemory && freeMemory) { freeMemory(device, imageMemory, NULL); AzTrace("V73 NEGATIVE REPEAT image vkFreeMemory completed"); }
                                                    } else {
                                                        AzTrace("V73 NEGATIVE REPEAT command buffer recording or memory properties unavailable; skipping GPU buffer probe");
                                                    }
                                                    AzTrace("V73 NEGATIVE REPEAT before vkFreeCommandBuffers");
                                                    freeBuffers(device, pool, 1, &buffer);
                                                    AzTrace("V73 NEGATIVE REPEAT vkFreeCommandBuffers completed");
                                                }
                                                AzTrace("V73 NEGATIVE REPEAT before vkDestroyCommandPool");
                                                destroyPool(device, pool, NULL);
                                                AzTrace("V73 NEGATIVE REPEAT vkDestroyCommandPool completed");
                                            }
                                        } else {
                                            AzTrace("V73 NEGATIVE REPEAT command pool/buffer functions missing; skipping");
                                        }
                                    }
                                } else {
                                    AzTrace("V73 NEGATIVE REPEAT vkGetDeviceQueue unavailable");
                                }
                                AzTrace("V73 NEGATIVE REPEAT before vkDestroyDevice");
                                destroyDevice(device, NULL);
                                AzTrace("V73 NEGATIVE REPEAT vkDestroyDevice completed");
                            }
                        } else { AzTrace("V73 NEGATIVE REPEAT no graphics-capable queue found"); }
                    } else { AzTrace("V73 NEGATIVE REPEAT invalid/unsupported queue-family count"); }
                }
            }
        }
        AzTrace("V73 NEGATIVE REPEAT before vkDestroyInstance");
        destroyInstance(instance, NULL);
        AzTrace("V73 NEGATIVE REPEAT vkDestroyInstance completed");
    }
close_loader:
    AzTrace("V73 NEGATIVE REPEAT before dlclose bundled MoltenVK");
    int closed = dlclose(handle);
    AzTrace(closed == 0 ? "V73 NEGATIVE REPEAT dlclose succeeded" : "V73 NEGATIVE REPEAT dlclose failed");
    AzTrace("V73 NEGATIVE REPEAT isolated negative-coordinate repeat-wrapped UV diagnostic draw; no surface/swapchain; software renderer unchanged");
}


