    char line[240];
    snprintf(line, sizeof(line), "V151 PERSISTENT_DESCRIPTOR phase=%s mask=0x%x expected=0x3f published=0 status=%s",
        phase, mask, mask == 0x3fu ? "PASS" : "FAIL");
    AzTrace(line);
