static void AzV113ReleaseOwner(void) {
    if (!gAzV113Owner.active) return;
    const bool hadDevice=gAzV113Owner.device && gAzV113Owner.destroyDevice;
    const bool hadInstance=gAzV113Owner.instance && gAzV113Owner.destroyInstance;
    const bool hadLibrary=gAzV113Owner.library!=nullptr;
    const unsigned descriptorReset = AzaharV151ResetDescriptor();
    AzTrace(descriptorReset && AzaharV151IsDescriptorCleared()
        ? "V151 DESCRIPTOR_RELEASE before_device_destroy=1 cleared=1 status=PASS"
        : "V151 DESCRIPTOR_RELEASE before_device_destroy=0 status=FAIL");
    if (hadDevice) gAzV113Owner.destroyDevice(gAzV113Owner.device,nullptr);
    if (hadInstance) gAzV113Owner.destroyInstance(gAzV113Owner.instance,nullptr);
    if (hadLibrary) dlclose(gAzV113Owner.library);
    gAzV113Owner={};
    char line[240];
    snprintf(line,sizeof(line),"V113 LANE_D OWNER_RELEASE device=%u instance=%u library=%u status=%s",
        (unsigned)hadDevice,(unsigned)hadInstance,(unsigned)hadLibrary,
        (hadDevice && hadInstance && hadLibrary)?"PASS":"FAIL");
    AzTrace(line);
