    snprintf(report157, sizeof(report157),
        "V157 UNPUBLISHED_CALLBACK_CONTRACT mask=0x%x expected=0x1ff bounded=1 replay_rejected=1 stale_rejected=1 published=0 status=%s",
        contract157, contract157 == 0x1ffu ? "PASS" : "FAIL");
    AzTrace(report157);
    AzTrace(AzaharV152AuditCallbacks()
        ? "V157 POST_TEST_CLEANUP inbox=0 counters=0 status=PASS"
        : "V157 POST_TEST_CLEANUP status=FAIL");
    const unsigned ingress158 = AzaharV158MalformedIngressRecoveryGate();
    char report158[240];
    snprintf(report158, sizeof(report158),
        "V158 MALFORMED_INGRESS_RECOVERY mask=0x%x expected=0x1ff invalid_rejected=1 recovered=1 published=0 status=%s",
        ingress158, ingress158 == 0x1ffu ? "PASS" : "FAIL");
    AzTrace(report158);
    AzTrace(AzaharV152AuditCallbacks()
        ? "V158 POST_TEST_CLEANUP inbox=0 counters=0 status=PASS"
        : "V158 POST_TEST_CLEANUP status=FAIL");
    const unsigned sync159 = AzaharV159SyncBoundaryGate();
    char report159[256];
    snprintf(report159,sizeof(report159),
        "V159 LANE_A SYNC_CALLBACK_BOUNDARY mask=0x%x expected=0xff wait=STUB_ONLY published=0 status=%s",
        sync159, sync159==0xffu ? "PASS":"FAIL");
    AzTrace(report159);
    const unsigned batch159 = AzaharV159MixedIngressBatchGate();
    snprintf(report159,sizeof(report159),
        "V159 LANE_B MIXED_INGRESS_BATCH mask=0x%x expected=0xff private=1 published=0 status=%s",
        batch159, batch159==0xffu ? "PASS":"FAIL");
    AzTrace(report159);
    AzTrace(AzaharV152AuditCallbacks()
        ? "V159 POST_TEST_CLEANUP inbox=0 counters=0 status=PASS"
        : "V159 POST_TEST_CLEANUP status=FAIL");
    AzTrace("V159 GPU_GATE handshake=REJECTED azahar_gpu_frames=0 presenter=ABSENT software_fallback=ENABLED");
    // Castle 160: six independent, private contract lanes (not six concurrent GPU users).
    const unsigned v160Expected[] = {0xffu,0x1fu,0x1fu,0x1fu,0x1fu,0x1fu};
    const char *v160Names[] = {"OFFICIAL_V5_DESCRIPTOR", "NULL_OWNER_RECOVERY",
        "BOUNDED_WAIT_ARRAY", "PENDING_REPLAY_GUARD", "GENERATION_FAMILY_DROP", "QUEUE_SYNC_ABI"};
    unsigned v160Actual[] = {AzaharV160LaneA(), AzaharV160LaneB(),
        AzaharV160LaneC(), AzaharV160LaneD(), AzaharV160LaneE(), AzaharV160LaneF()};
    char v160Line[256];
    for(unsigned lane=0;lane<6;lane++) {
        snprintf(v160Line,sizeof(v160Line),
            "V160 LANE_%c %s mask=0x%x expected=0x%x private=1 status=%s",
            'A'+lane,v160Names[lane],v160Actual[lane],v160Expected[lane],
            v160Actual[lane]==v160Expected[lane]?"PASS":"FAIL");
        AzTrace(v160Line);
    }
    AzTrace(AzaharV152AuditCallbacks()
        ? "V160 POST_TEST_CLEANUP inbox=0 counters=0 status=PASS"
        : "V160 POST_TEST_CLEANUP status=FAIL");
    AzTrace("V160 GPU_GATE wait=STUB_ONLY published=0 handshake=REJECTED azahar_gpu_frames=0 presenter=ABSENT software_fallback=ENABLED");
    // Castle 161: eight extra isolated lanes: malformed contracts, wait-width,
    // recoverability, queue/generation filtering, and repeated frame turnover.
    const char *v161Names[] = {"NULL_VIEW_RECOVERY", "WRONG_STYPE_RECOVERY",
       "WRONG_VIEWTYPE_RECOVERY", "NULL_WAIT_ARRAY_RECOVERY",
       "WAIT_COUNT_MATRIX", "INVALID_DURING_PENDING", "STALE_AND_WRONG_QUEUE",
       "SIXTEEN_FRAME_TURNOVER"};
    char v161Line[256];
    for (unsigned lane=0; lane<8; ++lane) {
        unsigned actual=AzaharV161Lane(lane);
        snprintf(v161Line,sizeof(v161Line),
           "V161 LANE_%c %s mask=0x%x expected=0x1f private=1 status=%s",
           'A'+lane,v161Names[lane],actual,actual==0x1fu?"PASS":"FAIL");
        AzTrace(v161Line);
    }
    AzTrace(AzaharV152AuditCallbacks()
        ? "V161 POST_TEST_CLEANUP inbox=0 counters=0 status=PASS"
        : "V161 POST_TEST_CLEANUP status=FAIL");
    AzTrace("V161 GPU_GATE wait=STUB_ONLY published=0 handshake=REJECTED azahar_gpu_frames=0 presenter=ABSENT software_fallback=ENABLED");
    // Castle 162: eight additional isolated ingress/consumption/recovery regressions.
    char v162Line[256];
    for (unsigned lane=0; lane<8; ++lane) {
        const unsigned actual=AzaharV162Lane(lane);
        snprintf(v162Line,sizeof(v162Line),
            "V162 LANE_%c WAIT_%u_RECOVERY mask=0x%x expected=0x3f private=1 status=%s",
            'A'+lane,lane,actual,actual==0x3fu?"PASS":"FAIL");
        AzTrace(v162Line);
    }
    AzTrace(AzaharV152AuditCallbacks()
        ? "V162 POST_TEST_CLEANUP inbox=0 counters=0 status=PASS"
        : "V162 POST_TEST_CLEANUP status=FAIL");
    AzTrace("V162 REAL_BRIDGE_AUDIT interface_published=0 hardware_handshake=REJECTED azahar_gpu_frames=0 openemu_presenter=ABSENT software_fallback=ENABLED");



    AzV151Audit("ACQUIRED");
        AzTrace("V113 DEVICE retained until preflight release; not shared with Azahar");
    } else {
        if (device && destroyDevice) destroyDevice(device,nullptr);
        if (instance && destroyInstance) destroyInstance(instance,nullptr);
        dlclose(library);
        AzTrace("V113 LANE_A OWNER_TRANSFER status=FAIL (probe did not acquire transferable owner)");
    }
}

- (BOOL)loadAzaharLibrary:(NSError **)error
{
    AzTrace("10 entering loadAzaharLibrary");
    AzTrace("V10 ARCH bridge=libretro software framebuffer; Vulkan probe is independent of Azahar renderer");
    AzTrace("V10 ARCH hardware requires frontend-owned Vulkan interface, lifecycle callbacks, image handoff and OpenEmu presentation");
    AzTrace("V12 AUDIT Vulkan preflight will reject unsupported HW interfaces, then reinitialize for Software");
    AzTrace("V29 PLAN v28 working display baseline; isolated empty Vulkan command-buffer submission probe");
    AzTrace("V11 AUDIT upstream Vulkan path requires ENABLE_VULKAN at build time");
    AzTrace("V11 AUDIT upstream Vulkan requests SET_HW_RENDER context_type=6 and SET_CONTEXT_NEGOTIATION");
    AzTrace("V11 AUDIT frontend must own compatible Vulkan context, callbacks, interface, frame presentation");
    AzTrace("V29 PROBE record and submit empty command buffer, wait for idle; no presentation");
    const char *legacyProbeFlag = getenv("AZAHAR_FULL_LEGACY_PROBES");
    const bool runLegacyProbes = legacyProbeFlag && strcmp(legacyProbeFlag,"1")==0;
    AzTrace(runLegacyProbes
        ? "V114 LANE_A LEGACY_PROBES mode=FULL status=OPT_IN"
        : "V114 LANE_A LEGACY_PROBES mode=SKIPPED status=PASS");
    if (runLegacyProbes) {
    AzV19AuditBundledVulkan();
    AzV20OpenCloseMoltenVK();
    AzV21QueryInstanceVersion();
    AzV22EnumerateInstanceExtensions();
    AzV23EnumeratePhysicalDevices();
    AzV24QueryPhysicalDeviceProperties();
    AzV25QueryQueueFamilies();
    AzV26CreateTemporaryLogicalDevice();
    AzV27AllocateCommandBuffer();
    AzV28RecordEmptyCommandBuffer();
    AzV29SubmitEmptyCommandBuffer();
    AzTrace("V30 PLAN v29 working display baseline; isolated GPU buffer fill and CPU readback verification");
    AzV30FillBufferReadback();
    AzTrace("V31 PLAN isolated GPU fill -> transfer barrier -> GPU buffer copy -> host readback; software rendering unchanged");
    AzV31CopyBufferReadback();
    AzTrace("V32 PLAN isolated 4x4 RGBA8 image clear red -> copy to readback buffer -> verify 16 pixels; software display unchanged");
    AzV32ImageClearReadback();
    AzTrace("V33 PLAN isolated 4x4 RGBA8 GPU source image clear -> image-to-image copy -> destination readback; software renderer unchanged");
    AzV33ImageToImageReadback();
    AzTrace("V34 PLAN isolated 4x4 Vulkan render pass/framebuffer color clear and CPU readback; software renderer unchanged");
    AzV34RenderPassReadback();
    AzTrace("V35 PLAN isolated Vulkan pipeline-layout creation plus render-target regression; no shader draw; software renderer unchanged");
    AzV35PipelinePreparation();
    AzV36ShaderModules();
    AzV37GraphicsPipeline();
    AzV38DrawTriangle();
    AzV39TrianglePattern();
    AzV40TwoTriangles();
    AzV41EdgeCoverage();
    AzV42TwoColors();
    AzV43InterpolatedColors();
    AzV44TextureUpload();
    AzV45PaddedTextureUpload();
    AzV46GuardedTextureUpload();
    AzV47TextureDescriptors();
    AzV48BindTextureDescriptors();
    AzV49ShaderStagePreparation();
    AzV50ShaderPairPreparation();
    AzV51ShaderReadLayoutTransition();
    AzV52SamplingShaderModule();
    AzV53SamplingPipelineStages();
    AzV54SamplingGraphicsPipeline();
    AzV55PipelineControl();
    AzV56VertexInputControl();
    AzV57SamplingPipelineControl();
    AzV58FramebufferControl();
    AzV59TexturedDrawControl();
    AzV60UVFlipDrawControl();
    AzV61VerticalUVFlipControl();
    AzV62DualAxisUVFlipControl();
    AzV63QuarterTurnUVControl();
    AzV64TextureScaleControl();
    AzV65OffsetCropScaleControl();
    AzV66UVRepeatWrapControl();
    AzV67WrapDiagnosticsControl();
    AzV68RepeatBoundaryControl();
    AzV69RepeatUVCorrectedControl();
    AzV70RepeatPeriodicityControl();
    AzV71ShiftedRepeatControl();
    AzV72FractionalRepeatControl();
    AzV73NegativeRepeatControl();
    AzV74ClampToEdgeControl();
    AzV75ClampToBorderControl();
    } // V114: expensive isolated legacy probes are opt-in; production bridge path stays active.
    AzTrace("V114 LANE_B LIBRETRO_LOAD_PATH legacy_probes_not_required=1 status=PASS");
    NSBundle *bundle = [NSBundle bundleForClass:[self class]];
    NSString *libraryPath =
        [[bundle resourcePath] stringByAppendingPathComponent:@"azahar_libretro.dylib"];

    AzTrace("11 before dlopen azahar_libretro.dylib");
    _azaharHandle = dlopen(libraryPath.fileSystemRepresentation, RTLD_NOW | RTLD_LOCAL);
    AzTrace(_azaharHandle ? "12 dlopen succeeded" : "12 dlopen failed");
    if (!_azaharHandle) {
        if (error) {
            NSString *reason = [NSString stringWithUTF8String:dlerror() ?: "unknown error"];
            *error = [NSError errorWithDomain:OEGameCoreErrorDomain
                                          code:OEGameCoreCouldNotLoadROMError
                                      userInfo:@{NSLocalizedDescriptionKey:
                                                     [NSString stringWithFormat:
                                                         @"Unable to load Azahar libretro core: %@",
                                                         reason]}];
        }
        return NO;
    }

#define LOAD_SYMBOL(name, member) \
    do { \
        _retro##member = (retro_##name##_t)dlsym(_azaharHandle, "retro_" #name); \
        if (!_retro##member) { \
            if (error) *error = [NSError errorWithDomain:OEGameCoreErrorDomain \
                code:OEGameCoreCouldNotLoadROMError userInfo:@{NSLocalizedDescriptionKey: \
                [NSString stringWithFormat:@"Azahar core is missing retro_%s.", #name]}]; \
            return NO; \
        } \
    } while (0)

    LOAD_SYMBOL(init, Init);
    LOAD_SYMBOL(deinit, Deinit);
    LOAD_SYMBOL(api_version, ApiVersion);
    LOAD_SYMBOL(get_system_info, GetSystemInfo);
    LOAD_SYMBOL(get_system_av_info, GetSystemAVInfo);
    LOAD_SYMBOL(set_environment, SetEnvironment);
    LOAD_SYMBOL(set_video_refresh, SetVideoRefresh);
    LOAD_SYMBOL(set_audio_sample, SetAudioSample);
    LOAD_SYMBOL(set_audio_sample_batch, SetAudioSampleBatch);
    LOAD_SYMBOL(set_input_poll, SetInputPoll);
    LOAD_SYMBOL(set_input_state, SetInputState);
    LOAD_SYMBOL(set_controller_port_device, SetControllerPortDevice);
    LOAD_SYMBOL(load_game, LoadGame);
    LOAD_SYMBOL(unload_game, UnloadGame);
    LOAD_SYMBOL(run, Run);
    LOAD_SYMBOL(reset, Reset);
    LOAD_SYMBOL(serialize_size, SerializeSize);
    LOAD_SYMBOL(serialize, Serialize);
    LOAD_SYMBOL(unserialize, Unserialize);
    LOAD_SYMBOL(get_region, GetRegion);

#undef LOAD_SYMBOL

    AzTrace("13 all required libretro symbols resolved");
    // Castle 143: independent binary-export audit of the ACTUAL loaded Azahar
    // dylib. Export presence is not proof of ENABLE_VULKAN; the environment
    // handshake is the authoritative test once hardware presentation exists.
    const char *v143Required[] = {
        "retro_init", "retro_deinit", "retro_api_version", "retro_get_system_info",
        "retro_get_system_av_info", "retro_set_environment", "retro_set_video_refresh",
        "retro_load_game", "retro_unload_game", "retro_run", "retro_reset",
        "retro_set_input_poll", "retro_set_input_state", "retro_set_audio_sample_batch",
        "retro_serialize", "retro_unserialize"
    };
    unsigned v143Exports = 0;
    for (const char *symbol : v143Required)
        if (dlsym(_azaharHandle, symbol)) ++v143Exports;
    char v143ExportsLine[320];
    snprintf(v143ExportsLine, sizeof(v143ExportsLine),
        "V143 CORE_EXPORTS required=%u found=%u status=%s vulkan_compiled=UNKNOWN",
        (unsigned)(sizeof(v143Required)/sizeof(v143Required[0])), v143Exports,
        v143Exports == sizeof(v143Required)/sizeof(v143Required[0]) ? "PASS" : "FAIL");
    AzTrace(v143ExportsLine);
    AzTrace("V143 CORE_CAPABILITY hardware_support=UNVERIFIED core_negotiation_callback=NOT_INVOKED software_fallback=ENABLED");

    // Castle 76: inspect the actual libretro boundary before attempting a real GPU bridge.
    // This is observational only: no callbacks are replaced and no renderer mode changes.
    AzTrace("V76 RENDERER BRIDGE AUDIT begin: actual loaded Azahar dylib");
    const char *bridgeSymbols[] = {
        "retro_set_environment", "retro_set_video_refresh", "retro_get_system_info",
        "retro_get_system_av_info", "retro_load_game", "retro_run",
        "retro_hw_get_current_framebuffer", "retro_hw_get_proc_address",
        "retro_get_memory_data", "retro_get_memory_size"
    };
    unsigned found76=0;
    for (unsigned i76=0; i76<sizeof(bridgeSymbols)/sizeof(bridgeSymbols[0]); ++i76) {
        const bool exists76=dlsym(_azaharHandle,bridgeSymbols[i76])!=NULL;
        found76+=(unsigned)exists76;
        char line76[256];
        snprintf(line76,sizeof(line76),"V76 RENDERER BRIDGE AUDIT export %s=%s",bridgeSymbols[i76],exists76?"present":"absent");
        AzTrace(line76);
    }
    char summary76[256];
    snprintf(summary76,sizeof(summary76),"V76 RENDERER BRIDGE AUDIT exports=%u/%u frontend=libretro Vulkan negotiation=SET_HW_RENDER then SET_CONTEXT_NEGOTIATION",
             found76,(unsigned)(sizeof(bridgeSymbols)/sizeof(bridgeSymbols[0])));
    AzTrace(summary76);
    AzTrace("V76 RENDERER BRIDGE AUDIT hardware callbacks belong to frontend; export absence does not imply missing GPU support");
    AzTrace("V76 RENDERER BRIDGE AUDIT next integration gate: supply valid libretro Vulkan HW context and negotiation interface; software fallback unchanged");
    AzTrace("V77 VULKAN BRIDGE PLAN begin: validating actual frontend negotiation boundary");
    AzTrace("V77 VULKAN BRIDGE PLAN Azahar is libretro core; OpenEmu wrapper owns environment callback and display path");
    AzTrace("V77 VULKAN BRIDGE PLAN offscreen MoltenVK success does NOT supply libretro retro_hw_render_interface_vulkan");
    AzTrace("V77 VULKAN BRIDGE PLAN next implementation requires real device ownership, Vulkan interface ABI, and frame presentation");

    return YES;
}

- (BOOL)loadFileAtPath:(NSString *)path error:(NSError **)error
{
    AzTrace("20 entered loadFileAtPath");
    if (![self loadAzaharLibrary:error])
        return NO;

    _romPath = [path copy];
    _supportPath = [[self supportDirectoryPath] copy];
    AzTrace(path ? "ROM NSString present" : "ERROR ROM NSString nil");
    AzTrace(_supportPath ? "Support NSString present" : "ERROR support NSString nil");
    if (!path || !path.fileSystemRepresentation || !path.fileSystemRepresentation[0] || !_supportPath || !_supportPath.fileSystemRepresentation) {
        AzTrace("ERROR required path is NULL or empty; refusing to enter libretro");
        if (error) *error = [NSError errorWithDomain:OEGameCoreErrorDomain
            code:OEGameCoreCouldNotLoadROMError
            userInfo:@{NSLocalizedDescriptionKey: @"Azahar diagnostic: missing ROM or support directory path."}];
        return NO;
    }
    AzTrace("ROM C path valid and nonempty");
    AzTrace("Support C path valid");

    [[NSFileManager defaultManager] createDirectoryAtPath:_supportPath
                              withIntermediateDirectories:YES
                                               attributes:nil error:nil];

    const BOOL saveDir190=[[NSFileManager defaultManager] isWritableFileAtPath:_supportPath];
    char savePath190[190];
    snprintf(savePath190,sizeof(savePath190),"V190 GAME_SAVE_DIRECTORY exists=%u writable=%u virtual_sd=ENABLED persistent_save=TO_BE_TESTED",
             (unsigned)[[NSFileManager defaultManager] fileExistsAtPath:_supportPath],(unsigned)saveDir190);
    AzTrace(savePath190);
    // OpenEmu stores display-mode preferences per core. Apply them before
    // retro_init/register-options so Azahar reads the selected values at load.
    NSString *savedGraphicsFile193=[_supportPath stringByAppendingPathComponent:@"AzaharDisplayPreferences-v193.plist"];
    NSDictionary *persistedGraphics193=[NSDictionary dictionaryWithContentsOfFile:savedGraphicsFile193];
    NSString *resolutionPreference = self.displayModeInfo[@"azaharResolution"];
    NSInteger savedResolution = [resolutionPreference respondsToSelector:@selector(integerValue)]
        ? [resolutionPreference integerValue] : 0;
    // v211 migration: existing installations may have v210's 7x/8x saved in
    // OpenEmu displayModeInfo. Clamp ONLY those valid legacy values to 6x.
    if (savedResolution >= 1 && savedResolution <= 8)
        _az191Resolution = std::min(savedResolution, (NSInteger)6);
    NSNumber *persistedResolution193=persistedGraphics193[@"resolution"];
    if ([persistedResolution193 respondsToSelector:@selector(integerValue)] &&
        persistedResolution193.integerValue>=1 && persistedResolution193.integerValue<=8)
        _az191Resolution=std::min(persistedResolution193.integerValue,(NSInteger)6);
    NSString *stereoPreference = self.displayModeInfo[@"azaharStereo"];
    if ([stereoPreference isKindOfClass:[NSString class]] &&
        [@[@"off", @"side-by-side", @"side-by-side-full", @"anaglyph"] containsObject:stereoPreference])
        _az191Stereo = stereoPreference;
    NSString *persistedStereo193=persistedGraphics193[@"stereo"];
    if ([persistedStereo193 isKindOfClass:[NSString class]] &&
        [@[@"off", @"side-by-side", @"side-by-side-full", @"anaglyph"] containsObject:persistedStereo193])
        _az191Stereo=persistedStereo193;
    // v195: Prefer the independently persisted value, as with stereo mode.
    // The old v194 file has no depth entry; 80% is our compatible default.
    id hostDepth195=self.displayModeInfo[@"azaharDepth"];
    NSInteger hostDepthValue195=[hostDepth195 respondsToSelector:@selector(integerValue)]
        ? [hostDepth195 integerValue] : 0;
    if(hostDepthValue195>=10 && hostDepthValue195<=100 && hostDepthValue195%10==0)
        _az195Depth=hostDepthValue195;
    id savedDepth195=persistedGraphics193[@"depth"];
    NSInteger savedDepthValue195=[savedDepth195 respondsToSelector:@selector(integerValue)]
        ? [savedDepth195 integerValue] : 0;
    if(savedDepthValue195>=10 && savedDepthValue195<=100 && savedDepthValue195%10==0)
        _az195Depth=savedDepthValue195;
    // Physical output is automatic and independent of the deprecated saved
    // hostScale setting: 1x internal -> native, 2x..6x -> physical 2x.
    // Neither the saved OpenEmu zoom nor the System Plugin is modified.
    _az207PendingHostScale=2u;
    AzTrace("V210 PHYSICAL_SETTINGS legacy_hostScale=IGNORED auto_output=1X_IF_NATIVE_ELSE_2X");
    _az193StablePresentation=(_az191Resolution>1 &&
                              ![_az191Stereo isEqualToString:@"side-by-side-full"]);
    Az197LockSessionGeometry(self,"restored_pre_init");
    Az191ApplyGraphicsOptions(self);
    // The game can create its Vulkan renderer *after* the options were read.
    // Trigger an initial update, then a bounded post-load reassertion when
    // the first real gameplay frames execute (not during preflight).
    _az191OptionDirty = YES;
    char restore193[280];
    snprintf(restore193,sizeof(restore193),
        "V193 GRAPHICS_RESTORE saved_file=%u host_stereo=%s selected_stereo=%s resolution=%ld stable_present=%u",
        (unsigned)(persistedGraphics193!=nil),
        [stereoPreference isKindOfClass:[NSString class]]?stereoPreference.UTF8String:"(none)",
        _az191Stereo.UTF8String,(long)_az191Resolution,(unsigned)_az193StablePresentation);
    AzTrace(restore193);
    char config191[220];
    snprintf(config191,sizeof(config191),
        "V195 GRAPHICS_INITIAL resolution=%ld stereo=%s depth=%ld variables=READY",
        (long)_az191Resolution,_az191Stereo.UTF8String,(long)_az195Depth);
    AzTrace(config191);
    AzTrace("21 before registering libretro callbacks");
    _retroSetEnvironment(AzEnvironment);
    _retroSetVideoRefresh(AzVideo);
    _retroSetAudioSample(AzAudioSample);
    _retroSetAudioSampleBatch(AzAudio);
    _retroSetInputPoll(AzInputPoll);
    _retroSetInputState(AzInputState);

    AzTrace("22 before retro_init");
    _retroInit();
    AzTrace("23 returned from retro_init");
    _initialized = YES;

    struct retro_system_info info = {};
    AzTrace("24 before retro_get_system_info");
    _retroGetSystemInfo(&info);
    AzTrace("25 returned from retro_get_system_info");

    if (!info.need_fullpath) {
        if (error)
            *error = [NSError errorWithDomain:OEGameCoreErrorDomain
                                         code:OEGameCoreCouldNotLoadROMError
                                     userInfo:@{NSLocalizedDescriptionKey:
                                                    @"The Azahar core unexpectedly requires an in-memory ROM."}];
        return NO;
    }

    // Diagnostic: give libretro a separately allocated, stable ROM path.
    // Keep it alive until dealloc, after retro_unload_game / retro_deinit.
    const char *romPath = _romPath.fileSystemRepresentation;
    free(_stableRomPath);
    _stableRomPath = romPath ? strdup(romPath) : NULL;
    if (!_stableRomPath || !_stableRomPath[0]) {
        AzTrace("ERROR unable to allocate stable ROM path");
        if (error) *error = [NSError errorWithDomain:OEGameCoreErrorDomain
            code:OEGameCoreCouldNotLoadROMError
            userInfo:@{NSLocalizedDescriptionKey: @"Azahar diagnostic: unable to allocate ROM path."}];
        return NO;
    }
    struct retro_game_info game = {};
    game.path = _stableRomPath;
    AzTrace("game.path uses dedicated strdup buffer immediately before retro_load_game");

    // V12 preflight: attempt the Vulkan path exactly once to see which
    // frontend services this *binary* requests.  We reject every hardware
    // context request and do not execute any frames in this mode.
    // Then fully deinitialize/reinitialize libretro before loading Software.
    gAz111SoftwareFrames=0; gAz111HardwareMarkers=0; gAz111NullFrames=0;
    gAz111InputPolls=0; gAz111PressedSamples=0;
    gAz111LastWidth=0; gAz111LastHeight=0;
    gAz112BadGeometry=0; gAz112BadPitch=0;
    gAz112AudioBatches=0; gAz112AudioFrames=0; gAz112InputReads=0;
    gAz112FrameSamples=0; gAz112NonzeroFrameSamples=0;
    gAz112SoftwareRestarts=0;
    const unsigned v145Mask = AzaharV145BoundaryAudit();
    char v145Line[360];
    snprintf(v145Line, sizeof(v145Line),
        "V145 PARALLEL_B ABI_BOUNDARY mask=0x%02x expected=0xff v2_contract=%u callback=%u app_version=%u ownership_unassigned=%u v5_layout=%u image_sync_unassigned=%u queue_lock_unassigned=%u handles_unpublished=%u status=%s",
        v145Mask, !!(v145Mask & 1u), !!(v145Mask & 2u),
        !!(v145Mask & 4u), !!(v145Mask & 8u), !!(v145Mask & 16u),
        !!(v145Mask & 32u), !!(v145Mask & 64u), !!(v145Mask & 128u),
        v145Mask == 255u ? "PASS" : "FAIL");
    AzTrace(v145Line);
    AzTrace("V145 PARALLEL_C HANDSHAKE_GUARD stage1=REJECTED stage2=NOT_PUBLISHED gpu_frames=0 software_fallback=ENABLED");
    AzTrace("V204 BUILD_ID 3DS_AZAHAR_CORE_204_BOUNDED_ASYNC_METAL_STREAM_20261101");
    AzTrace("V204 SAFETY stock_OpenEmu=UNCHANGED renderer=V199_BITMAP GPU_stream=PRIVATE_PROBE max_inflight=2 waits=NONE");
    AzTrace("V205 BUILD_ID 3DS_AZAHAR_CORE_205_VERIFIED_ASYNC_METAL_BITMAP_HANDOFF_20261101");
    AzTrace("V206 BUILD_ID 3DS_AZAHAR_CORE_206_PARALLEL_FULL_RESOLUTION_MATRIX_20261101");
    AzTrace("V207 BUILD_ID 3DS_AZAHAR_CORE_207_OPTIONAL_REAL_HIRES_HOST_BITMAP_20261101");
    AzTrace("V208 BUILD_ID 3DS_AZAHAR_CORE_208_DELAYED_SOURCE_RECT_PITCH_SAFE_20261101");
