           "V176 INSTANCE_TEARDOWN core_app_callback_invoked=%u instance_destroyed=%u device_negotiated=0 callbacks_cleared=1 software_fallback=ENABLED",
           (unsigned)((gAzV176LiveInstanceMask & 2u)!=0),
           (unsigned)((gAzV176LiveInstanceMask & 32u)!=0));
        AzTrace(line176);
    }
    {
        char deviceCleanup[230];
        snprintf(deviceCleanup,sizeof(deviceCleanup),
           "V177 DEVICE_TEARDOWN created=%u destroyed=%u instance_destroyed=%u interface_published=0 software_fallback=ENABLED",
           (unsigned)((gAzV177LiveDeviceMask & 16u)!=0),
           (unsigned)((gAzV177LiveDeviceMask & 64u)!=0),
           (unsigned)((gAzV177LiveDeviceMask & 128u)!=0));
        AzTrace(deviceCleanup);
    }
    AzTrace("V175 REAL_V2_TEARDOWN callbacks_cleared=1 device_callbacks_invoked=PREVIOUSLY_CAPTURED_ONLY retained_after_preflight=0 software_fallback=ENABLED");
    AzTrace("V174 DISCOVERY_TEARDOWN preflight_deinitialized=1 next=SOFTWARE_FALLBACK stage1_not_reused=1");
    gAzV174DiscoveryStage1 = false;
    const bool v146Survived = gAzV113Owner.active && gAzV113Owner.instance && gAzV113Owner.device;
    AzTrace(v146Survived
        ? "V146 LANE_C CROSS_DEINIT owner_alive=1 core_deinit_complete=1 published=0 status=PASS"
        : "V146 LANE_C CROSS_DEINIT owner_alive=0 core_deinit_complete=1 status=FAIL");
    // The complete tuple remains valid across retro_deinit, but is never
    // passed to the core. Check before destroying it, not after.
    AzV149AuditOwner("AFTER_DEINIT");
    AzV150AuditOfficialOwner("AFTER_DEINIT");
    AzV151Audit("AFTER_DEINIT");
    AzTrace("V149 HANDSHAKE_GATE interface_published=0 callbacks_invoked=0 set_image=ABSENT azahar_gpu_frames=0 stage1=REJECTED");
    // Destroy device, then instance, then close loader; no GPU handles escape.
    AzV113ReleaseOwner();
    AzTrace(!gAzV113Owner.active && !gAzV113Owner.graphicsQueue &&
        !gAzV113Owner.physicalDevice && !gAzV113Owner.instanceProcAddr
        ? "V149 OWNER_RELEASE cleared_tuple=1 before_software_init=1 status=PASS"
        : "V149 OWNER_RELEASE cleared_tuple=0 status=FAIL");
    AzTrace(!gAzV113Owner.active
        ? "V146 LANE_D OWNER_RELEASE device_then_instance=1 before_software_init=1 status=PASS"
        : "V146 LANE_D OWNER_RELEASE owner_still_active=1 status=FAIL");

    AzV80ClearRequest(); // clear preflight contract before software restart
    AzTrace((!gAzV80Request.valid && !gAzV80Request.reset && !gAzV80Request.destroy)
        ? "V110 LANE_F SOFTWARE_RESTART pre_deinit=1 callback_cleared=1 status=PASS"
        : "V110 LANE_F SOFTWARE_RESTART pre_deinit=1 callback_cleared=0 status=FAIL");
    {
        const bool cleared = !gAzV80Request.valid &&
            !gAzV80Request.reset && !gAzV80Request.destroy;
        AzTrace(cleared
            ? "V82 BRIDGE LIFECYCLE cleared=1 no_dangling_callbacks=1 software_restart_safe=1"
            : "V82 BRIDGE LIFECYCLE cleared=0 ERROR: stale hardware callbacks");
    }
    gAzV12ProbeVulkan = false;
    // Re-register callbacks in case the libretro core cleared them on deinit.
    _retroSetEnvironment(AzEnvironment);
    _retroSetVideoRefresh(AzVideo);
    _retroSetAudioSample(AzAudioSample);
    _retroSetAudioSampleBatch(AzAudio);
    _retroSetInputPoll(AzInputPoll);
    _retroSetInputState(AzInputState);
    gAz111SoftwareFrames=0; gAz111HardwareMarkers=0; gAz111NullFrames=0;
    gAz111InputPolls=0; gAz111PressedSamples=0;
    ++gAz112SoftwareRestarts;
    Az111Report("SOFTWARE_RESET");
    Az112Report("SOFTWARE_RESET");
    AzTrace("V12 FALLBACK before retro_init for Software");
    _retroInit();
    AzTrace("V12 FALLBACK returned from retro_init");
    AzTrace("26 before retro_load_game");
    if (!_retroLoadGame(&game)) {
        AzTrace("27 retro_load_game returned false");
        if (error)
            *error = [NSError errorWithDomain:OEGameCoreErrorDomain
                                         code:OEGameCoreCouldNotLoadROMError
                                     userInfo:@{NSLocalizedDescriptionKey:
                                                    @"Azahar could not load this 3DS title. Encrypted titles and unsupported formats are rejected by Azahar."}];
        return NO;
    }

    AzTrace("27 retro_load_game returned true");
    AzTrace("V12 FALLBACK software ROM loaded successfully");
    AzTrace("V13 RESULT software fallback preserved; no Vulkan hardware context was advertised");
    AzTrace("V14 RESULT capability audit complete; safe software fallback retained");
    AzTrace("V15 RESULT disposable surface probe complete; no swapchain, OpenEmu presentation, or hardware context accepted");
    _gameLoaded = YES;

    struct retro_system_av_info av = {};
    AzTrace("28 before retro_get_system_av_info");
    _retroGetSystemAVInfo(&av);
    AzTrace("29 returned from retro_get_system_av_info");

    {
        char info197[220];
        snprintf(info197,sizeof(info197),
            "V197 INITIAL_AV_GEOMETRY core=%ux%u host_locked=%ux%u phase=software_loaded",
            av.geometry.base_width,av.geometry.base_height,
            _az197SessionWidth,_az197SessionHeight);
        AzTrace(info197);
    }

    Az191ApplyGraphicsOptions(self);
    _az191OptionDirty = YES;
    _az194StartupReassertFrames = 4;
    AzTrace("V194 STEREO_POST_LOAD_REARM phase=software status=ARMED");
    AzTrace("30 loadFileAtPath completed successfully");
    return YES;
}

- (void)executeFrame
{
    if (_gameLoaded && ![self isEmulationPaused]) {
        // v194: force libretro to re-check saved 3D mode once the runtime
        // renderer is active, rather than only before retro_load_game.
        // Also repeat once after three frames to cover delayed setup.
        if (_az194StartupReassertFrames) {
            const unsigned remaining = _az194StartupReassertFrames--;
            if (remaining == 4 || remaining == 1) {
                Az191ApplyGraphicsOptions(self);
                _az191OptionDirty = YES;
                char reassertLine[240];
                snprintf(reassertLine,sizeof(reassertLine),
                    "V195 GRAPHICS_REASSERT remaining=%u resolution=%ld stereo=%s depth=%ld dirty=1",
                    remaining,(long)_az191Resolution,
                    (_az191Stereo ?: @"off").UTF8String,(long)_az195Depth);
                AzTrace(reassertLine);
            }
        }
        // v190: OpenEmu schedules frame cadence itself. Avoid v189's extra
        // 16.667ms sleep, which introduced pauses on the Vulkan readback path.
        // Measure frame start gaps and per-run cost without affecting gameplay.
        const bool observing190=gAzV188HardwarePromoted;
        const auto tick190=std::chrono::steady_clock::now();
        if(observing190 && _az189PaceInitialized) {
            const auto gap190=std::chrono::duration_cast<std::chrono::microseconds>(
                tick190-_az189LastFrameStart).count();
            if(gap190>=0) {
                ++gAz190Samples;
                gAz190GapTotalUs+=(unsigned long long)gap190;
                if((unsigned long long)gap190>gAz190MaxGapUs)gAz190MaxGapUs=gap190;
                if(gap190<8000)++gAz190FastIntervals;
                if(gap190>25000)++gAz190SlowIntervals;
                if(gap190>40000)++gAz190VerySlowIntervals;
            }
        }
        if(observing190){ _az189LastFrameStart=tick190; _az189PaceInitialized=true; }
        _retroRun();
        if(observing190){
            const auto runUs190=std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now()-tick190).count();
            if(runUs190>0){
                gAz190RunTotalUs+=(unsigned long long)runUs190;
                if((unsigned long long)runUs190>gAz190MaxRunUs)gAz190MaxRunUs=runUs190;
            }
        }
        if(gAzV188HardwarePromoted && gAzV188FrameCopies &&
           (gAzV188FrameCopies%600u)==0u &&
           gAzV188FrameCopies != gAzV188LastProgressCheckpoint) {
            gAzV188LastProgressCheckpoint=gAzV188FrameCopies;
            char pace190[420];
            snprintf(pace190,sizeof(pace190),
             "V190 FRAME_TIMING frames=%u samples=%llu fast_lt8ms=%llu slow_gt25ms=%llu stalls_gt40ms=%llu mean_gap_us=%llu mean_run_us=%llu max_gap_us=%llu max_run_us=%llu governor=OPENEMU_ONLY",
             gAzV188FrameCopies,gAz190Samples,gAz190FastIntervals,
             gAz190SlowIntervals,gAz190VerySlowIntervals,
             gAz190Samples?gAz190GapTotalUs/gAz190Samples:0ull,
             gAzV188FrameCopies?gAz190RunTotalUs/gAzV188FrameCopies:0ull,
             gAz190MaxGapUs,gAz190MaxRunUs);
            AzTrace(pace190);
        }
        if(gAzV188HardwarePromoted && (gAzV188FrameCopies==60u ||
           gAzV188FrameCopies==180u || gAzV188FrameCopies==300u) &&
           gAzV188FrameCopies != gAzV188LastProgressCheckpoint) {
            gAzV188LastProgressCheckpoint=gAzV188FrameCopies;
            char run188[290];
            snprintf(run188,sizeof(run188),
              "V188 LIVE_HARDWARE_GAMEPLAY_PROGRESS frame_copies=%u sentinels=%u readbacks=%u readback_failures=%u hash_changes=%u nonzero_frames=%u status=%s",
              gAzV188FrameCopies,gAzV187HwSentinels,gAzV187HwReadbacks,
              gAzV187HwReadbackFailures,gAzV188FrameHashesChanged,gAzV188FrameNonzero,
              gAzV187HwReadbackFailures==0?"PASS":"DEGRADED");
            AzTrace(run188);
        }
    }
}

- (void)resetEmulation
{
    if (_gameLoaded)
        _retroReset();
}

- (void)azV188RetireLiveHardware
{
    if(!gAzV188HardwarePromoted)return;
    char tail188[360];
    snprintf(tail188,sizeof(tail188),
      "V188 LIVE_HARDWARE_SESSION_SUMMARY bitmap_copies=%u gpu_sentinels=%u gpu_readbacks=%u readback_failures=%u hash_changes=%u nonzero_frames=%u format=%u",
      gAzV188FrameCopies,gAzV187HwSentinels,gAzV187HwReadbacks,
      gAzV187HwReadbackFailures,gAzV188FrameHashesChanged,gAzV188FrameNonzero,gAzV188LastFormat);
    AzTrace(tail188);
    snprintf(tail188,sizeof(tail188),
      "V189 LIVE_SESSION_SUMMARY paced_frames=%u capped=%llu long_gaps=%llu sleep_us=%llu start_down=%u start_up=%u start_queries=%u start_positive=%u start_latch=%u select_down=%u select_positive=%u gpu_readback_failures=%u",
      gAzV188FrameCopies,gAz189PaceCaps,gAz189PaceStalls,gAz189PaceSleptUs,
      gAz189StartPressEvents,gAz189StartReleaseEvents,gAz189StartQueries,
      gAz189StartPositive,gAz189StartLatched,gAz189SelectPressEvents,
      gAz189SelectPositive,gAzV187HwReadbackFailures);
    AzTrace(tail188);
    snprintf(tail188,sizeof(tail188),
      "V190 FRAME_AND_INPUT_SUMMARY frames=%u very_fast=%llu slow=%llu stalls=%llu max_gap_us=%llu max_run_us=%llu axis_events=%u,%u,%u,%u extra_events=%u,%u",
      gAzV188FrameCopies,gAz190FastIntervals,gAz190SlowIntervals,
      gAz190VerySlowIntervals,gAz190MaxGapUs,gAz190MaxRunUs,
      gAz190AnalogEvents[0],gAz190AnalogEvents[1],gAz190AnalogEvents[2],
      gAz190AnalogEvents[3],gAz190ExtraEvents[0],gAz190ExtraEvents[1]);
    AzTrace(tail188);
    snprintf(tail188,sizeof(tail188),
      "V190 ANALOG_QUERY_SUMMARY left_x=%u left_y=%u right_x=%u right_y=%u",
      gAz190AnalogQueries[0],gAz190AnalogQueries[1],
      gAz190AnalogQueries[2],gAz190AnalogQueries[3]);
    AzTrace(tail188);
    if(gAzV80Request.destroy){
        AzTrace("V188 LIVE_CONTEXT_DESTROY_BEGIN");
        gAzV80Request.destroy();
        AzTrace("V188 LIVE_CONTEXT_DESTROY_RETURNED");
    }
    if(_initialized && _retroDeinit){
        AzTrace("V188 LIVE_RETRO_DEINIT_BEGIN");
        _retroDeinit();
        _initialized=NO;
        AzTrace("V188 LIVE_RETRO_DEINIT_RETURNED");
    }
    unsigned releaseMask=AzaharV187UnpublishPreflight();
    unsigned retiredMask=AzaharV178RetireAfterDeinit();
    AzV113ReleaseOwner();
    AzV80ClearRequest();
    gAzV12ProbeVulkan=false;
    gAzV187HardwareInterfaceActive=false;
    gAzV188HardwarePromoted=false;
    snprintf(tail188,sizeof(tail188),
      "V188 LIVE_HARDWARE_TEARDOWN unpublish_mask=0x%x expected=0x7 retired_mask=0x%x expected=0x1f status=%s",
      releaseMask,retiredMask,
      releaseMask==7u && retiredMask==0x1fu?"PASS":"CHECK");
    AzTrace(tail188);
}

- (void)stopEmulation
{
    {
        char host207[280];
        snprintf(host207,sizeof(host207),
            "V207 HOST_SESSION active_scale=%u pending_scale=%u physical=%ux%u frames=%u source_ge_target=%u exact_size=%u renderer=BITMAP status=%s",
            _az207ActiveHostScale,_az207PendingHostScale,
            _az197SessionWidth,_az197SessionHeight,
            _az207HostFrames,_az207RealHighResFrames,_az207ExactCopyFrames,
            _az207ActiveHostScale==1u?"COMPATIBLE":
                (_az207RealHighResFrames>0u?"HIRES_FRAMES_DELIVERED":"NO_HIRES_SOURCE"));
        AzTrace(host207);
    }
    {
      char h208[270];
      snprintf(h208,sizeof(h208),
        "V208 SESSION padded=%u buffer=%dx%d rect=%ux%u published=%u startup_frames=%u host_realloc=NONE frame_data=%s",
        (unsigned)_az208PaddedHost,(int)_videoSize.width,(int)_videoSize.height,
        _az208VisibleWidth,_az208VisibleHeight,_az208HiResPublished,
        _az208StartupFrames,_az208PaddedHost?"PITCH_SAFE_COMPACT_COPY":"COMPATIBLE");
      AzTrace(h208);
    }
    {
      char audit209[350];
      snprintf(audit209,sizeof(audit209),
        "V209 SESSION_AUDIT scale=%u stereo=%s buffer=%dx%d rect=%ux%u published=%u rowcopies=%llu rowpass=%llu rowfail=%llu native_start=%u hires=%u average_copy_us=%llu max_copy_us=%llu status=%s",
        _az207ActiveHostScale,(_az191Stereo?:@"off").UTF8String,
        (int)_videoSize.width,(int)_videoSize.height,
        _az208VisibleWidth,_az208VisibleHeight,_az208HiResPublished,
        (unsigned long long)_az209PitchCopies,
        (unsigned long long)_az209PitchPass,
        (unsigned long long)_az209PitchFail,
        _az209NativeStartCopies,_az209HiResCopies,
        (unsigned long long)(_az209PitchCopies?_az209PitchTotalUs/_az209PitchCopies:0u),
        (unsigned long long)_az209PitchMaxUs,
        _az209PitchFail==0u?"PASS":"CHECK");
      AzTrace(audit209);
    }
    {
        char summary212[320];
        snprintf(summary212, sizeof(summary212),
            "V212 SESSION_PROFILE frames=%u sampled_intervals=%llu slow_gt25ms=%llu stalls_gt40ms=%llu max_gap_us=%llu max_run_us=%llu frame_copy_avg_us=%llu frame_copy_max_us=%llu telemetry=OBSERVATIONAL",
            gAzV188FrameCopies,gAz190Samples,gAz190SlowIntervals,
            gAz190VerySlowIntervals,gAz190MaxGapUs,gAz190MaxRunUs,
            (unsigned long long)(_az209PitchCopies ? _az209PitchTotalUs/_az209PitchCopies : 0ull),
            (unsigned long long)_az209PitchMaxUs);
        AzTrace(summary212);
        snprintf(summary212, sizeof(summary212),
            "V212 DIAGNOSTIC_SUMMARY mode=%s emitted=%llu historical_filtered=%llu failures_always_retained=YES",
            Az212VerboseDiagnostics()?"VERBOSE":"CONCISE",
            gAz212LinesWritten.load(),gAz212LinesFiltered.load());
        AzTrace(summary212);
    }
    // v213 release-health gate: consolidate the counters collected by the
    // *existing* Vulkan frame handoff and pitch-safe host copy. No extra GPU
    // transfers, framebuffer reads, waits, or per-frame branches are added.
    // PASS means these measured invariants hold for this session; it is not a
    // substitute for visual compatibility, full save/restore or macOS tests.
    {
        const bool hadHardwareFrames = gAzV188HardwarePromoted && gAzV188FrameCopies > 0u;
        const bool completeReadbacks = gAzV187HwReadbacks == gAzV188FrameCopies;
        const bool validBitmapCopies = gAzV188VideoCopyFailures == 0u &&
                                       gAzV188RejectedFormats == 0u;
        const bool validPitch = _az209PitchCopies == _az209PitchPass &&
                                _az209PitchFail == 0u &&
                                _az209PitchCopies == (uint64_t)gAzV188FrameCopies;
        const bool healthy = hadHardwareFrames && completeReadbacks &&
                             gAzV187HwReadbackFailures == 0u &&
                             validBitmapCopies && validPitch;
        char health213[400];
        snprintf(health213,sizeof(health213),
            "V213 RELEASE_HEALTH frames=%u gpu_readbacks=%u readback_errors=%u copy_errors=%u bad_formats=%u pitched=%llu pitch_pass=%llu pitch_fail=%llu hw_promoted=%u status=%s",
            gAzV188FrameCopies,gAzV187HwReadbacks,gAzV187HwReadbackFailures,
            gAzV188VideoCopyFailures,gAzV188RejectedFormats,
            (unsigned long long)_az209PitchCopies,
            (unsigned long long)_az209PitchPass,
            (unsigned long long)_az209PitchFail,
            (unsigned)hadHardwareFrames, healthy?"PASS":"CHECK");
        AzTrace(health213);
    }
    if (_gameLoaded) {
        _retroUnloadGame();
        _gameLoaded = NO;
    }
    if(_az206Matrix) {
        char line206[260];
        snprintf(line206,sizeof(line206),
            "V206 SESSION_MATRIX started=%u completed=%u passed=%u failed=%u checked_pixels=%u inflight=%u host=BITMAP_V205",
            _az206Matrix->started.load(),_az206Matrix->completed.load(),
            _az206Matrix->passed.load(),_az206Matrix->failed.load(),
            _az206Matrix->checkedPixels.load(),_az206Matrix->inFlight.load());
        AzTrace(line206);
    }
    // Asynchronous callbacks retain their own state and will never touch the core.
    _az206Matrix.reset();
    if(_az205Present) {
        char line[260];
        snprintf(line,sizeof(line),"V205 SESSION_RESULT submitted=%u completed=%u verified=%u rejected=%u busy=%u visible=%u stale=%u",
            _az205Present->submitted.load(),_az205Present->finished.load(),
            _az205Present->verified.load(),_az205Present->rejected.load(),
            _az205Present->skippedBusy.load(),_az205Present->visible.load(),
            _az205Present->stale.load());
        AzTrace(line);
    }
    // Outstanding callbacks may continue against their own shared state.
    _az205Present.reset();
    [self azV188RetireLiveHardware];
    [super stopEmulation];
}

#pragma mark - Azahar display modes (v191)

- (NSArray<NSDictionary<NSString *, id> *> *)displayModes
{
    // OpenEmu owns the parent Select Display Mode menu, the built-in shader
    // submenu, and the Scale submenu. The SDK supports one level of core
    // submenus: Resolution, Stereoscopic Mode, and Stereoscopic Depth.
    static unsigned az195MenuEnumerations = 0;
    if (++az195MenuEnumerations <= 6) {
        char line[220];
        snprintf(line,sizeof(line),
            "V195 DISPLAY_MODES_ENUMERATED call=%u resolution=%ld stereo=%s depth=%ld",
            az195MenuEnumerations,(long)_az191Resolution,
            (_az191Stereo ?: @"off").UTF8String,(long)_az195Depth);
        AzTrace(line);
    }
    NSMutableArray<NSDictionary<NSString *,id> *> *resolutions = [NSMutableArray array];
    // Player-facing internal rendering quality, NOT the host pixel scale.
    // 7x and 8x were tested on Mac; benefits were negligible and 8x slowed
    // gameplay. Physical output automatically stays at native or 2x.
    for (NSInteger factor = 1; factor <= 6; ++factor) {
        NSString *name = factor == 1 ? @"1× (Native)" :
            [NSString stringWithFormat:@"%ld×",(long)factor];
        NSString *value = [NSString stringWithFormat:@"%ld",(long)factor];
        [resolutions addObject:OEDisplayMode_OptionWithStateValue(
            name, @"azaharResolution", @(_az191Resolution==factor), value)];
    }
    // Separate adjacent submenus make it clear that depth controls the
    // stereoscopic rendering mode; both live inside Select Display Mode.
    NSMutableArray<NSDictionary<NSString *,id> *> *stereoModes = [NSMutableArray array];
    [stereoModes addObjectsFromArray:@[
        OEDisplayMode_OptionWithStateValue(@"Off (2D)", @"azaharStereo",
            @([_az191Stereo isEqualToString:@"off"]), @"off"),
        OEDisplayMode_OptionWithStateValue(@"Side-by-Side (Half Resolution)", @"azaharStereo",
            @([_az191Stereo isEqualToString:@"side-by-side"]), @"side-by-side"),
        OEDisplayMode_OptionWithStateValue(@"Side-by-Side (Full Resolution)", @"azaharStereo",
            @([_az191Stereo isEqualToString:@"side-by-side-full"]), @"side-by-side-full"),
        OEDisplayMode_OptionWithStateValue(@"Anaglyph (Red/Cyan)", @"azaharStereo",
            @([_az191Stereo isEqualToString:@"anaglyph"]), @"anaglyph")
    ]];
    NSMutableArray<NSDictionary<NSString *,id> *> *stereoDepths = [NSMutableArray array];
    for (NSInteger depth = 10; depth <= 100; depth += 10) {
        NSString *name = [NSString stringWithFormat:@"%ld%%",(long)depth];
        NSString *value = [NSString stringWithFormat:@"%ld",(long)depth];
        [stereoDepths addObject:OEDisplayMode_OptionWithStateValue(
            name, @"azaharDepth", @(_az195Depth==depth), value)];
    }
    return @[
        OEDisplayMode_Submenu(@"Resolution", resolutions),
        OEDisplayMode_Submenu(@"Stereoscopic Mode", stereoModes),
        OEDisplayMode_Submenu(@"Stereoscopic Depth", stereoDepths)
    ];
}

- (void)changeDisplayWithMode:(NSString *)displayMode
{
    if (![displayMode isKindOfClass:[NSString class]]) return;
    BOOL recognized = NO;
    unsigned requestedHostScale207=_az207PendingHostScale;
    NSInteger resolution = _az191Resolution;
    NSInteger depth = _az195Depth;
    NSString *stereo = _az191Stereo ?: @"off";
    NSArray<NSString *> *res = @[@"1× (Native)",@"2×",@"3×",@"4×",@"5×",@"6×"];
    NSUInteger resIndex = [res indexOfObject:displayMode];
    if (resIndex != NSNotFound) {
        resolution = (NSInteger)resIndex + 1;
        recognized = YES;
    } else {
        NSArray<NSString *> *names = @[@"Off (2D)",@"Side-by-Side (Half Resolution)",
            @"Side-by-Side (Full Resolution)",@"Anaglyph (Red/Cyan)"];
        NSArray<NSString *> *values = @[@"off",@"side-by-side",@"side-by-side-full",@"anaglyph"];
        NSUInteger stereoIndex = [names indexOfObject:displayMode];
        if (stereoIndex != NSNotFound) {
            stereo = values[stereoIndex];
            recognized = YES;
        } else if ([displayMode hasSuffix:@"%"] && displayMode.length > 1) {
            NSString *number = [displayMode substringToIndex:displayMode.length-1];
            NSScanner *scanner = [NSScanner scannerWithString:number];
            NSInteger selected = 0;
            if ([scanner scanInteger:&selected] && scanner.isAtEnd &&
                selected >= 10 && selected <= 100 && selected % 10 == 0) {
                depth = selected;
                recognized = YES;
            }
        }
    }
    if (!recognized) return;
    if (_az191Resolution == resolution && [_az191Stereo isEqualToString:stereo] &&
        _az195Depth == depth && _az207PendingHostScale==requestedHostScale207) {
        // Preserve v194 behavior: an already-selected option can reassert
        // the Azahar runtime in case a fresh renderer started in 2D.
        Az191ApplyGraphicsOptions(self);
        _az191OptionDirty = YES;
        AzTrace("V195 DISPLAY_MODE_REASSERT selected_mode=UNCHANGED dirty=1");
        return;
    }
    _az194StartupReassertFrames = 0;
    _az191Resolution = resolution;
    _az191Stereo = stereo;
    _az195Depth = depth;
    _az207PendingHostScale=requestedHostScale207;
    if(requestedHostScale207!=_az207ActiveHostScale) {
        char pending207[220];
        snprintf(pending207,sizeof(pending207),
            "V207 HOST_OUTPUT_PENDING selected=%u active=%u apply=NEXT_GAME_LAUNCH no_live_geometry_change=YES",
            requestedHostScale207,_az207ActiveHostScale);
        AzTrace(pending207);
    }
    if (resolution > 1 && ![stereo isEqualToString:@"side-by-side-full"])
        _az193StablePresentation = YES;
    // Internal resolution and stereo options update libretro immediately.
    // The SESSION'S logical width remains locked: SBS Full can use a wider
    // logical window when the game starts with that mode selected. A live
    // stereo switch uses the existing host geometry until game restart.
    // A return to 2D in a wide session preserves aspect via pillarboxing.
    ++_az197TransitionCount;
    char mode197[280];
    snprintf(mode197,sizeof(mode197),
        "V197 LIVE_MODE_CHANGE count=%u selected=%s retained_window=%ux%u "
        "restart_for_geometry=%u",
        _az197TransitionCount,_az191Stereo.UTF8String,
        _az197SessionWidth,_az197SessionHeight,
        (unsigned)((Az197FullSelected(self) ? kAz197FullWidth : kNativeWidth)
            != _az197SessionWidth));
    AzTrace(mode197);
    Az191ApplyGraphicsOptions(self);
    if (_supportPath.length) {
        NSString *settingsFile193 = [_supportPath stringByAppendingPathComponent:@"AzaharDisplayPreferences-v193.plist"];
        NSDictionary *settings195 = @{
            @"resolution": @(resolution), @"stereo": stereo,
            @"depth": @(depth)
        };
        BOOL saved195 = [settings195 writeToFile:settingsFile193 atomically:YES];
        AzTrace(saved195?"V195 GRAPHICS_PERSIST status=SAVED":"V195 GRAPHICS_PERSIST status=FAILED");
    }
    _az191OptionDirty = YES; // libretro GET_VARIABLE_UPDATE
    char line[300];
    snprintf(line,sizeof(line),
        "V195 DISPLAY_MODE_CHANGE resolution=%ld stereo=%s depth=%ld runtime_update=PENDING",
        (long)_az191Resolution,_az191Stereo.UTF8String,(long)_az195Depth);
    AzTrace(line);
}

// OPTIONAL diagnostic lane (introduced v202): compare a full-resolution
// Vulkan-readback image against a privately owned Metal texture. This probe
// must NEVER become the OpenEmu presenter or block on a command-buffer wait.
// It runs once per real high-resolution factor; the stable bitmap path remains
// available whether the Metal device succeeds or fails.
static uint64_t Az202RowHash(const uint8_t *pixels, size_t length) {
    uint64_t hash=UINT64_C(1469598103934665603);
    for(size_t i=0;i<length;++i) hash=(hash^pixels[i])*UINT64_C(1099511628211);
    return hash;
}

- (void)az202ProbeFullResolutionPixels:(const uint8_t *)pixels
                          sourceWidth:(unsigned)width sourceHeight:(unsigned)height
                          sourcePitch:(size_t)pitch rgba:(BOOL)rgba {
    // On an unsupported device or a problematic driver, users can opt out
    // without changing the two-plugin installation or any display menu.
    const char *disabled=getenv("AZAHAR_V202_SKIP_METAL_PROBE");
    if(disabled && strcmp(disabled,"1")==0) return;
    // Skip disposable Vulkan preflight sessions; only inspect live gameplay.
    if(!_gameLoaded || !pixels || !Az191ValidFrame(width,height) ||
       pitch<(size_t)width*4u) return;
    const NSInteger requested=std::max((NSInteger)1,_az191Resolution);
    if(requested<2 || requested>6) return;
    const uint32_t bit=1u << (unsigned)(requested-1);
    if(_az202ProbeAttemptedMask & bit) return;
    const bool stereoFull=Az197FullSelected(self);
    const unsigned minimumWidth=stereoFull?kAz197FullWidth:kNativeWidth;
    const bool genuine=(uint64_t)width>=(uint64_t)minimumWidth*(unsigned)requested &&
                       (uint64_t)height>=(uint64_t)kNativeHeight*(unsigned)requested;
    if(!genuine) {
        if(!(_az202ProbeMissingMask & bit)) {
            _az202ProbeMissingMask |= bit;
            char info[250];
            snprintf(info,sizeof(info),
                "V202 SOURCE_CHECK selected=%ld source=%ux%u expected_min=%ux%u stereo=%s genuine=0 probe=DEFERRED",
                (long)requested,width,height,minimumWidth*(unsigned)requested,
                kNativeHeight*(unsigned)requested,stereoFull?"FULL":"OTHER");
            AzTrace(info);
        }
        return; // Allow a later true-resolution frame to trigger the one-shot probe.
    }
    _az202ProbeAttemptedMask |= bit; // Fail closed on allocation/command failure.
    if(!_az202ProbeDevice) _az202ProbeDevice=MTLCreateSystemDefaultDevice();
    if(_az202ProbeDevice && !_az202ProbeQueue)
        _az202ProbeQueue=[_az202ProbeDevice newCommandQueue];
    if(!_az202ProbeDevice || !_az202ProbeQueue) {
        AzTrace("V202 METAL_PROBE status=UNAVAILABLE presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    const MTLPixelFormat format=rgba?MTLPixelFormatRGBA8Unorm:MTLPixelFormatBGRA8Unorm;
    MTLTextureDescriptor *srcDesc=[MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:format width:width height:height mipmapped:NO];
    srcDesc.storageMode=MTLStorageModeShared;
    srcDesc.usage=MTLTextureUsageShaderRead;
    MTLTextureDescriptor *dstDesc=[MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:format width:width height:height mipmapped:NO];
    dstDesc.storageMode=MTLStorageModePrivate;
    dstDesc.usage=MTLTextureUsageShaderRead;
    id<MTLTexture> source=[_az202ProbeDevice newTextureWithDescriptor:srcDesc];
    id<MTLTexture> target=[_az202ProbeDevice newTextureWithDescriptor:dstDesc];
    const size_t rowBytes=(size_t)width*4u;
    if(!source || !target || rowBytes>SIZE_MAX-255u) {
        AzTrace("V202 METAL_PROBE status=ALLOC_FAIL presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    const size_t alignedRowBytes=(rowBytes+255u)&~(size_t)255u;
    if(alignedRowBytes>SIZE_MAX/3u) return;
    id<MTLBuffer> verification=[_az202ProbeDevice newBufferWithLength:alignedRowBytes*3u
        options:MTLResourceStorageModeShared];
    if(!verification) {
        AzTrace("V202 METAL_PROBE status=VERIFY_ALLOC_FAIL presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    // replaceRegion copies all true high-res source pixels without filtering.
    [source replaceRegion:MTLRegionMake2D(0,0,width,height) mipmapLevel:0
              withBytes:pixels bytesPerRow:pitch];
    const unsigned rows[3]={0u,height/2u,height-1u};
    const uint64_t hash0=Az202RowHash(pixels+(size_t)rows[0]*pitch,rowBytes);
    const uint64_t hash1=Az202RowHash(pixels+(size_t)rows[1]*pitch,rowBytes);
    const uint64_t hash2=Az202RowHash(pixels+(size_t)rows[2]*pitch,rowBytes);
    id<MTLCommandBuffer> command=[_az202ProbeQueue commandBuffer];
    id<MTLBlitCommandEncoder> blit=[command blitCommandEncoder];
    if(!command || !blit) {
        AzTrace("V202 METAL_PROBE status=COMMAND_FAIL presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    [blit copyFromTexture:source sourceSlice:0 sourceLevel:0
            sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(width,height,1)
               toTexture:target destinationSlice:0 destinationLevel:0
       destinationOrigin:MTLOriginMake(0,0,0)];
    for(unsigned i=0;i<3u;++i) {
        [blit copyFromTexture:target sourceSlice:0 sourceLevel:0
                sourceOrigin:MTLOriginMake(0,rows[i],0)
                  sourceSize:MTLSizeMake(width,1,1)
                    toBuffer:verification destinationOffset:alignedRowBytes*i
          destinationBytesPerRow:alignedRowBytes destinationBytesPerImage:alignedRowBytes
                       options:MTLBlitOptionNone];
    }
    [blit endEncoding];
    // Capture GPU resources explicitly until callback completion. No self/core
    // reference, no wait, and no writes to the host-owned video bitmap.
    id<MTLTexture> retainedSource=source;
    id<MTLTexture> retainedTarget=target;
    id<MTLBuffer> retainedVerify=verification;
    [command addCompletedHandler:^(id<MTLCommandBuffer> completed) {
        (void)retainedSource; (void)retainedTarget;
        const bool completedOK=completed.status==MTLCommandBufferStatusCompleted;
        const uint8_t *result=(const uint8_t *)retainedVerify.contents;
        const bool pixelsOK=completedOK && result &&
            Az202RowHash(result,rowBytes)==hash0 &&
            Az202RowHash(result+alignedRowBytes,rowBytes)==hash1 &&
            Az202RowHash(result+alignedRowBytes*2u,rowBytes)==hash2;
        char line[320];
        snprintf(line,sizeof(line),
            "V202 METAL_TRANSFER selected=%ld source=%ux%u bytes=%zu gpu_status=%lu sampled_rows=3 pixel_exact=%u presenter=V199_BITMAP_UNCHANGED status=%s",
            (long)requested,width,height,(size_t)width*(size_t)height*4u,
            (unsigned long)completed.status,(unsigned)pixelsOK,
            pixelsOK?"PASS":"FAIL");
        AzTrace(line);
    }];
    char submitted[230];
    snprintf(submitted,sizeof(submitted),
        "V202 METAL_SUBMIT selected=%ld source=%ux%u full_source=YES submitted=1 no_wait=YES",
        (long)requested,width,height);
    AzTrace(submitted);
    [command commit]; // No waitUntilCompleted: never gate gameplay on this probe.
}


// v203: independent quality/geometry check for final Metal scaling.
// Azahar continues rendering at genuine internal resolution. The *diagnostic*
// Metal compute encoder samples the entire source to a native-sized private
// texture, then copies that texture to a private verification buffer. OpenEmu
// never sees either texture. No thread waits for the GPU; no source pointer is
// retained past this function. A CPU bilinear reference at 25 pixel positions
// tests content, orientation, geometry and both byte-channel formats.
static unsigned Az203ProbeCoord(unsigned size, unsigned index) {
    switch(index) {
        case 0: return 0u;
        case 1: return size/4u;
        case 2: return size/2u;
        case 3: return 3u*size/4u;
        default: return size-1u;
    }
}

static void Az203CPUReferenceSample(const uint8_t *pixels, unsigned sw, unsigned sh,
                                    size_t pitch, unsigned dw, unsigned dh,
                                    unsigned dx, unsigned dy, uint8_t out[4]) {
    const double fx=((double)dx+0.5)*(double)sw/(double)dw-0.5;
    const double fy=((double)dy+0.5)*(double)sh/(double)dh-0.5;
    const int x0=(int)floor(fx), y0=(int)floor(fy);
    const double tx=fx-floor(fx), ty=fy-floor(fy);
    const int sx[2]={std::max(0,std::min((int)sw-1,x0)),
                     std::max(0,std::min((int)sw-1,x0+1))};
    const int sy[2]={std::max(0,std::min((int)sh-1,y0)),
                     std::max(0,std::min((int)sh-1,y0+1))};
    for(unsigned ch=0;ch<4;ch++) {
        const double top=(double)pixels[(size_t)sy[0]*pitch+(size_t)sx[0]*4u+ch]*(1.0-tx)
                         +(double)pixels[(size_t)sy[0]*pitch+(size_t)sx[1]*4u+ch]*tx;
        const double bot=(double)pixels[(size_t)sy[1]*pitch+(size_t)sx[0]*4u+ch]*(1.0-tx)
                         +(double)pixels[(size_t)sy[1]*pitch+(size_t)sx[1]*4u+ch]*tx;
        out[ch]=(uint8_t)std::max(0,std::min(255,(int)lround(top*(1.0-ty)+bot*ty)));
    }
}

- (void)az203ProbeMetalComposition:(const uint8_t *)pixels
                      sourceWidth:(unsigned)width sourceHeight:(unsigned)height
                      sourcePitch:(size_t)pitch rgba:(BOOL)rgba {
    const char *disable=getenv("AZAHAR_V203_SKIP_METAL_PROBE");
    if(disable && strcmp(disable,"1")==0) return;
    if(!_gameLoaded || !pixels || !Az191ValidFrame(width,height) ||
       pitch<(size_t)width*4u) return;
    const NSInteger selected=std::max((NSInteger)1,_az191Resolution);
    if(selected<2 || selected>6) return;
    const uint32_t bit=1u<<(unsigned)(selected-1);
    if(_az203AttemptedMask & bit) return;
    const BOOL fullStereo=Az197FullSelected(self);
    const unsigned dw=fullStereo?kAz197FullWidth:kNativeWidth;
    const unsigned dh=kNativeHeight;
    if((uint64_t)width<(uint64_t)dw*(unsigned)selected ||
       (uint64_t)height<(uint64_t)dh*(unsigned)selected) {
        if(!(_az203MissingMask & bit)) {
            _az203MissingMask |= bit;
            char line[250];
            snprintf(line,sizeof(line),
                "V203 SOURCE_CHECK selected=%ld source=%ux%u min=%ux%u genuine=0 deferred=1",
                (long)selected,width,height,dw*(unsigned)selected,dh*(unsigned)selected);
            AzTrace(line);
        }
        return;
    }
    _az203AttemptedMask |= bit; // Fail closed, never retry on unsafe allocation or driver.
    if(!_az202ProbeDevice) _az202ProbeDevice=MTLCreateSystemDefaultDevice();
    if(_az202ProbeDevice && !_az202ProbeQueue)
        _az202ProbeQueue=[_az202ProbeDevice newCommandQueue];
    if(!_az202ProbeDevice || !_az202ProbeQueue) {
        AzTrace("V203 METAL_COMPOSE status=UNAVAILABLE presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    if(!_az203FitPipeline) {
        // Compile only inside the plugin; no .metallib, application change, or new installation.
        NSString *code=@"#include <metal_stdlib>\n"
            @"using namespace metal;\n"
            @"kernel void az203_fit(texture2d<float, access::sample> src [[texture(0)]],\n"
            @"texture2d<float, access::write> dst [[texture(1)]],\n"
            @"uint2 xy [[thread_position_in_grid]]) {\n"
            @" if (xy.x >= dst.get_width() || xy.y >= dst.get_height()) return;\n"
            @" constexpr sampler s(coord::normalized, address::clamp_to_edge, filter::linear);\n"
            @" float2 uv=(float2(xy)+0.5)/float2(dst.get_width(),dst.get_height());\n"
            @" dst.write(src.sample(s,uv),xy);\n"
            @"}\n";
        NSError *err=nil;
        id<MTLLibrary> lib=[_az202ProbeDevice newLibraryWithSource:code options:nil error:&err];
        id<MTLFunction> fn=[lib newFunctionWithName:@"az203_fit"];
        if(fn) _az203FitPipeline=[_az202ProbeDevice newComputePipelineStateWithFunction:fn error:&err];
        if(!_az203FitPipeline) {
            AzTrace("V203 METAL_COMPOSE status=SHADER_COMPILE_FAILED presenter=V199_BITMAP_UNCHANGED");
            return;
        }
    }
    const MTLPixelFormat format=rgba?MTLPixelFormatRGBA8Unorm:MTLPixelFormatBGRA8Unorm;
    MTLTextureDescriptor *sd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format
                              width:width height:height mipmapped:NO];
    sd.storageMode=MTLStorageModeShared;
    sd.usage=MTLTextureUsageShaderRead;
    MTLTextureDescriptor *dd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format
                              width:dw height:dh mipmapped:NO];
    dd.storageMode=MTLStorageModePrivate;
    dd.usage=MTLTextureUsageShaderWrite | MTLTextureUsageShaderRead;
    id<MTLTexture> source=[_az202ProbeDevice newTextureWithDescriptor:sd];
    id<MTLTexture> destination=[_az202ProbeDevice newTextureWithDescriptor:dd];
    const size_t row=(size_t)dw*4u;
    const size_t aligned=(row+255u)&~(size_t)255u;
    id<MTLBuffer> output=[_az202ProbeDevice newBufferWithLength:aligned*(size_t)dh
                                           options:MTLResourceStorageModeShared];
    if(!source || !destination || !output) {
        AzTrace("V203 METAL_COMPOSE status=ALLOC_FAIL presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    [source replaceRegion:MTLRegionMake2D(0,0,width,height)
            mipmapLevel:0 withBytes:pixels bytesPerRow:pitch];
    uint8_t expected[100]={0};
    for(unsigned y=0;y<5;y++) for(unsigned x=0;x<5;x++)
        Az203CPUReferenceSample(pixels,width,height,pitch,dw,dh,
                               Az203ProbeCoord(dw,x),Az203ProbeCoord(dh,y),
                               expected+(y*5u+x)*4u);
    NSData *reference=[NSData dataWithBytes:expected length:sizeof(expected)];
    id<MTLCommandBuffer> cb=[_az202ProbeQueue commandBuffer];
    id<MTLComputeCommandEncoder> compute=[cb computeCommandEncoder];
    if(!cb || !compute) {
        AzTrace("V203 METAL_COMPOSE status=ENCODER_FAIL presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    [compute setComputePipelineState:_az203FitPipeline];
    [compute setTexture:source atIndex:0];
    [compute setTexture:destination atIndex:1];
    const MTLSize thread=MTLSizeMake(8u,8u,1u);
    [compute dispatchThreadgroups:MTLSizeMake((dw+7u)/8u,(dh+7u)/8u,1u)
            threadsPerThreadgroup:thread];
    [compute endEncoding];
    id<MTLBlitCommandEncoder> blit=[cb blitCommandEncoder];
    if(!blit) {
        AzTrace("V203 METAL_COMPOSE status=BLIT_ENCODER_FAIL presenter=V199_BITMAP_UNCHANGED");
        return;
    }
    [blit copyFromTexture:destination sourceSlice:0 sourceLevel:0
        sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(dw,dh,1)
        toBuffer:output destinationOffset:0 destinationBytesPerRow:aligned
        destinationBytesPerImage:aligned*(size_t)dh options:MTLBlitOptionNone];
    [blit endEncoding];
    // Keep only one-shot immutable diagnostics and Metal resources alive in the
    // completion handler. Do NOT capture the core, host bitmap, or readback pointer.
    id<MTLTexture> keptSrc=source;
    id<MTLTexture> keptDst=destination;
    id<MTLBuffer> keptOutput=output;
    NSData *keptReference=reference;
    [cb addCompletedHandler:^(id<MTLCommandBuffer> finished) {
        (void)keptSrc; (void)keptDst;
        const BOOL done=finished.status==MTLCommandBufferStatusCompleted;
        const uint8_t *actual=(const uint8_t *)keptOutput.contents;
        const uint8_t *gold=(const uint8_t *)keptReference.bytes;
        unsigned maxError=0, passed=0;
        if(done && actual && gold) {
            for(unsigned y=0;y<5;y++) for(unsigned x=0;x<5;x++) {
                BOOL ok=YES;
                const uint8_t *a=actual+(size_t)Az203ProbeCoord(dh,y)*aligned+
                                 (size_t)Az203ProbeCoord(dw,x)*4u;
                const uint8_t *b=gold+(y*5u+x)*4u;
                for(unsigned ch=0;ch<4;ch++) {
                    const unsigned delta=(unsigned)abs((int)a[ch]-(int)b[ch]);
                    maxError=std::max(maxError,delta);
                    if(delta>2u) ok=NO; // 8-bit linear-sampling hardware rounding allowance.
                }
                passed+=(unsigned)ok;
            }
        }
        const BOOL good=done && passed==25u;
        char line[350];
        snprintf(line,sizeof(line),
            "V203 METAL_COMPOSE selected=%ld source=%ux%u destination=%ux%u "
            "points=%u/25 max_error=%u gpu_status=%lu scale=GPU_LINEAR "
            "visible_presenter=V199_BITMAP_UNCHANGED status=%s",
            (long)selected,width,height,dw,dh,passed,maxError,
            (unsigned long)finished.status,good?"PASS":"FAIL");
        AzTrace(line);
    }];
    char line[260];
    snprintf(line,sizeof(line),
        "V203 METAL_COMPOSE_SUBMIT selected=%ld source=%ux%u destination=%ux%u "
        "genuine=1 no_wait=YES presenter=V199_BITMAP_UNCHANGED",
        (long)selected,width,height,dw,dh);
    AzTrace(line);
    [cb commit]; // Never wait for the GPU on the emulator thread.
}


// v204: prove consecutive Metal compositions instead of only the one-shot
// v203 sample. The source is the actual high-resolution Azahar frame. Each
// command buffer owns its own textures and verification data. A 2-buffer
// atomic in-flight limit is tested non-blockingly. Results never write to
// OpenEmu's texture, bitmap, view or game state. The renderer remains bitmap.
- (void)az204ProbeContinuousMetalComposition:(const uint8_t *)pixels
                      sourceWidth:(unsigned)width sourceHeight:(unsigned)height
                      sourcePitch:(size_t)pitch rgba:(BOOL)rgba {
    const char *skip=getenv("AZAHAR_V204_SKIP_METAL_STREAM");
    if(skip && strcmp(skip,"1")==0) return;
    if(!_gameLoaded || !pixels || !Az191ValidFrame(width,height) ||
       pitch < (size_t)width*4u) return;
    const NSInteger factor=std::max((NSInteger)1,_az191Resolution);
    if(factor<2 || factor>6) return;
    const BOOL wide=Az197FullSelected(self);
    const unsigned dw=wide?kAz197FullWidth:kNativeWidth;
    const unsigned dh=kNativeHeight;
    const unsigned sw=(unsigned)factor*dw, sh=(unsigned)factor*dh;
    const unsigned idx=(unsigned)(factor-1)+(wide?6u:0u);
    if(!_az204Tracker) _az204Tracker=std::make_shared<Az204StreamTracker>();
    const std::shared_ptr<Az204StreamTracker> state=_az204Tracker;
    if(width!=sw || height!=sh) {
        if(state->missing_reported[idx].fetch_add(1)==0) {
            char msg[230];
            snprintf(msg,sizeof(msg),
              "V204 STREAM_SOURCE selected=%ld full_stereo=%u actual=%ux%u required=%ux%u status=SKIP",
              (long)factor,(unsigned)wide,width,height,sw,sh);
            AzTrace(msg);
        }
        return;
    }
    // This gate deliberately requires the already-tested v203 shader.
    if(!_az202ProbeDevice || !_az202ProbeQueue || !_az203FitPipeline) return;
    static constexpr unsigned kStreamFrames=12;
    if(state->submissions[idx].load(std::memory_order_acquire)>=kStreamFrames) return;
    unsigned busy=state->inflight.load(std::memory_order_acquire);
    while(busy<2 && !state->inflight.compare_exchange_weak(
            busy,busy+1,std::memory_order_acq_rel,std::memory_order_acquire)) {}
    if(busy>=2) {
        state->busy_skips[idx].fetch_add(1,std::memory_order_relaxed);
        return;
    }
    // Recheck after reserving a slot, protecting against reentrant callbacks.
    if(state->submissions[idx].load(std::memory_order_acquire)>=kStreamFrames) {
        state->inflight.fetch_sub(1,std::memory_order_release);
        return;
    }
    const MTLPixelFormat format=rgba?MTLPixelFormatRGBA8Unorm:MTLPixelFormatBGRA8Unorm;
    MTLTextureDescriptor *sd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format
                              width:width height:height mipmapped:NO];
    sd.storageMode=MTLStorageModeShared; sd.usage=MTLTextureUsageShaderRead;
    MTLTextureDescriptor *dd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format
                              width:dw height:dh mipmapped:NO];
    dd.storageMode=MTLStorageModePrivate;
    dd.usage=MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    id<MTLTexture> source=[_az202ProbeDevice newTextureWithDescriptor:sd];
    id<MTLTexture> dest=[_az202ProbeDevice newTextureWithDescriptor:dd];
    const size_t row=(size_t)dw*4u;
    const size_t aligned=(row+255u)&~(size_t)255u;
    id<MTLBuffer> output=[_az202ProbeDevice newBufferWithLength:aligned*(size_t)dh
                                            options:MTLResourceStorageModeShared];
    if(!source || !dest || !output) {
        state->inflight.fetch_sub(1,std::memory_order_release);
        AzTrace("V204 STREAM status=ALLOC_FAIL bitmap_unaffected=YES");
        return;
    }
    [source replaceRegion:MTLRegionMake2D(0,0,width,height)
            mipmapLevel:0 withBytes:pixels bytesPerRow:pitch];
    // C++ std::array is captured by value into the asynchronous block.
    // A C array is not capturable; stack pointers would dangle.
    const std::array<unsigned,5> xs={0u,dw/4u,dw/2u,3u*dw/4u,dw-1u};
    const std::array<unsigned,5> ys={0u,dh/4u,dh/2u,3u*dh/4u,dh-1u};
    uint8_t expected[100];
    for(unsigned y=0;y<5;y++) for(unsigned x=0;x<5;x++)
        Az203CPUReferenceSample(pixels,width,height,pitch,dw,dh,xs[x],ys[y],
                               expected+(y*5u+x)*4u);
    NSData *reference=[NSData dataWithBytes:expected length:sizeof(expected)];
    id<MTLCommandBuffer> cb=[_az202ProbeQueue commandBuffer];
    id<MTLComputeCommandEncoder> compute=[cb computeCommandEncoder];
    if(!cb || !compute) {
        state->inflight.fetch_sub(1,std::memory_order_release);
        AzTrace("V204 STREAM status=ENCODER_FAIL bitmap_unaffected=YES");
        return;
    }
    [compute setComputePipelineState:_az203FitPipeline];
    [compute setTexture:source atIndex:0];
    [compute setTexture:dest atIndex:1];
    [compute dispatchThreadgroups:MTLSizeMake((dw+7u)/8u,(dh+7u)/8u,1u)
            threadsPerThreadgroup:MTLSizeMake(8u,8u,1u)];
    [compute endEncoding];
    id<MTLBlitCommandEncoder> blit=[cb blitCommandEncoder];
    if(!blit) {
        state->inflight.fetch_sub(1,std::memory_order_release);
        AzTrace("V204 STREAM status=BLIT_FAIL bitmap_unaffected=YES");
        return;
    }
    [blit copyFromTexture:dest sourceSlice:0 sourceLevel:0
        sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(dw,dh,1)
        toBuffer:output destinationOffset:0 destinationBytesPerRow:aligned
        destinationBytesPerImage:aligned*(size_t)dh options:MTLBlitOptionNone];
    [blit endEncoding];
    const unsigned sequence=state->submissions[idx].fetch_add(1,std::memory_order_acq_rel)+1;
    if(sequence==1) {
        char line[270];
        snprintf(line,sizeof(line),
            "V204 STREAM_BEGIN selected=%ld source=%ux%u native=%ux%u full_stereo=%u frames_target=%u max_inflight=2 no_wait=YES",
            (long)factor,width,height,dw,dh,(unsigned)wide,kStreamFrames);
        AzTrace(line);
    }
    id<MTLTexture> keptSource=source, keptDest=dest;
    id<MTLBuffer> keptOutput=output;
    NSData *keptReference=reference;
    [cb addCompletedHandler:^(id<MTLCommandBuffer> finished) {
        (void)keptSource; (void)keptDest;
        const BOOL completed=finished.status==MTLCommandBufferStatusCompleted;
        const uint8_t *a=(const uint8_t *)keptOutput.contents;
        const uint8_t *b=(const uint8_t *)keptReference.bytes;
        unsigned passed=0,maxError=0;
        if(completed && a && b) {
            for(unsigned y=0;y<5;y++) for(unsigned x=0;x<5;x++) {
                const uint8_t *got=a+(size_t)ys[y]*aligned+(size_t)xs[x]*4u;
                const uint8_t *want=b+(size_t)(y*5u+x)*4u;
                BOOL good=YES;
                for(unsigned ch=0;ch<4;ch++) {
                    const unsigned delta=(unsigned)abs((int)got[ch]-(int)want[ch]);
                    maxError=std::max(maxError,delta);
                    if(delta>2u) good=NO;
                }
                passed+=(unsigned)good;
            }
        }
        unsigned observed=state->max_errors[idx].load(std::memory_order_acquire);
        while(observed<maxError && !state->max_errors[idx].compare_exchange_weak(
                observed,maxError,std::memory_order_acq_rel,std::memory_order_acquire)) {}
        if(completed && passed==25u) state->passes[idx].fetch_add(1);
        else state->failures[idx].fetch_add(1);
        const unsigned received=state->completions[idx].fetch_add(1)+1;
        state->inflight.fetch_sub(1,std::memory_order_release);
        if(received==kStreamFrames) {
            const unsigned total=state->submissions[idx].load();
            const unsigned pass=state->passes[idx].load();
            const unsigned failed=state->failures[idx].load();
            const unsigned drop=state->busy_skips[idx].load();
            char msg[320];
            snprintf(msg,sizeof(msg),
              "V204 STREAM_RESULT selected=%ld full_stereo=%u submitted=%u completed=%u pass=%u fail=%u busy_skips=%u max_error=%u pixel_points=%u/%u wait=NONE bitmap_unaffected=YES status=%s",
              (long)factor,(unsigned)wide,total,received,pass,failed,drop,
              state->max_errors[idx].load(),pass*25u,kStreamFrames*25u,
              (total==kStreamFrames && pass==kStreamFrames && failed==0)?"PASS":"FAIL");
            AzTrace(msg);
        }
    }];
    [cb commit]; // No wait. Never touch host-visible pixels from completion callback.
}


// v206: Use one genuine Azahar frame to test *several* physical GPU output
// dimensions in the same command buffer: native 1x, intermediate 2x/3x,
// and a pixel-preserving full-source-size copy. None is shown to OpenEmu.
// Only 25 sampled pixels per output are copied to a compact verification buffer.
// This establishes that the core can retain genuine high-res content in Metal;
// it does NOT claim that the host will display all these pixels yet.
- (void)az206ProbeOutputMatrix:(const uint8_t *)pixels
    sourceWidth:(unsigned)width sourceHeight:(unsigned)height
    sourcePitch:(size_t)pitch rgba:(BOOL)rgba {
    const char *off=getenv("AZAHAR_V206_SKIP_MATRIX");
    if(off && strcmp(off,"1")==0) return;
    if(!_gameLoaded || !pixels || !Az191ValidFrame(width,height) ||
       pitch<(size_t)width*4u || !_az202ProbeDevice ||
       !_az202ProbeQueue || !_az203FitPipeline) return;
    const NSInteger factor=std::max((NSInteger)1,_az191Resolution);
    if(factor<2 || factor>6) return;
    unsigned stereo=0u;
    if([_az191Stereo isEqualToString:@"side-by-side"]) stereo=1u;
    else if([_az191Stereo isEqualToString:@"side-by-side-full"]) stereo=2u;
    else if([_az191Stereo isEqualToString:@"anaglyph"]) stereo=3u;
    const unsigned nativeW=(stereo==2u)?800u:400u, nativeH=480u;
    const unsigned requested=(unsigned)factor;
    if(width!=nativeW*requested || height!=nativeH*requested) return;
    const unsigned slot=(requested-1u)+6u*stereo;
    const uint32_t flag=1u<<slot;
    if(_az206AttemptedMask&flag) return;
    if(!_az206Matrix) _az206Matrix=std::make_shared<Az206MatrixTracker>();
    const std::shared_ptr<Az206MatrixTracker> state=_az206Matrix;
    unsigned expected=0u;
    if(!state->inFlight.compare_exchange_strong(expected,1u)) {
        if(!(_az206BusyReportedMask&flag)) {
            _az206BusyReportedMask|=flag;
            AzTrace("V206 MATRIX_DEFER reason=PRIVATE_GPU_BUSY fallback=V205_BITMAP");
        }
        return; // Reattempt automatically after preceding GPU command finishes.
    }

    // Every target is at or below the actual physical source resolution.
    const std::array<unsigned,4> proposed={1u,2u,3u,requested};
    std::array<unsigned,4> scales={};
    std::array<unsigned,4> widths={};
    std::array<unsigned,4> heights={};
    unsigned count=0u;
    for(unsigned candidate:proposed) {
        if(candidate>requested) continue;
        bool seen=false;
        for(unsigned j=0;j<count;j++) if(scales[j]==candidate) seen=true;
        if(seen) continue;
        scales[count]=candidate; widths[count]=nativeW*candidate;
        heights[count]=nativeH*candidate;
        count++;
    }
    if(count<2u) { state->inFlight.store(0); return; }
    const size_t sourceBytes=(size_t)width*height*4u;
    size_t budget=sourceBytes;
    for(unsigned i=0;i<count;i++) budget+=(size_t)widths[i]*heights[i]*4u;
    // One-shot probe only. Avoid runaway allocations on unexpected geometry.
    if(budget>(size_t)192u*1024u*1024u) {
        AzTrace("V206 MATRIX_SKIP reason=PRIVATE_MEMORY_BUDGET bitmap_unchanged=YES");
        state->inFlight.store(0); _az206AttemptedMask|=flag; return;
    }
    const MTLPixelFormat format=rgba?MTLPixelFormatRGBA8Unorm:MTLPixelFormatBGRA8Unorm;
    MTLTextureDescriptor *sd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format
        width:width height:height mipmapped:NO];
    sd.storageMode=MTLStorageModeShared; sd.usage=MTLTextureUsageShaderRead;
    id<MTLTexture> src=[_az202ProbeDevice newTextureWithDescriptor:sd];
    NSMutableArray<id<MTLTexture>> *destinations=[NSMutableArray arrayWithCapacity:count];
    NSMutableArray<id<MTLBuffer>> *smallReadbacks=[NSMutableArray arrayWithCapacity:count];
    NSMutableArray<NSData *> *references=[NSMutableArray arrayWithCapacity:count];
    bool allocated=(src!=nil);
    constexpr size_t kSamplePitch=256u, kSampleCount=25u;
    for(unsigned i=0;i<count && allocated;i++) {
        MTLTextureDescriptor *dd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format
            width:widths[i] height:heights[i] mipmapped:NO];
        dd.storageMode=MTLStorageModePrivate;
        dd.usage=MTLTextureUsageShaderWrite|MTLTextureUsageShaderRead;
        id<MTLTexture> target=[_az202ProbeDevice newTextureWithDescriptor:dd];
        id<MTLBuffer> small=[_az202ProbeDevice
            newBufferWithLength:kSamplePitch*kSampleCount
            options:MTLResourceStorageModeShared];
        if(!target || !small) { allocated=false; break; }
        uint8_t cpu[100];
        for(unsigned y=0;y<5;y++) for(unsigned x=0;x<5;x++)
            Az203CPUReferenceSample(pixels,width,height,pitch,widths[i],heights[i],
                Az203ProbeCoord(widths[i],x),Az203ProbeCoord(heights[i],y),
                cpu+4u*(y*5u+x));
        [destinations addObject:target];
        [smallReadbacks addObject:small];
        [references addObject:[NSData dataWithBytes:cpu length:sizeof(cpu)]];
    }
    if(!allocated) {
        state->inFlight.store(0); _az206AttemptedMask|=flag;
        AzTrace("V206 MATRIX_SKIP reason=PRIVATE_ALLOCATION_FAILED bitmap_unchanged=YES");
        return;
    }
    [src replaceRegion:MTLRegionMake2D(0,0,width,height) mipmapLevel:0
        withBytes:pixels bytesPerRow:pitch];
    id<MTLCommandBuffer> command=[_az202ProbeQueue commandBuffer];
    if(!command) {
        state->inFlight.store(0); _az206AttemptedMask|=flag;
        AzTrace("V206 MATRIX_SKIP reason=COMMAND_BUFFER_FAILED bitmap_unchanged=YES");
        return;
    }
    bool encoded=true;
    for(unsigned i=0;i<count && encoded;i++) {
        id<MTLTexture> target=destinations[i];
        if(scales[i]==requested) {
            // Important independent lane: no scaling at all. Full 6x pixels
            // remain in an equally sized Metal texture.
            id<MTLBlitCommandEncoder> b=[command blitCommandEncoder];
            if(!b) { encoded=false; break; }
            [b copyFromTexture:src sourceSlice:0 sourceLevel:0
                sourceOrigin:MTLOriginMake(0,0,0)
                sourceSize:MTLSizeMake(width,height,1)
                toTexture:target destinationSlice:0 destinationLevel:0
                destinationOrigin:MTLOriginMake(0,0,0)];
            [b endEncoding];
        } else {
            id<MTLComputeCommandEncoder> c=[command computeCommandEncoder];
            if(!c) { encoded=false; break; }
            [c setComputePipelineState:_az203FitPipeline];
            [c setTexture:src atIndex:0]; [c setTexture:target atIndex:1];
            [c dispatchThreadgroups:MTLSizeMake((widths[i]+7u)/8u,(heights[i]+7u)/8u,1u)
                threadsPerThreadgroup:MTLSizeMake(8u,8u,1u)];
            [c endEncoding];
        }
        id<MTLBlitCommandEncoder> b=[command blitCommandEncoder];
        if(!b) { encoded=false; break; }
        id<MTLBuffer> small=smallReadbacks[i];
        for(unsigned y=0;y<5;y++) for(unsigned x=0;x<5;x++) {
            const unsigned n=y*5u+x;
            [b copyFromTexture:target sourceSlice:0 sourceLevel:0
                sourceOrigin:MTLOriginMake(Az203ProbeCoord(widths[i],x),
                                           Az203ProbeCoord(heights[i],y),0)
                sourceSize:MTLSizeMake(1,1,1)
                toBuffer:small destinationOffset:kSamplePitch*(size_t)n
                destinationBytesPerRow:kSamplePitch
                destinationBytesPerImage:kSamplePitch
                options:MTLBlitOptionNone];
        }
        [b endEncoding];
    }
    _az206AttemptedMask|=flag;
    if(!encoded) {
        state->inFlight.store(0);
        AzTrace("V206 MATRIX_SKIP reason=ENCODE_FAILED bitmap_unchanged=YES");
        return;
    }
    state->started.fetch_add(1);
    const auto start=std::chrono::steady_clock::now();
    // Retain immutable C++ geometry and all ObjC Metal objects by value; no
    // core/self capture or potentially dangling C-array capture.
    id<MTLTexture> keptSource=src;
    NSArray<id<MTLTexture>> *keptTargets=[destinations copy];
    NSArray<id<MTLBuffer>> *keptReadbacks=[smallReadbacks copy];
    NSArray<NSData *> *keptReferences=[references copy];
    [command addCompletedHandler:^(id<MTLCommandBuffer> finished) {
        (void)keptSource; (void)keptTargets;
        const bool gpuOK=finished.status==MTLCommandBufferStatusCompleted;
        unsigned totalGood=0, totalTested=0, maxError=0;
        for(unsigned i=0;i<count;i++) {
            id<MTLBuffer> small=keptReadbacks[i];
            NSData *ref=keptReferences[i];
            const uint8_t *got=(const uint8_t *)small.contents;
            const uint8_t *want=(const uint8_t *)ref.bytes;
            unsigned good=0;
            if(gpuOK && got && want) for(unsigned n=0;n<25;n++) {
                bool same=true;
                for(unsigned channel=0;channel<4;channel++) {
                    const int err=abs((int)got[(size_t)n*kSamplePitch+channel]
                                     -(int)want[4u*n+channel]);
                    maxError=std::max(maxError,(unsigned)err);
                    if(err>(scales[i]==requested?0:2)) same=false;
                }
                good+=(unsigned)same;
            }
            totalGood+=good; totalTested+=25u;
            char detail[260];
            snprintf(detail,sizeof(detail),
                "V206 GPU_MATRIX selected=%u stereo=%u texture_scale=%u output=%ux%u samples=%u/25 full_pixels_kept=%u status=%s",
                requested,stereo,scales[i],widths[i],heights[i],good,
                (unsigned)(scales[i]==requested),good==25u?"PASS":"FAIL");
            AzTrace(detail);
        }
        const bool pass=gpuOK && totalGood==totalTested;
        state->completed.fetch_add(1);
        if(pass) state->passed.fetch_add(1); else state->failed.fetch_add(1);
        state->checkedPixels.fetch_add(totalGood);
        state->inFlight.store(0);
        const auto elapsed=std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now()-start).count();
        char msg[320];
        snprintf(msg,sizeof(msg),
            "V206 MATRIX_RESULT selected=%u stereo=%u full_source=%ux%u distinct_outputs=%u samples=%u/%u max_error=%u elapsed_us=%lld gpu_status=%lu host_bitmap=UNCHANGED gpu_wait=NONE status=%s",
            requested,stereo,width,height,count,totalGood,totalTested,maxError,
            (long long)elapsed,(unsigned long)finished.status,pass?"PASS":"FAIL");
        AzTrace(msg);
    }];
    char begin[280];
    snprintf(begin,sizeof(begin),
        "V206 MATRIX_BEGIN selected=%u stereo=%u true_source=%ux%u targets=%u private_bytes=%zu host_screen=%ux%u nonblocking=YES",
        requested,stereo,width,height,count,budget,nativeW,nativeH);
    AzTrace(begin);
    [command commit]; // NEVER synchronize, wait, or touch the host bitmap.
}

// v205: the first live Metal handoff, without switching the OpenEmu renderer.
// The v199 bitmap frame is ALWAYS computed before this method is invoked.
// Only completed, pixel-verified work can overwrite that bitmap on a later
// frame. Metal callbacks never access host video memory or the core object.
- (uint64_t)az205SubmitVisibleCandidate:(const uint8_t *)pixels
    sourceWidth:(unsigned)width sourceHeight:(unsigned)height
    sourcePitch:(size_t)pitch rgba:(BOOL)rgba
    destinationWidth:(unsigned)dw destinationHeight:(unsigned)dh
    fullStereo:(BOOL)wide {
    const char *disable=getenv("AZAHAR_V205_DISABLE_METAL_PRESENT");
    if(disable && strcmp(disable,"1")==0) return 0;
    if(!_gameLoaded || !pixels || !Az191ValidFrame(width,height) ||
       pitch < (size_t)width*4u) return 0;
    const NSInteger factor=std::max((NSInteger)1,_az191Resolution);
    if(factor<2 || factor>6) return 0;
    const unsigned expectedW=(unsigned)factor*(wide?kAz197FullWidth:kNativeWidth);
    const unsigned expectedH=(unsigned)factor*kNativeHeight;
    // Do not overwrite pillarboxed or compact-stereo presentation. The
    // OpenEmu window remains host-controlled, sometimes locked at 400px.
    if(width!=expectedW || height!=expectedH ||
       dw!=(wide?kAz197FullWidth:kNativeWidth) || dh!=kNativeHeight ||
       (wide && Az198HasCompactFullStereoLayout(width,height))) return 0;
    if(!_az202ProbeDevice || !_az202ProbeQueue || !_az203FitPipeline) return 0;
    if(!_az205Present) _az205Present=std::make_shared<Az205PresentState>();
    const std::shared_ptr<Az205PresentState> state=_az205Present;
    if(state->disabled.load(std::memory_order_acquire)) return 0;
    const uint64_t sequence=state->frameSequence.fetch_add(1,std::memory_order_relaxed)+1u;
    // Per-mode pilot: 120 submissions per factor/stereo pair, sampled every
    // other eligible frame; never more than two total GPU tasks in flight.
    unsigned stereo=0;
    if([_az191Stereo isEqualToString:@"side-by-side"]) stereo=1;
    else if([_az191Stereo isEqualToString:@"side-by-side-full"]) stereo=2;
    else if([_az191Stereo isEqualToString:@"anaglyph"]) stereo=3;
    const unsigned idx=(unsigned)(factor-1)+6u*stereo;
    if((sequence&1u)==0u || state->modeSubmitted[idx].load()>=120u)
        return sequence;
    unsigned prev=state->inFlight.load(std::memory_order_acquire);
    while(prev<2u && !state->inFlight.compare_exchange_weak(prev,prev+1u,
          std::memory_order_acq_rel,std::memory_order_acquire)) {}
    if(prev>=2u) {
        state->skippedBusy.fetch_add(1);
        return sequence;
    }
    if(state->modeSubmitted[idx].load()>=120u) {
        state->inFlight.fetch_sub(1);
        return sequence;
    }
    // Include depth to prevent reuse across modes with identical geometry.
    const unsigned mode=(unsigned)factor+16u*stereo+128u*(unsigned)_az195Depth;
    const MTLPixelFormat fmt=rgba?MTLPixelFormatRGBA8Unorm:MTLPixelFormatBGRA8Unorm;
    MTLTextureDescriptor *sd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:fmt
                             width:width height:height mipmapped:NO];
    sd.storageMode=MTLStorageModeShared; sd.usage=MTLTextureUsageShaderRead;
    MTLTextureDescriptor *dd=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:fmt
                             width:dw height:dh mipmapped:NO];
    dd.storageMode=MTLStorageModePrivate;
    dd.usage=MTLTextureUsageShaderWrite | MTLTextureUsageShaderRead;
    id<MTLTexture> src=[_az202ProbeDevice newTextureWithDescriptor:sd];
    id<MTLTexture> dst=[_az202ProbeDevice newTextureWithDescriptor:dd];
    const size_t aligned=(((size_t)dw*4u)+255u)&~(size_t)255u;
    id<MTLBuffer> out=[_az202ProbeDevice newBufferWithLength:aligned*(size_t)dh
                        options:MTLResourceStorageModeShared];
    if(!src || !dst || !out) {
        state->inFlight.fetch_sub(1); state->disabled.store(true);
        AzTrace("V205 METAL_DISABLE reason=ALLOC fallback=V199");
        return sequence;
    }
    [src replaceRegion:MTLRegionMake2D(0,0,width,height)
        mipmapLevel:0 withBytes:pixels bytesPerRow:pitch];
    const std::array<unsigned,5> xs={0u,dw/4u,dw/2u,3u*dw/4u,dw-1u};
    const std::array<unsigned,5> ys={0u,dh/4u,dh/2u,3u*dh/4u,dh-1u};
    uint8_t wanted[100];
    for(unsigned y=0;y<5;++y) for(unsigned x=0;x<5;++x)
        Az203CPUReferenceSample(pixels,width,height,pitch,dw,dh,xs[x],ys[y],
                               wanted+4u*(y*5u+x));
    NSData *reference=[NSData dataWithBytes:wanted length:sizeof(wanted)];
    id<MTLCommandBuffer> cb=[_az202ProbeQueue commandBuffer];
    id<MTLComputeCommandEncoder> compute=[cb computeCommandEncoder];
    if(!cb || !compute) {
        state->inFlight.fetch_sub(1); state->disabled.store(true);
        AzTrace("V205 METAL_DISABLE reason=ENCODER fallback=V199");
        return sequence;
    }
    [compute setComputePipelineState:_az203FitPipeline];
    [compute setTexture:src atIndex:0];
    [compute setTexture:dst atIndex:1];
    [compute dispatchThreadgroups:MTLSizeMake((dw+7u)/8u,(dh+7u)/8u,1u)
            threadsPerThreadgroup:MTLSizeMake(8u,8u,1u)];
    [compute endEncoding];
    id<MTLBlitCommandEncoder> blit=[cb blitCommandEncoder];
    if(!blit) {
        state->inFlight.fetch_sub(1); state->disabled.store(true);
        AzTrace("V205 METAL_DISABLE reason=BLIT fallback=V199");
        return sequence;
    }
    [blit copyFromTexture:dst sourceSlice:0 sourceLevel:0
        sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(dw,dh,1)
        toBuffer:out destinationOffset:0 destinationBytesPerRow:aligned
        destinationBytesPerImage:aligned*(size_t)dh options:MTLBlitOptionNone];
    [blit endEncoding];
    const unsigned modeSubmission=state->modeSubmitted[idx].fetch_add(1)+1u;
    state->submitted.fetch_add(1);
    if(modeSubmission==1u) {
        char line[240];
        snprintf(line,sizeof(line),"V205 METAL_HANDOFF_BEGIN selected=%ld stereo=%u source=%ux%u target=%ux%u frame_budget=120 sample_period=2 max_inflight=2 no_wait=YES",
            (long)factor,stereo,width,height,dw,dh);
        AzTrace(line);
    }
    id<MTLTexture> keptSrc=src,keptDst=dst;
    id<MTLBuffer> keptOut=out;
    NSData *keptReference=reference;
    [cb addCompletedHandler:^(id<MTLCommandBuffer> done) {
        (void)keptSrc; (void)keptDst;
        bool valid=done.status==MTLCommandBufferStatusCompleted &&
                   keptOut.contents && keptReference.bytes;
        if(valid) {
            const uint8_t *a=(const uint8_t *)keptOut.contents;
            const uint8_t *b=(const uint8_t *)keptReference.bytes;
            for(unsigned y=0;y<5 && valid;y++) for(unsigned x=0;x<5 && valid;x++) {
                const uint8_t *got=a+(size_t)ys[y]*aligned+(size_t)xs[x]*4u;
                const uint8_t *want=b+4u*(y*5u+x);
                for(unsigned c=0;c<4;++c)
                    if(abs((int)got[c]-(int)want[c])>2) valid=false;
            }
        }
        if(valid) {
            std::vector<uint8_t> frame((size_t)dw*dh*4u);
            const uint8_t *base=(const uint8_t *)keptOut.contents;
            for(unsigned y=0;y<dh;++y) {
                uint8_t *row=frame.data()+(size_t)y*dw*4u;
                memcpy(row,base+(size_t)y*aligned,(size_t)dw*4u);
                if(rgba) for(unsigned x=0;x<dw;++x)
                    std::swap(row[x*4u],row[x*4u+2u]);
            }
            {
                std::lock_guard<std::mutex> lock(state->mutex);
                if(sequence>state->readySequence) {
                    state->readyPixels.swap(frame);
                    state->readyW=dw; state->readyH=dh;
                    state->readySourceW=width; state->readySourceH=height;
                    state->readyMode=mode; state->readySequence=sequence;
                }
            }
            state->verified.fetch_add(1);
            state->modeVerified[idx].fetch_add(1);
        } else {
            state->rejected.fetch_add(1);
            state->disabled.store(true);
            AzTrace("V205 METAL_DISABLE reason=PIXEL_OR_GPU_ERROR fallback=V199");
        }
        state->finished.fetch_add(1);
        const unsigned modeFinished=state->modeFinished[idx].fetch_add(1)+1u;
        state->inFlight.fetch_sub(1);
        if(modeFinished==120u) {
            char msg[280];
            const unsigned pass=state->modeVerified[idx].load();
            snprintf(msg,sizeof(msg),"V205 GPU_BATCH_RESULT selected=%ld stereo=%u submitted=%u completed=%u verified=%u busy_global=%u visible_global=%u wait=NONE status=%s",
                (long)factor,stereo,state->modeSubmitted[idx].load(),modeFinished,
                pass,state->skippedBusy.load(),state->visible.load(),
                pass==120u?"PASS":"FAIL");
            AzTrace(msg);
        }
    }];
    [cb commit]; // No wait, ever.
    return sequence;
}

- (void)az205MaybePresentVerifiedFrame:(uint8_t *)destination
    width:(unsigned)dw height:(unsigned)dh
    sourceWidth:(unsigned)sw sourceHeight:(unsigned)sh
    sequence:(uint64_t)sequence fullStereo:(BOOL)wide {
    (void)wide;
    if(!destination || !sequence || !_az205Present ||
       _az205Present->disabled.load()) return;
    const std::shared_ptr<Az205PresentState> state=_az205Present;
    if(!state->mutex.try_lock()) return; // Nonblocking; v199 frame remains.
    unsigned stereo=0;
    if([_az191Stereo isEqualToString:@"side-by-side"]) stereo=1;
    else if([_az191Stereo isEqualToString:@"side-by-side-full"]) stereo=2;
    else if([_az191Stereo isEqualToString:@"anaglyph"]) stereo=3;
    const unsigned mode=(unsigned)std::max((NSInteger)1,_az191Resolution)
            +16u*stereo+128u*(unsigned)_az195Depth;
    // No stale images across mode changes, wrong-sized output, or GPU latency
    // greater than two frames. Never reuse a frame already presented.
    const bool fresh=state->readySequence>state->lastPresented &&
        sequence>=state->readySequence && sequence-state->readySequence<=2u;
    const bool match=state->readyMode==mode && state->readyW==dw &&
        state->readyH==dh && state->readySourceW==sw &&
        state->readySourceH==sh &&
        state->readyPixels.size()==(size_t)dw*dh*4u;
    if(fresh && match) {
        memcpy(destination,state->readyPixels.data(),state->readyPixels.size());
        state->lastPresented=state->readySequence;
        const unsigned visible=state->visible.fetch_add(1)+1u;
        if(visible==1u || visible%30u==0u) {
            char msg[230];
            snprintf(msg,sizeof(msg),"V205 METAL_VISIBLE count=%u source=%ux%u output=%ux%u age_frames=%llu fallback=AVAILABLE status=PASS",
                visible,sw,sh,dw,dh,(unsigned long long)(sequence-state->readySequence));
            AzTrace(msg);
        }
    } else if(state->readySequence>state->lastPresented && !fresh) {
        state->stale.fetch_add(1);
    }
    state->mutex.unlock();
}

#pragma mark - Video

- (OEGameCoreRendering)gameCoreRendering
{
    return OEGameCoreRenderingBitmap;
}

- (const void *)videoBuffer
{
    static unsigned v18GetterCalls = 0;
    if (v18GetterCalls++ < 4) {
        char line[200];
        snprintf(line, sizeof(line), "V18 OPENEMU videoBuffer call=%u ptr=%p size=%dx%d capacity=%zu",
                 v18GetterCalls, (void *)_videoBuffer, (int)_videoSize.width, (int)_videoSize.height, _videoBufferCapacity);
        AzTrace(line);
    }
    return _videoBuffer;
}

- (const void *)getVideoBufferWithHint:(void *)hint
{
    static unsigned v18HintCalls = 0;
    if (v18HintCalls++ < 4) {
        char line[200];
        snprintf(line, sizeof(line), "V18 OPENEMU bufferHint call=%u hint=%p old=%p size=%dx%d",
                 v18HintCalls, hint, (void *)_videoBuffer, (int)_videoSize.width, (int)_videoSize.height);
        AzTrace(line);
    }
    // v197: do not adopt host-owned hints of unknown capacity. This avoids
    // invalidating OpenEmu's cached bitmap address during live stereo switching.
    if (hint && hint != _videoBuffer && v18HintCalls<=8)
        AzTrace("V197 OPENEMU_HINT ignored=1 reason=STABLE_OWNED_FRAMEBUFFER");
    return _videoBuffer;
}

- (OEIntSize)bufferSize
{
