#pragma mark - Save states

- (NSData *)serializeStateWithError:(NSError **)outError
{
    if (!_gameLoaded)
        return nil;

    size_t size = _retroSerializeSize();
    if (!size)
        return nil;

    NSMutableData *data = [NSMutableData dataWithLength:size];
    if (!_retroSerialize(data.mutableBytes, size)) {
        if (outError)
            *outError = [NSError errorWithDomain:OEGameCoreErrorDomain
                                            code:OEGameCoreCouldNotSaveStateError
                                        userInfo:nil];
        return nil;
    }

    char diag190[160];
    snprintf(diag190,sizeof(diag190),"V190 SAVE_STATE_SERIALIZE bytes=%zu status=PASS",size);
    AzTrace(diag190);
    return data;
}

- (BOOL)deserializeState:(NSData *)state error:(NSError **)outError
{
    if (!_gameLoaded)
        return NO;

    BOOL ok = _retroUnserialize(state.bytes, state.length);
    if (!ok && outError)
        *outError = [NSError errorWithDomain:OEGameCoreErrorDomain
                                        code:OEGameCoreCouldNotLoadStateError
                                    userInfo:nil];
    char diag190[160];
    snprintf(diag190,sizeof(diag190),"V190 SAVE_STATE_DESERIALIZE bytes=%lu status=%s",
             (unsigned long)state.length,ok?"PASS":"FAIL");
    AzTrace(diag190);
    return ok;
}

- (void)saveStateToFileAtPath:(NSString *)fileName
        completionHandler:(void (^)(BOOL, NSError *))block
{
    NSData *state = [self serializeStateWithError:nil];
    BOOL ok = state && [state writeToFile:fileName options:NSDataWritingAtomic error:nil];
    // Save-state write is caller-initiated and atomic; do not mutate emulator
    // state with a speculative self-test. Never print the user's save path.
    char audit212[180];
    snprintf(audit212,sizeof(audit212),"V212 SAVE_FILE_WRITE bytes=%lu atomic=1 status=%s",
             (unsigned long)(state ? state.length : 0),ok?"PASS":"FAIL");
    AzTrace(audit212);
    if (block)
        block(ok, ok ? nil : [NSError errorWithDomain:OEGameCoreErrorDomain
                                                  code:OEGameCoreCouldNotSaveStateError
                                              userInfo:nil]);
}

- (void)loadStateFromFileAtPath:(NSString *)fileName
          completionHandler:(void (^)(BOOL, NSError *))block
{
    NSData *state = [NSData dataWithContentsOfFile:fileName];
    // A deserialize result is meaningful only when OpenEmu actually requests
    // restoring a previously written state, not when querying serialize_size.
    BOOL ok = state && state.length > 0 && [self deserializeState:state error:nil];
    char audit212[180];
    snprintf(audit212,sizeof(audit212),"V212 SAVE_FILE_READ bytes=%lu status=%s",
             (unsigned long)(state ? state.length : 0),ok?"PASS":"FAIL");
    AzTrace(audit212);
    if (block)
        block(ok, ok ? nil : [NSError errorWithDomain:OEGameCoreErrorDomain
                                                  code:OEGameCoreCouldNotLoadStateError
                                              userInfo:nil]);
}

#pragma mark - NDS/3DS input

- (void)setNDSButton:(OENDSButton)button pressed:(BOOL)pressed
{
    if (button < OENDSButtonCount)
        _buttons[button] = pressed;
    // Record controller events, not an assumed mapping. This distinguishes a
    // missing OpenEmu control binding from a libretro input sampling error.
    if(button==OENDSButtonStart || button==OENDSButtonSelect) {
        const bool start=(button==OENDSButtonStart);
        if(start) {
            if(pressed){++gAz189StartPressEvents;gAz189StartLatchUntilPoll=0;}
            else {++gAz189StartReleaseEvents;gAz189StartLatchUntilPoll=gAz111InputPolls+2u;}
        } else {
            if(pressed){++gAz189SelectPressEvents;gAz189SelectLatchUntilPoll=0;}
            else {++gAz189SelectReleaseEvents;gAz189SelectLatchUntilPoll=gAz111InputPolls+2u;}
        }
        char event189[240];
        snprintf(event189,sizeof(event189),
          "V189 RESPONDER_BUTTON key=%s event=%s enum=%u poll=%llu active=%u",
          start?"START":"SELECT",pressed?"DOWN":"UP",(unsigned)button,
          gAz111InputPolls,(unsigned)gAzV188HardwarePromoted);
        AzTrace(event189);
    }
}

- (oneway void)didPushNDSButton:(OENDSButton)button forPlayer:(NSUInteger)player
{
    (void)player;
    [self setNDSButton:button pressed:YES];
}

- (oneway void)didReleaseNDSButton:(OENDSButton)button forPlayer:(NSUInteger)player
{
    (void)player;
    [self setNDSButton:button pressed:NO];
}

// Cross-process callbacks from 3DS-System-Plugin v12. The system plugin
// maps its numeric UI key IDs to NDS compatible button IDs explicitly.
- (oneway void)didChange3DSAnalogAxis:(NSUInteger)axis value:(float)value forPlayer:(NSUInteger)player
{
    if (player != 1 && player != 0) return; // OpenEmu player indexes differ by adapter
    if (axis >= 4 || !std::isfinite(value)) return;
    const float clamped = std::max(-1.0f,std::min(1.0f,value));
    const int16_t quantized=(int16_t)std::lround(clamped*32767.0f);
    int16_t *target[4]={&_axisX,&_axisY,&_cStickX,&_cStickY};
    *target[axis]=quantized;
    ++gAz190AnalogEvents[axis];
    if(gAz190AnalogEvents[axis]<=12 || (gAz190AnalogEvents[axis]%240)==0){
        char diag190[220];
        snprintf(diag190,sizeof(diag190),"V190 ANALOG_FROM_SYSTEM axis=%lu raw=%.3f quantized=%d events=%u",
                 (unsigned long)axis,(double)value,(int)quantized,gAz190AnalogEvents[axis]);
        AzTrace(diag190);
    }
}

- (oneway void)didChange3DSExtraButton:(NSUInteger)button pressed:(BOOL)pressed forPlayer:(NSUInteger)player
{
    if ((player!=1 && player!=0) || button>=2) return;
    _buttons[14u+button]=pressed;
    ++gAz190ExtraEvents[button];
    char diag190[180];
    snprintf(diag190,sizeof(diag190),"V190 EXTRA_BUTTON name=%s pressed=%u events=%u",
             button==0?"ZL":"ZR",(unsigned)pressed,gAz190ExtraEvents[button]);
    AzTrace(diag190);
}

- (oneway void)didTouchScreenPoint:(OEIntPoint)point
{
    /*
     * OpenEmu reports the point in the core's video coordinate space.
     * Azahar's libretro pointer interface uses signed 16-bit coordinates:
     * -32768..32767 maps across the entire output framebuffer.
     */
    int width = MAX(_videoSize.width, 1);
    int height = MAX(_videoSize.height, 1);

    int x = MAX(0, MIN(width - 1, point.x));
    int y = MAX(0, MIN(height - 1, point.y));

    _touchX = (int16_t)(((double)x / (double)(width - 1)) * 65535.0 - 32768.0);
    _touchY = (int16_t)(((double)y / (double)(height - 1)) * 65535.0 - 32768.0);
    _touchPressed = YES;
}

- (oneway void)didReleaseTouch
{
    _touchPressed = NO;
}

